insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-01','marketing','النمو يجي من عميلات جدد وقليلات الزيارة','يرى Sharp أن العلامات تكبر أساسًا بزيادة عدد المشترين، لا بتعميق ولاء الموجودين، وأن أغلب مشتري أي علامة يشترون منها قليلًا وعلى فترات متباعدة.','لا تبنون كل التسويق على العميلات الدائمات. أغلب الـ٦٠٠٠ عميلة غالبًا يزورون مرة أو مرتين في السنة، وهذول هم مخزون النمو. الحملات اللي توصل لنساء الأحساء عمومًا (مو بس متابعات الحساب) هي اللي تزيد عدد العميلات.','بدل حملة «عرض خاص للعميلات المميزات» فقط، حملة عامة قبل العيد تعرّف بخدمة الحمام المغربي لأي امرأة في الأحساء.','عدد العميلات المختلفات اللي زرن خلال ١٢ شهر، ونسبة العميلات الجدد من إجمالي الحجوزات، ومصادر «كيف عرفتنا؟».','لما يثبت عدد العميلات الجدد شهر بعد شهر، أو لما يصير معظم الدخل من نفس الوجوه.','مدارس أخرى (Godin، والتسويق المستهدف عند Kotler) تركز على فئة محددة وعلى الولاء. الخلاف حقيقي، والحل العملي: الولاء مهم للتشغيل، لكن لا تتوقعون منه وحده نمو كبير.',array['sharp-hbg']::text[],'evidence',array['جذب','عميلات جدد','انتشار','نمو','Byron Sharp']::text[],'campaigns',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-02','marketing','خلّوا الصالون أول اسم يجي على البال','الحضور الذهني يعني أن تخطر العلامة على بال المشترية في لحظة الحاجة، ويُبنى قبل الشراء بالتكرار والتواجد المستمر، مو بحملة وحدة.','ربطوا اسم بيوتفريش بلحظات محددة: «عندي عرس»، «شعري تعب من الصبغة»، «أبي أرتاح بعد الدوام». انشروا محتوى ثابت على مدار السنة، مو بس وقت العروض، عشان لما تجي اللحظة يكون اسمكم جاهز.','سلسلة شهرية ثابتة في إنستقرام «قبل المناسبة بأسبوع» تربط الصالون بلحظة التجهيز لأي مناسبة.','نسبة اللي يقولون في «كيف عرفتنا؟» إنهم سمعوا عنكم أو شافوكم قبل، وعدد عمليات البحث باسم الصالون في ملف قوقل للنشاط التجاري.','لما تلاحظون أن الحجوزات ترتفع وقت الإعلان وتنزل بعده مباشرة.',null,array['sharp-hbg']::text[],'evidence',array['حضور ذهني','وعي','تكرار','علامة تجارية']::text[],'campaigns',1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-03','marketing','سهّلوا الوصول والحجز قدر الإمكان','الحضور المادي يعني أن تكون العلامة سهلة الإيجاد والشراء، ويعدّ Sharp الظهور في بحث قوقل جزءًا منه مثل مساحة الرف في المتجر.','كل خطوة زيادة بين الرغبة والحجز تخسّركم عميلة. تأكدوا أن ملف قوقل محدّث (الموقع، الساعات، الخدمات، رابط الحجز في ركاز)، وأن رابط الحجز واضح في البايو والواتساب. الخدمات المنزلية نفسها توسّع الحضور المادي للعميلة اللي ما تقدر تطلع.','رابط حجز مباشر لخدمة «مكياج منزلي للمناسبات» في ملف قوقل وفي ردود الواتساب الجاهزة.','نسبة الحجوزات من الرابط المباشر، وعدد النقرات على «الاتجاهات» و«الاتصال» في إحصائيات ملف قوقل، ونسبة الاستفسارات اللي تتحول لحجز.','لما يكثر السؤال «وين موقعكم؟» أو «كيف أحجز؟»، أو لما تكون الاستفسارات كثيرة والحجوزات قليلة.',null,array['sharp-hbg']::text[],'evidence',array['حضور مادي','حجز','قوقل','خدمات منزلية','سهولة']::text[],null,2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-04','marketing','أصول مميِّزة ثابتة لا تتغير كل موسم','تشرح Romaniuk أن العناصر الحسية للعلامة (لون، شكل، شعار، نبرة) تصير أصولًا فقط إذا كانت مشهورة (يعرفها كثير من الناس) وفريدة (ما ترتبط بمنافس)، وهذا يحتاج ثبات طويل.','اختاروا لون أو عنصرين وكرروهم في كل منشور وكرت وكيس وواجهة. لا تغيرون الهوية مع كل مصمم أو موسم، لأن التغيير يمسح اللي بنيتوه في ذاكرة الناس.','نفس اللون ونفس شكل إطار الصور في كل محتوى قبل وبعد، بحيث تعرف المتابعة إنه من بيوتفريش قبل ما تقرأ الاسم.','اختبار بسيط: اعرضوا على مجموعة عميلات عنصر بدون الاسم واسألوهم لمين؟ وراقبوا نسبة اللي يعرفونه مع الوقت.','قبل أي تغيير في الشعار أو الألوان، وعند التفكير في الامتياز التجاري (الفرانشايز) لأن الفروع تحتاج هوية ثابتة.','لا تعتبرون أي عنصر «أصل» لمجرد أنكم تحبونه؛ لازم يكون الناس يعرفونه ويربطونه بكم أنتم فقط.',array['romaniuk-dba']::text[],'evidence',array['هوية بصرية','أصول مميزة','شعار','ألوان','فرانشايز']::text[],'writer',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-05','marketing','قسّموا السوق للفهم لا للإقصاء','يشرح Kotler وKeller التجزئة (ديموغرافية، سلوكية، حسب المناسبة والحاجة) لاختيار الشرائح وتصميم العرض. ويقبل Sharp التجزئة كأداة تحليل لكنه يعارض الاستهداف اللي يستبعد بقية السوق.','استخدموا بيانات العميلات لفهم الشرائح: عرائس، أمهات، موظفات، طالبات جامعة. صمموا رسالة مناسبة لكل شريحة، لكن خلّوا الحضور العام موجّه لكل نساء الأحساء.','رسالة مختلفة للموظفات (مواعيد مسائية سريعة) وللأمهات (خدمة منزلية)، مع بقاء الإعلان العام للجميع.','متوسط الفاتورة وتكرار الزيارة لكل شريحة من بيانات ركاز، ومصدر «كيف عرفتنا؟» لكل شريحة.','لما تصممون باقة أو عرض جديد، أو لما ترون شريحة نموها أبطأ من غيرها.','الخلاف بين مدرسة Kotler (الاستهداف) ومدرسة Ehrenberg-Bass (الانتشار الواسع) قائم؛ اختبروا بأرقامكم بدل افتراض أن الاستهداف أفضل.',array['kotler-mm','sharp-hbg']::text[],'consensus',array['تجزئة','شرائح','استهداف','عميلات']::text[],'campaigns',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-06','marketing','فكرة واحدة واضحة في ذهن العميلة','يرى Ries وTrout أن التموضع يحدث في ذهن العميل لا في المنتج، وأن الذهن مزدحم فالعلامة تحتاج فكرة واحدة بسيطة تملكها بدل قائمة مزايا.','اختاروا كلمة أو فكرة واحدة تبون الناس يقولونها عنكم في الأحساء، وكرروها في كل مكان. قائمة «شعر وأظافر وبشرة وليزر ومكياج» ما تميزكم لأن كل صالون يقولها.','لو اخترتوا «الدقة في الصبغة والعناية بالشعر المتعب»، يكون أغلب المحتوى والتدريب وقصص العميلات حول هذي الفكرة.','اسألوا العميلات الجدد: «وش سمعتي عنا قبل تجين؟» وراقبوا كم وحدة تذكر نفس الفكرة.','لما يكون المحتوى مشتت، أو لما تسألون الفريق «وش يميزنا؟» ويعطونكم أجوبة مختلفة.','الفكرة لازم تكون حقيقية وتقدرون تثبتونها في الخدمة كل يوم، وإلا التقييمات بتكذّبها.',array['ries-trout-pos']::text[],'practice',array['تموضع','تميز','رسالة','هوية']::text[],'writer',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-07','marketing','اكتبوا بيان التموضع بعناصره','يقترح Kotler وKeller أن يحدد التموضع: الفئة المرجعية اللي تتنافسون فيها، ونقاط التشابه الأساسية اللي لازم تكون عندكم، ونقاط الاختلاف اللي تميزكم.','حددوا: هل منافسكم الصالونات الكبيرة أو الأخصائيات المنزليات أو العيادات؟ نقاط التشابه: النظافة والتعقيم والالتزام بالموعد. نقاط الاختلاف: شي تتفوقون فيه فعلًا وتدعمه تقييماتكم.','بيان داخلي من سطرين يستخدمه الكاتب الذكي: «لنساء الأحساء اللي يبون نتيجة مضمونة في الشعر، بيوتفريش صالون متكامل يتميز بـ... لأن...».','كلمات تتكرر في التقييمات على قوقل؛ إذا نقطة الاختلاف ما تظهر في كلام العميلات، فهي ما وصلت.','قبل حملة كبيرة، أو قبل التفكير في الامتياز التجاري.','إذا نقاط التشابه ناقصة (مثل التأخير أو النظافة)، ما تنفع أي نقطة اختلاف.',array['kotler-mm']::text[],'consensus',array['تموضع','منافسة','تميز','استراتيجية']::text[],'writer',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-08','marketing','وازنوا بين بناء العلامة والتنشيط','يبيّن Binet وField أن بناء العلامة (محتوى عاطفي وانتشار واسع وأثر بطيء) والتنشيط (عروض ودعوات حجز وأثر سريع) يحتاجون بعض، وأن الاستغناء الكامل عن أي واحد منهم يضر الفعالية.','لا تخلون كل الجهد عروض وخصومات. خصصوا جزء ثابت لمحتوى يبني اسم الصالون (قصص عميلات، خبرة الأخصائيات، أجواء المكان)، وجزء لدعوات حجز مباشرة في المواسم.','في رمضان: محتوى عن تجربة الاسترخاء في الحمام المغربي طول الشهر (بناء)، ورسالة حجز مواعيد العيد في آخر أسبوعين (تنشيط).','التنشيط: حجوزات الأسبوع نفسه. البناء: نمو العميلات الجدد والبحث باسم الصالون على مدى أشهر، مو أيام.','عند وضع خطة التسويق الفصلية أو السنوية.','النسبة المشهورة (مثل ٦٠:٤٠) متوسط من بيانات علامات كبيرة وليست قاعدة ثابتة؛ المؤلفان نفسهما يقولان إن التوازن يختلف حسب الفئة وحجم العلامة ومرحلتها. وSharp يعترض على تقسيم التنشيط لدفعات متقطعة لأن التقاط المشترية الجاهزة نشاط يومي.',array['binet-field-eic','sharp-hbg']::text[],'evidence',array['بناء علامة','تنشيط','عروض','ميزانية','تخطيط']::text[],'campaigns',7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-09','marketing','لا تحكمون على التسويق بنتيجة أسبوع','يحذّر Binet وField من الاعتماد على مقاييس قصيرة المدى فقط، لأنها تميل لتفضيل التنشيط والخصومات وتُخفي أثر بناء العلامة اللي يظهر لاحقًا.','لا تلغون محتوى بناء العلامة لأنه ما جاب حجوزات في نفس الأسبوع. وكثرة الخصومات تعوّد العميلات ينتظرون العرض وتضغط على متوسط الفاتورة.','بدل خصم ٣٠٪ كل شهر، خصم موسمي مرخّص مرتين أو ثلاث في السنة، والباقي قيمة مضافة (مثل جلسة ترطيب مع الصبغة).','متوسط الفاتورة ونسبة الحجوزات اللي تجي فقط وقت العروض، على مدى ٦-١٢ شهر.','لما تلاحظون أن الحجوزات تموت بين العروض، أو أن العميلات يسألون «متى العرض الجاي؟».',null,array['binet-field-eic']::text[],'evidence',array['خصومات','تسعير','قياس','مدى طويل']::text[],'campaigns',8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-10','marketing','الدليل الاجتماعي الحقيقي فقط','يشرح Cialdini أن الناس في حالة التردد يقتدون بتصرف أمثالهم. ويفرّق بين الاستخدام الأخلاقي (إبراز دليل موجود فعلًا) والاستغلال (اختلاق دليل).','عندكم تقييم ★4.8 وآلاف العميلات؛ هذا دليل حقيقي، أبرزوه. استخدموا تقييمات وصور عميلات حقيقيات بإذنهن، ويُفضَّل من نفس الشريحة (عرائس للعرائس، أمهات للأمهات).','منشور يجمع ثلاث تقييمات حقيقية من قوقل عن الصبغة مع رابط الحجز، بدون تعديل كلام العميلة.','نسبة التحويل من مشاهدة المنشور إلى حجز، وذكر «شفت التقييمات» في «كيف عرفتنا؟».','لما تطلقون خدمة جديدة أو تستهدفون عميلات ما يعرفونكم.','ممنوع شراء متابعين أو تقييمات أو اختلاق عبارات «أكثر من ألف عروس» بدون رقم مؤكد من بياناتكم.',array['cialdini-influence']::text[],'evidence',array['دليل اجتماعي','تقييمات','إقناع','أخلاقيات']::text[],'reviews',9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-11','marketing','الندرة صادقة أو لا تُستخدم','يذكر Cialdini أن الشي يبدو أثمن لما يكون محدودًا أو قد يضيع. واستخدامه الأخلاقي يكون فقط لما تكون الندرة حقيقية.','مواعيد ليلة العيد وموسم الأعراس محدودة فعلًا بعدد الأخصائيات والساعات؛ قولوا هذا بصدق. لكن «باقي ٣ مقاعد» وهي مو صحيحة تضر الثقة ويمكن تدخل في التضليل.','رسالة: «مواعيد مكياج ليلة العيد تفتح الأحد، وعندنا عدد محدود حسب الأخصائيات المتاحات» مع رابط الحجز.','سرعة امتلاء المواعيد بعد الإعلان، ونسبة الإلغاء (الندرة المصطنعة ترفع الحجز المتسرع والإلغاء).','قبل المواسم المزدحمة: العيدين، الإجازات، موسم الأعراس حسب بياناتكم.','العرض المحدود بوقت إذا كان تخفيض سعر يحتاج ترخيص من وزارة التجارة (انظري mkt-27).',array['cialdini-influence']::text[],'evidence',array['ندرة','مواعيد','عيد','إقناع','أخلاقيات']::text[],'campaigns',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-12','marketing','أبرزوا خبرة الأخصائيات الحقيقية','مبدأ السلطة عند Cialdini: الناس يثقون بالخبير الموثوق. والأخلاقي أن تُعرض الخبرة الحقيقية بوضوح، لا أن تُصطنع ألقاب.','عرّفوا العميلات بالأخصائيات: سنوات الخبرة، الدورات المعتمدة، التخصص. في الخدمات الحساسة مثل الليزر والبشرة، الشهادات والتراخيص عنصر ثقة أساسي.','بطاقة لكل أخصائية في الموقع والإنستقرام: اسمها، تخصصها، شهاداتها، ونموذج من شغلها بإذن العميلة.','عدد الحجوزات اللي تطلب أخصائية بالاسم، ونسبة الحجز في الخدمات عالية السعر.','لما تسوقون لخدمات عالية السعر أو حساسة، أو لما تنضم أخصائية جديدة.','لا تستخدمون ألقاب مثل «دكتورة» أو «خبيرة عالمية» إلا إذا كانت مثبتة.',array['cialdini-influence']::text[],'evidence',array['سلطة','خبرة','ثقة','أخصائيات','ليزر']::text[],'writer',11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-13','marketing','القرب والانتماء لأهل الأحساء','يذكر Cialdini أن الناس يتأثرون أكثر بمن يحبونه ويشبههم (الإعجاب)، وبمن يشاركهم هوية «نحن» (الوحدة، المبدأ المضاف في الطبعة الموسعة).','أنتم صالون من الأحساء ولأهل الأحساء؛ هذي ميزة ما يقدر صالون سلسلة ينسخها. استخدموا لهجة قريبة، ووجوه الفريق الحقيقية، ومناسبات المنطقة.','محتوى «من بيتنا لبيتكم» يعرض الفريق بأسمائهم ويحتفل بمناسبات محلية، بنبرة أحسائية لطيفة.','التفاعل بالتعليقات والردود (مو بس اللايكات)، ونسبة الإحالات من الأقارب والصديقات.','لما ينافسكم صالون جديد أو سلسلة كبيرة بأسعار أقل.','الانتماء يُبنى بالصدق والاستمرار؛ الشعارات المحلية بدون خدمة تليق تنقلب ضدكم.',array['cialdini-influence']::text[],'evidence',array['انتماء','محلي','الأحساء','إعجاب','وحدة']::text[],'writer',12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-14','marketing','أعطوا قيمة قبل ما تطلبون','مبدأ المعاملة بالمثل عند Cialdini: الناس يميلون لرد الجميل. ويكون أقوى لما تكون الهدية مفيدة وشخصية وغير متوقعة.','قدموا قيمة حقيقية بدون شرط: نصيحة عناية بعد الصبغة، فحص بسيط لحالة الشعر، أو لمسة صغيرة غير متوقعة في الزيارة.','بعد البروتين، رسالة واتساب (للعميلات اللي وافقن على التواصل) فيها نصائح مخصصة لأول أسبوعين بدون أي عرض.','نسبة رجوع العميلات خلال الفترة المعتادة للخدمة، وعدد التقييمات اللي تذكر الاهتمام.','بعد الخدمات الكبيرة (صبغة، بروتين، عروس) وعند استقبال عميلة جديدة.','لا تربطون الهدية بكتابة تقييم إيجابي؛ هذا مخالف لسياسة قوقل (انظري mkt-24).',array['cialdini-influence']::text[],'evidence',array['معاملة بالمثل','هدايا','عناية','ولاء']::text[],'gifts',13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-15','marketing','خطوة صغيرة تقود لالتزام أكبر','مبدأ الالتزام والاتساق عند Cialdini: لما يتخذ الشخص خطوة صغيرة باختياره، يميل يكمل بما يتسق معها.','خلّوا أول خطوة سهلة وواضحة: حجز استشارة قصيرة، أو تأكيد الموعد بنفسها. التأكيد الصريح من العميلة يقلل الغياب.','في باقة العروس: موعد تجربة مكياج أولًا، ثم العميلة تختار باقتها بنفسها وتأكدها.','نسبة الغياب والإلغاء قبل وبعد طلب التأكيد، ونسبة تحويل الاستشارات إلى باقات.','لما ترتفع نسبة الغياب أو لما تكون الخدمة عالية السعر وتحتاج تجربة.','الالتزام لازم يكون اختيار حر؛ الضغط أو الشروط المخفية يضر السمعة.',array['cialdini-influence']::text[],'evidence',array['التزام','تأكيد موعد','غياب','عرائس']::text[],'appts',14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-16','marketing','شي يحب الناس يتكلمون عنه','في إطار STEPPS عند Berger: الناس يشاركون اللي يخليهم يبانون بشكل حلو (العملة الاجتماعية)، واللي يتذكرونه لأن شي حولهم يذكّرهم فيه (المحفزات).','اصنعوا لحظة تخلي العميلة تحب تشارك تجربتها، واربطوا الصالون بمحفز يومي متكرر في حياة نساء الأحساء.','ركن تصوير جميل بإضاءة جيدة بعد المكياج (عملة اجتماعية)، وربط محتوى «ترتيبة الخميس» بالصالون (محفز أسبوعي).','عدد المنشنات والقصص اللي تذكر الصالون، ونسبة «صديقة/قريبة» في «كيف عرفتنا؟».','لما يكون الكلام الشفهي ضعيف رغم رضا العميلات.',null,array['berger-contagious']::text[],'evidence',array['كلام شفهي','مشاركة','STEPPS','محفزات']::text[],'writer',15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-17','marketing','محتوى مفيد وعاطفي وفيه قصة','بقية STEPPS: العاطفة (خاصة المشاعر عالية الإثارة)، والقيمة العملية، والقصص اللي تحمل الرسالة. ودراسة Berger وMilkman (٢٠١٢) وجدت أن المحتوى الإيجابي وعالي الإثارة يُشارك أكثر، والمحتوى المفيد كذلك.','المحتوى اللي ينتشر يكون إما مفيد جدًا تحب العميلة ترسله لصديقتها، أو يثير مشاعر قوية مثل الدهشة. وخلّوا اسم الصالون جزء من القصة نفسها مو ملصق عليها.','ريلز «٣ أخطاء تخرّب الصبغة في البيت» بصوت الأخصائية، أو قصة عروس من التوتر إلى الفرحة (بإذنها).','عدد الإرسالات والحفظ للمنشور (مو بس المشاهدات)، والحجوزات اللي تذكر المنشور.','عند تخطيط محتوى الشهر.','المشاعر السلبية مثل الخوف من العيوب تنتشر أحيانًا لكنها تضر صورة علامة تجميل تقوم على الراحة والثقة.',array['berger-contagious']::text[],'evidence',array['محتوى','قصص','قيمة عملية','انتشار','مشاعر']::text[],'writer',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-18','marketing','خلّوا التجربة ظاهرة للناس','من STEPPS عند Berger: الأشياء اللي يشوفها الناس علنًا تنتشر أكثر من اللي تصير بالخفاء، لأن الناس يقلدون اللي يشوفونه.','خدمات الصالون تصير داخل مكان خاص، فصمموا أثر ظاهر يطلع مع العميلة: كيس مميز، كرت عناية أنيق، أو شي يبان في صورها.','كيس بلون الصالون الثابت لمنتجات العناية، وبطاقة صغيرة بموعد الصيانة القادم للصبغة.','عدد العميلات الجدد اللي قالوا «شفت عند صديقتي»، والمنشنات بصور فيها أصول الصالون.','لما تكون التقييمات ممتازة لكن الانتشار محدود.','خصوصية العميلات أولًا؛ لا تنشرون أي صورة من داخل الصالون فيها عميلة بدون إذن صريح.',array['berger-contagious']::text[],'evidence',array['ظهور','تغليف','كلام شفهي','خصوصية']::text[],null,17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-19','marketing','خدمة تستاهل الكلام عنها','يرى Godin في البقرة البنفسجية أن الإعلان وحده ما يكفي في سوق مزدحم، وأن المنتج اللي يستاهل يُذكر هو اللي ينتشر، والآمن والعادي يُنسى.','فكروا في تفصيلة واحدة في تجربة بيوتفريش تخلي العميلة تقول «لازم تجربينه». قد تكون في الاستقبال، أو طريقة الاستشارة، أو اللي يصير بعد الخدمة.','استشارة شعر مكتوبة تأخذها العميلة معها بعد الصبغة الأولى، فيها تحليل حالة شعرها وخطة العناية.','عدد التقييمات اللي تذكر التفصيلة بالاسم، وعدد الإحالات بعدها.','لما تشبه تجربتكم تجربة المنافسين، أو لما تحسون أن الإعلان يزيد والنتيجة ثابتة.','الشي اللافت لازم يخدم العميلة؛ الغرابة بدون قيمة تجيب انتباه مؤقت فقط.',array['godin-purplecow']::text[],'practice',array['تميز','تجربة العميلة','ابتكار','كلام شفهي']::text[],null,18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-20','marketing','اخدموا فئة محددة بعمق','في This Is Marketing يدعو Godin إلى اختيار أصغر جمهور قابل للحياة، وخدمته بعمق لدرجة يتكلمون عنكم، بدل محاولة إرضاء الكل.','مفيد في الخدمات المتخصصة: اختاروا فئة واحدة (مثل العرائس، أو صاحبات الشعر المتعب من الصبغات) وصمموا لها تجربة كاملة ومحتوى خاص.','«برنامج العروس» من أول استشارة قبل العرس بأشهر إلى يوم الزفاف، مع خطة عناية بالبشرة والشعر.','عدد العرائس سنويًا، ومتوسط الفاتورة لهن، ونسبة اللي جن بإحالة من عروس سابقة.','عند تصميم خدمة متخصصة أو باقة عالية القيمة.','هذا يعارض جزئيًا رأي Sharp (mkt-01). الجمع العملي: التخصص للباقات المميزة، والانتشار الواسع للصالون ككل.',array['godin-tim','sharp-hbg']::text[],'practice',array['تخصص','فئة محددة','عرائس','باقات']::text[],'campaigns',19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-21','marketing','العميلة البطلة والصالون المرشد','إطار StoryBrand عند Miller: الرسالة الواضحة تجعل العميل بطل القصة، والعلامة مرشدًا يفهم مشكلته ويعطيه خطة بسيطة ودعوة واضحة للفعل، ويوضح النجاح المتوقع.','اكتبوا الرسائل من مشكلة العميلة لا من مزايا الصالون: وش يضايقها؟ كيف نفهمها؟ وش الخطوات الثلاث؟ وش الزر اللي تضغطه؟','«شعرك تعب من الصبغات؟ أخصائياتنا يبدأون بفحص حالة شعرك، ثم خطة علاج، ثم متابعة. احجزي استشارتك من الرابط.»','نسبة النقر على رابط الحجز في المنشورات المكتوبة بهذي الصيغة مقارنة بغيرها.','عند كتابة صفحات الخدمات أو الإعلانات أو الردود الجاهزة.','هو إطار كتابة من الممارسة المهنية، مو نظرية مثبتة بدراسات؛ اختبروه بأرقامكم.',array['miller-storybrand']::text[],'practice',array['كتابة','رسالة','قصة','دعوة للفعل','صفحات الخدمات']::text[],'writer',20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-22','marketing','وش المهمة اللي تحجزنا عشانها؟','نظرية المهام المطلوب إنجازها عند Christensen: العميل «يستأجر» المنتج لينجز تقدمًا في ظرف معين، والمهمة تشمل جوانب وظيفية وعاطفية واجتماعية، وفهمها أهم من خصائص العميل.','عميلتان بنفس العمر قد تحجزان نفس الخدمة لمهمتين مختلفتين: وحدة «أبي أطلع بأحلى صورة في عرس أختي»، وثانية «أبي ساعة راحة من البيت». الرسالة والتجربة تختلف.','في موسم الأعراس: المهمة ليست مكياج فقط بل «ما أتوتر يوم العرس»، فالتسويق يركز على التنظيم والتجربة المسبقة والالتزام بالوقت.','اسألوا عند الحجز سؤال اختياري «وش المناسبة؟» وحللوا الأجوبة مع متوسط الفاتورة والرجوع.','عند تصميم باقة أو موسم (أعراس، عيد، تخرج)، أو لما تكون خدمة مبيعاتها ضعيفة رغم جودتها.','مواسم الأعراس والتخرج تختلف من سنة لسنة؛ حددوها من بيانات حجوزاتكم لا من الانطباع.',array['christensen-cal']::text[],'practice',array['مهام العميل','عرائس','موسم الأعراس','دوافع','باقات']::text[],'seasons',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-23','marketing','العميلة المُحالة قيمتها أعلى','وجدت دراسة Schmitt وSkiera وVan den Bulte (٢٠١١) أن العملاء المُحالين أعلى ربحية وأكثر بقاءً من غيرهم، وأن فارق البقاء يستمر بينما فارق الهامش يقل مع الوقت، وأن الفارق يختلف بين الشرائح فيُنصح ببرنامج انتقائي.','برنامج إحالة بسيط يستاهل: هدية للعميلة المحيلة وللصديقة الجديدة. ركزوا البرنامج على العميلات الأكثر رضا والخدمات اللي تناسب الإحالة (مثل العرائس وصديقاتهن).','«عرّفي صديقتك على بيوتفريش: هي تحصل جلسة ترطيب مع أول صبغة، وأنتِ مثلها في زيارتك القادمة.»','سجّلوا في ركاز مصدر «إحالة» واسم المحيلة، ثم قارنوا رجوع المُحالات ومتوسط فاتورتهن بغيرهن من بياناتكم.','لما يكون الرضا عالي (★4.8) لكن نسبة الجدد قليلة.','الدراسة على عملاء بنك في ألمانيا؛ لا تنقلون الأرقام للصالون، قيسوا بنفسكم. والهدية تكون على الإحالة، لا على كتابة تقييم.',array['schmitt-2011']::text[],'evidence',array['إحالة','صديقة','ولاء','جذب','مكافآت']::text[],'vip',22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-24','marketing','اطلبوا التقييم من الكل وبدون مقابل','سياسة قوقل تمنع تقديم أي حافز (خصم، خدمة مجانية، مال) مقابل تقييم أو تعديله أو حذفه، وتمنع منع التقييمات السلبية أو طلب التقييم من الراضيات فقط، وتعتبر تقييمات الموظفات تضارب مصالح.','اطلبوا التقييم من كل عميلة بنفس الطريقة بعد الخدمة، بدون فلترة «اللي مبسوطة بس». ولا تكتب الأخصائيات أو أقاربهن تقييمات.','رسالة موحدة بعد كل زيارة: «رأيك يهمنا ويساعد غيرك، تقدرين تقيمين تجربتك من هنا» مع الرابط، بدون أي هدية مشروطة.','عدد التقييمات الجديدة شهريًا، ونسبة الرد عليها، وثبات المتوسط.','دائمًا، وخصوصًا عند التفكير في أي حملة لزيادة التقييمات.','مخالفة السياسة قد تؤدي لحذف تقييمات أو تقييد الملف. والخطر الأكبر على صالون بسمعة ★4.8 هو خسارة الثقة.',array['google-reviews-policy']::text[],'practice',array['تقييمات','قوقل','سياسات','أخلاقيات','مراجعات']::text[],'reviews',23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-25','marketing','عدد التقييمات أهم من الكمال','وجد مركز Spiegel أن وجود أول خمس مراجعات يرفع احتمال الشراء بشكل كبير ثم تقل الفائدة الإضافية، وأن احتمال الشراء يبلغ ذروته غالبًا عند تقييمات بين ٤٫٠ و٤٫٧ ثم ينخفض كلما اقترب من ٥، لأن الكمال يبدو غير قابل للتصديق.','تقييمكم ٤٫٨ ممتاز، فلا تخافون من تقييم ٣ أو ٤ نجوم صادق. الأهم استمرار تدفق تقييمات حديثة لكل خدمة، والرد المهني على السلبية يبين للقارئة كيف تتعاملون مع المشاكل.','رد على تقييم ٣ نجوم عن التأخير: اعتذار محدد، وش تغيّر، ودعوة للتواصل المباشر.','عدد التقييمات الحديثة (آخر ٩٠ يوم)، ونسبة التقييمات اللي عليها رد، ونمو الحجوزات من ملف قوقل.','عند مراجعة السمعة شهريًا، أو لما يجي تقييم سلبي ويتوتر الفريق.','البيانات من تجارة إلكترونية لمنتجات، مو صالونات؛ الاتجاه مفيد لكن الأرقام لا تُنقل كما هي.',array['spiegel-reviews']::text[],'evidence',array['تقييمات','سمعة','ثقة','رد على المراجعات']::text[],'reviews',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-26','marketing','التقييمات تفرق أكثر للمستقل','وجد Luca أن ارتفاع نجمة واحدة في تقييم Yelp يرتبط بزيادة في إيرادات المطاعم المستقلة، بينما لا أثر يُذكر للمطاعم التابعة لسلاسل، لأن الناس يعتمدون على المراجعات أكثر لما ما يعرفون العلامة.','بيوتفريش صالون مستقل، فالتقييمات عندكم أداة جذب رئيسية وليست تفصيلة. ولو صار عندكم فروع امتياز لاحقًا، سيعتمد كل فرع جديد على تقييماته الخاصة في البداية.','خطة لكل فرع مستقبلي: هدف تقييمات في أول ٣ أشهر عبر طلب موحد من كل عميلة.','عدد التقييمات ومتوسطها لكل فرع، مقابل نمو العميلات الجدد من ملف قوقل.','عند فتح فرع، أو عند إطلاق خدمة جديدة ما لها تقييمات.','الدراسة على مطاعم في سياتل؛ الآلية معقولة للصالون لكن النسبة لا تُنقل.',array['luca-yelp']::text[],'evidence',array['تقييمات','مستقل','فرانشايز','إيراد','Yelp']::text[],'reviews',25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-27','marketing','رخصة التخفيض قبل الإعلان','وزارة التجارة تصدر تراخيص التخفيضات إلكترونيًا، وتطلب أن يكون التخفيض مرخصًا وحقيقيًا وغير مضلل، مع عرض الترخيص الذي تستطيع المستهلكة التحقق منه بمسح الباركود، وتراقب الأسعار قبل وبعد التخفيض ضمن نظام مكافحة الغش التجاري.','أي إعلان «خصم» في رمضان أو العيد أو اليوم الوطني أو الجمعة البيضاء يحتاج تتأكدون قبله من متطلبات الترخيص لنشاطكم، وتعرضون السعر قبل وبعد بشكل صادق.','قبل حملة خصم على الصبغة في العيد: إصدار الترخيص، ووضع الباركود في المنشور وعند الاستقبال، وتثبيت السعر الأصلي المعتاد.','وجود ترخيص لكل حملة خصم في سجل الحملات، وصفر شكاوى أو ملاحظات من الجهات.','قبل أي إعلان فيه نسبة خصم أو «عرض لفترة محدودة».','المصادر المتاحة تتكلم غالبًا عن المنتجات والمتاجر؛ تأكدوا من الوزارة مباشرة هل خصومات الخدمات تحتاج نفس الترخيص. البديل الآمن: قيمة مضافة بدل تخفيض سعر، مع التحقق أيضًا.',array['moc-discounts']::text[],'law',array['تخفيضات','ترخيص','وزارة التجارة','عروض','رمضان','الجمعة البيضاء']::text[],'rules',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-28','marketing','المؤثرات بترخيص «موثوق» فقط','الهيئة العامة لتنظيم الإعلام تشترط رخصة «موثوق» للأفراد اللي يعلنون عن منتجات أو خدمات في المملكة عبر المنصات، وحذّرت المنشآت من التعامل مع معلنين غير مرخصين. ويُستثنى من يروج لمنتجه أو خدمته من حسابه الشخصي.','قبل أي تعاون مدفوع مع مشهورة أو مؤثرة (بمال أو خدمة مجانية)، تأكدوا من رخصة «موثوق» سارية، واكتبوا اتفاق مكتوب، واحفظوا نسخة. وغير السعوديات يحتجن ترتيب نظامي مختلف عبر وكالة أو كيان مرخص.','تعاون مع مؤثرة أحسائية: التحقق من رخصتها، عقد مكتوب يحدد المحتوى ومنع الفلاتر اللي تبالغ في النتيجة، وكود حجز خاص لقياس الأثر.','عدد الحجوزات بكود المؤثرة، ونسبة رجوع العميلات اللي جن منها، مقارنة بالتكلفة.','قبل أي تعاون إعلاني مع شخص له متابعين.','لا نذكر هنا مبالغ الغرامات لأن المصادر المتاحة صحفية؛ ارجعوا للهيئة مباشرة. وأخصائيات الصالون اللي ينشرن شغلهن في حساباتهن: تأكدوا من وضعهن مع الهيئة لأن الاستثناء للمنتج أو الخدمة الشخصية.',array['gamr-mawthooq']::text[],'law',array['مؤثرات','مشاهير','موثوق','ترخيص','إعلان']::text[],'rules',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-29','marketing','رسائل تسويق بموافقة وإلغاء سهل','بموجب نظام حماية البيانات الشخصية ولائحته، إرسال المواد الإعلانية يحتاج موافقة مسبقة من المستلمة، مع وسيلة واضحة وسهلة لإيقاف الرسائل، وتعريف واضح بالجهة المرسلة.','رقم العميلة في ركاز للحجز لا يعني موافقتها على رسائل العروض. اطلبوا موافقة منفصلة وواضحة (خانة غير محددة مسبقًا)، وخلّوا كل رسالة واتساب أو SMS تذكر اسم الصالون وطريقة إيقاف الرسائل، ونفّذوا طلب الإيقاف فورًا.','في نموذج الحجز: «أبي توصلني عروض ونصائح بيوتفريش على الواتساب» (اختياري). وفي آخر كل رسالة: «لإيقاف الرسائل أرسلي: إيقاف».','نسبة العميلات الموافقات من الإجمالي، ونسبة طلبات الإيقاف لكل حملة (ارتفاعها مؤشر إزعاج)، وعدد الحجوزات من الرسائل.','قبل أي حملة رسائل جماعية، وعند إعداد نموذج الحجز.','بيانات مثل حالة البشرة أو حساسية الليزر قد تُعد بيانات صحية حساسة؛ لا تستخدمونها في استهداف الرسائل بدون مراجعة قانونية. ولم نذكر أرقام مواد لأن الترقيم يختلف بين النظام واللائحة.',array['pdpl']::text[],'law',array['واتساب','رسائل','موافقة','خصوصية','حماية البيانات']::text[],'winback',28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-30','marketing','قبل وبعد: صدق وإذن وبدون فلاتر','أوضحت هيئة معايير الإعلان البريطانية أن الفلاتر بحد ذاتها ليست مشكلة، لكن استخدامها بطريقة تبالغ في نتيجة الخدمة أو المنتج مضلل، وأن المعلن مسؤول عن فلاتر المؤثرين في إعلاناته.','صور قبل وبعد تكون بنفس الإضاءة والزاوية وبدون فلاتر أو تعديل يغير النتيجة. وخذوا إذن مكتوب صريح من العميلة لكل استخدام، واحترموا رغبة اللي ما تبي وجهها يبان.','تصوير الصبغة قبل وبعد تحت نفس الإضاءة في ركن ثابت، مع إخفاء الوجه افتراضيًا إلا بإذن.','صفر شكاوى من عميلات عن صور منشورة، ونسبة اللي يقولون إن النتيجة طابقت المتوقع (من استبيان بعد الخدمة).','في كل محتوى نتائج: شعر، بشرة، ليزر، مكياج عرائس.','الإرشاد بريطاني ويُستخدم هنا كمعيار أخلاقي مقارن؛ صور العميلات بيانات شخصية تخضع لنظام حماية البيانات السعودي، ومبالغة النتائج قد تدخل في التضليل.',array['asa-filters','pdpl']::text[],'practice',array['قبل وبعد','فلاتر','صور','أخلاقيات','خصوصية','إذن']::text[],'writer',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-31','marketing','محتوى أصلي يناسب كل مساحة','شرح رئيس إنستقرام أن لكل مساحة إشاراتها: القصص تعتمد على قرب العلاقة، والريلز تعتمد على المشاهدة الكاملة وإعادة المشاركة، وأن الريلز المنشورة سابقًا أو اللي عليها علامة مائية أو منخفضة الجودة تقل رؤيتها.','صوّروا محتواكم بأنفسكم بجودة جيدة، ولا تعيدون نشر ريلز من منصات ثانية بعلامتها المائية. استخدموا القصص للعميلات الحاليات (مواعيد متاحة، كواليس)، والريلز للوصول لنساء جديدات.','ريلز قصير أصلي لأخصائية تشرح تفصيلة واحدة في العناية بالشعر، وقصة يومية «مواعيد اليوم المتاحة».','الإرسالات والحفظ والمشاهدة الكاملة للريلز من إحصائيات الحساب، والحجوزات من رابط البايو.','عند تخطيط المحتوى، أو لما ينزل الوصول فجأة.','خوارزميات المنصات تتغير؛ هذا من شرح رسمي بتاريخ ٢٠٢٣. وما لقينا مصدر رسمي موثوق مماثل لتيك توك فلم نضع له مبادئ خاصة.',array['ig-ranking']::text[],'practice',array['إنستقرام','ريلز','قصص','محتوى','خوارزمية']::text[],'writer',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-32','marketing','تقويم مواسم مبني على بياناتكم','التجزئة حسب المناسبة عند Kotler وKeller تعني أن الحاجة نفسها تتغير بالمناسبة. ووزارة التجارة تعامل مواسم مثل رمضان والعيد واليوم الوطني كمواسم تخفيضات مرخصة، والجمعة البيضاء موسم تسوق إقليمي معروف.','ابنوا تقويم سنوي: رمضان (تغير أوقات الذروة للمساء والليل)، ما قبل العيدين (ذروة مكياج وشعر)، الإجازات وتقويم وزارة التعليم (الطالبات والأمهات)، والجمعة البيضاء واليوم الوطني (عروض مرخصة). حددوا ذروة الأعراس من حجوزاتكم الفعلية.','قبل رمضان بشهر: تمديد ساعات العمل للمساء، فتح حجز مواعيد العيد مبكرًا، ومحتوى «تجهيزات العيد» في آخر أسبوعين.','مقارنة الحجوزات والإيراد وساعات الذروة لكل موسم بنفس الموسم في السنة الماضية من بيانات ركاز.','قبل كل موسم بـ٤-٦ أسابيع، وعند مراجعة السنة.','مواعيد المواسم الهجرية تتغير كل سنة ميلادية؛ اربطوا التقويم بالهجري. ولا تفترضون أن كل موسم يحتاج خصم.',array['kotler-mm','moc-discounts']::text[],'practice',array['مواسم','رمضان','عيد','الجمعة البيضاء','اليوم الوطني','تقويم','أعراس']::text[],'seasons',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('mkt-33','marketing','العميلة الغائبة غالبًا مو زعلانة','يوضح Sharp أن أغلب المشترين يشترون من العلامة على فترات متباعدة، فقلة الزيارة غالبًا طبيعة الشراء وليست انقطاع ولاء، والحل في البقاء حاضرًا في ذهنهم.','العميلة اللي ما رجعت من ٦ أشهر غالبًا ما تركتكم؛ هي بس ما احتاجت أو نسيت. تذكير لطيف في التوقيت المناسب للخدمة (موعد تجديد الصبغة مثلًا) أنفع من خصم كبير.','للموافقات على الرسائل فقط: «صار لك فترة من آخر صبغة، تحبين نحجز لك موعد مع أخصائيتك؟» مع الرابط.','نسبة الرجوع خلال ٣٠ يوم من التذكير، مقارنة بمجموعة ما وصلها تذكير.','لما تطول الفترة بين زيارات العميلة عن المعتاد لخدمتها.','الرسائل للموافقات فقط مع إلغاء سهل (mkt-29). ولو العميلة تركت بسبب تجربة سيئة، فالحل اعتذار وتواصل شخصي مو رسالة جماعية.',array['sharp-hbg','pdpl']::text[],'evidence',array['استرجاع','عميلات غائبات','تذكير','ولاء']::text[],'winback',32) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-01','sales','الاستشارة أسئلة قبل ما تكون عرض','يرى Rackham أن البائع الناجح في الصفقات الكبيرة يسأل أكثر مما يعرض، ويتدرج من أسئلة الوضع الحالي إلى أسئلة المشكلة، ويقلل أسئلة الوضع لأنها تملّ العميل ولا تضيف له شي.','قبل أي خدمة كبيرة (صبغة جذرية، بروتين، باقة ليزر) تخصص الأخصائية دقائق للأسئلة: وش يزعجك في شعرك الحين؟ متى آخر مرة صبغتي؟ وش تستخدمين في البيت؟ وتاخذ بيانات الوضع الأساسية (آخر صبغة، الحساسية) من ملف العميلة في ركاز بدل ما تسألها من جديد.','عميلة جاية تبي «تقصير أطراف»، الأخصائية تسأل عن التقصف والجفاف وتكتشف إنها تكوي يوميًا، فتطلع الحاجة الحقيقية: علاج وحماية من الحرارة، لا مجرد قص.','متوسط الفاتورة للعميلات اللي أخذن استشارة مقابل اللي ما أخذن، ونسبة العميلات اللي يرجعن لنفس الخدمة خلال الموعد المقترح.','لما تكون الفاتورة واقفة على خدمة واحدة، أو لما تشتكي العميلات إن النتيجة ما كانت اللي يبونه.','بحث Rackham تجاري وغير محكّم وأصله صفقات كبيرة بين الشركات؛ الاستشارة الطويلة ما تناسب خدمة سريعة مثل تنظيف أظافر.',array['rackham-spin']::text[],'practice',array['استشارة','أسئلة','احتياج','متوسط الفاتورة','بيع استشاري']::text[],'sales',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-02','sales','خلّي العميلة هي اللي تقول الفايدة','أسئلة «الأثر» تكبّر حجم المشكلة في ذهن العميل، وأسئلة «العائد من الحل» تخليه يقول بنفسه ليش الحل يفيده، وهذا أقوى من أن البائع يعدد المزايا.','بعد ما تتضح المشكلة، الأخصائية تسأل: لو صار شعرك يمسك التسريحة أسبوع كامل، وش يفرق معك؟ العميلة لما تشرح الفايدة بكلامها تقتنع أكثر، والأخصائية ما تحتاج تضغط.','عروس قبل الزواج بشهرين: «لو بشرتك صافية بدون كونسيلر ثقيل يوم الملكة، وش يعني لك؟» فتطلب هي جلسات البشرة التحضيرية.','نسبة قبول الخدمات المقترحة في الاستشارة، تسجلها الاستقبال في ركاز (اقتُرح/قُبل).','لما تكون الخدمة المقترحة غالية نسبيًا أو جديدة على العميلة.','السؤال لازم يكون صادق ومرتبط بمشكلة حقيقية قالتها العميلة؛ تحويله لسيناريو محفوظ يبان تلاعب.',array['rackham-spin']::text[],'practice',array['استشارة','قيمة','عرائس','بشرة','إقناع']::text[],'sales',1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-03','sales','الاعتراض غالبًا سببه عرض الحل بدري','يلاحظ Rackham أن كثير من الاعتراضات تنتج عن تقديم الحل ومزاياه قبل ما يقتنع العميل إن عنده مشكلة تستاهل، فالوقاية من الاعتراض أنفع من مهارة الرد عليه.','لا تبدأ الأخصائية بـ«عندنا بروتين جديد ممتاز» قبل ما تفهم وضع الشعر. إذا كثرت عبارة «غالي» أو «بفكر» في خدمة معينة، راجعوا هل الأخصائيات يقترحنها قبل الاستشارة.','بدل ما الاستقبال تعرض باقة الليزر أول ما تدخل العميلة، الأخصائية تسأل عن الطريقة الحالية وتكرارها وتكلفتها الشهرية، وبعدها تعرض الباقة.','عدد مرات «بفكر وأرد لكم» مقابل الحجز الفعلي، لكل خدمة ولكل أخصائية.','لما ترتفع الاعتراضات على السعر في خدمة بعينها رغم إن سعرها منافس.',null,array['rackham-spin']::text[],'practice',array['اعتراضات','سعر','استشارة','تدريب الأخصائيات']::text[],'sales',2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-04','sales','البيع الكبير غير البيع الصغير','يفرّق Rackham بين البيع الصغير السريع والبيع الكبير اللي يحتاج قرار وتفكير، ويرى أن أساليب الإغلاق الضاغطة قد تنفع في الصغير وتضر في الكبير.','قسّموا خدماتكم: إضافات صغيرة (رسمة أظافر، ماسك سريع) تُعرض بجملة وحدة وبدون ضغط، وقرارات كبيرة (باقة ليزر، باقة عروس، بروتين) تحتاج استشارة ووقت تفكير ومتابعة لطيفة.','باقة العروس ما تنغلق في نفس الزيارة؛ الاستقبال ترسل ملخص مكتوب بالخيارات وتتابع بعد يومين برسالة وحدة.','نسبة تحول الاستفسار لحجز في الباقات الكبيرة خلال أسبوعين من الاستشارة.','عند تصميم سكربت الاستقبال أو تدريب أخصائية جديدة.','التصنيف لكل صالون يختلف؛ حددوه من أسعاركم ومن مدة تردد عميلاتكم الفعلية.',array['rackham-spin']::text[],'practice',array['باقات','عرائس','ليزر','إغلاق','متابعة']::text[],'sales',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-05','sales','علّميها شي ما كانت تعرفه','تطرح The Challenger Sale أن أفضل البائعين يقدمون للعميل فكرة جديدة عن مشكلته تغيّر طريقة تفكيره، ثم يربطونها بالحل، بدل الاكتفاء ببناء علاقة ودية.','الأخصائية تشارك معلومة مهنية صحيحة ومفيدة: أثر الماء العسر أو الكي اليومي على الصبغة، أو ليش جلسات الليزر لازم تكون على فترات. المعلومة تبني ثقة، والاقتراح يجي بعدها طبيعي.','لعميلة تشتكي إن الصبغة تبهت بسرعة: تشرح الأخصائية علاقة الشامبو والحرارة بثبات اللون، ثم تقترح روتين بسيط ومنتج مناسب.','مبيعات منتجات العناية المنزلية المرتبطة بالخدمة، وتقييمات تذكر إن الأخصائية «فهّمتني».','لما تكون العلاقة مع العميلات قوية لكن المبيعات الإضافية ضعيفة.','النموذج مبني على بيع معقد بين الشركات (B2B)؛ في الصالون يكفي «التعليم» بلطف، و«أخذ السيطرة» أو خلق توتر بنّاء ما يناسب علاقة العميلة الشخصية. والمعلومة لازم تكون صحيحة علميًا، لا مبالغة تسويقية.',array['dixon-challenger']::text[],'practice',array['معلومة','ثقة','منتجات منزلية','صبغة','تعليم العميلة']::text[],'sales',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-06','sales','خاطبي صاحبة القرار وصاحبة الدفع','من عناصر Challenger تكييف الرسالة حسب كل شخص مشارك في القرار، لأن اهتمامات كل طرف تختلف.','في باقات العرايس والمناسبات كثيرًا ما تكون الأم أو الأخت شريكة في القرار أو الدفع. العروس يهمها الشكل والراحة، والأم يهمها الثقة والتنظيم والقيمة. جهزوا ملخصين مختلفين للباقة نفسها.','رسالة للعروس تركز على البروفة والنتيجة، ورسالة للأم تركز على الجدول وعدد الأخصائيات والتزام الموعد يوم الزواج.','نسبة إغلاق باقات العرايس، وعدد الحجوزات الجماعية (العروس + أهلها) في نفس المناسبة.','مواسم الزواجات والأعياد والحجوزات الجماعية.','أصل الفكرة تعدد صناع القرار في الشركات؛ لا تتجاوزون العروس نفسها، القرار النهائي لها.',array['dixon-challenger']::text[],'practice',array['عرائس','مناسبات','حجز جماعي','رسائل']::text[],'vip',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-07','sales','سعّري على القيمة مقارنة بالبديل','يرى Nagle وMüller أن السعر الصحيح يُبنى على القيمة الاقتصادية للعميل مقارنة بأقرب بديل متاح له، والتكلفة تحدد الحد الأدنى فقط.','لكل خدمة رئيسية حددوا البديل الحقيقي للعميلة في الأحساء: صالون منافس، خدمة منزلية مستقلة، منتج تستخدمه في البيت. ثم اسألوا: وش نقدم زيادة عن هذا البديل (نتيجة أطول، تعقيم، خبرة، راحة)؟ هذا الفرق هو اللي يبرر السعر.','إزالة الشعر بالليزر: البديل هو الشمع الشهري؛ احسبوا مع العميلة تكلفة ووقت الشمع على سنة مقابل الباقة.','هامش الربح لكل خدمة (من بيانات التكاليف في الموقع)، ونسبة الحجز بعد أي تعديل سعري.','عند إطلاق خدمة جديدة أو مراجعة قائمة الأسعار السنوية.','التسعير على القيمة ما يعني رفع السعر دائمًا؛ أحيانًا يكشف إن الخدمة مسعّرة أعلى من قيمتها عند شريحة معينة.',array['nagle-pricing']::text[],'consensus',array['تسعير','قيمة','منافسين','هامش','ليزر']::text[],'finance',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-08','sales','سياسة سعر ثابتة ما تكافئ المساومة','يؤكد Nagle أن توقعات العميل تتشكل من تصرفات المنشأة؛ إذا تعلم العميل أن الضغط أو التأجيل يجيب سعر أحسن، يصير السعر العادي غير مقبول عنده.','اكتبوا سياسة واضحة: متى يُعطى خصم ومن يملك الصلاحية (الشريكتين فقط مثلًا)، وما تعطيه الاستقبال لأن العميلة ألحّت. البديل عن الخصم: تقليل نطاق الخدمة أو اقتراح خيار أبسط.','عميلة تقول «صاحبتي أخذته أرخص»: الاستقبال تشرح الفرق أو تعرض خدمة أقصر بسعر أقل، بدل نزول السعر لنفس الخدمة.','نسبة الفواتير اللي فيها خصم يدوي ومتوسط الخصم، لكل موظفة، من تقارير ركاز.','لما تكثر الخصومات اليدوية أو تختلف الأسعار بين العميلات لنفس الخدمة.',null,array['nagle-pricing']::text[],'consensus',array['خصم','مساومة','سياسة','استقبال','صلاحيات']::text[],'sales',7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-09','sales','وضّحي القيمة قبل ما تذكرين الرقم','في إطار Nagle، توصيل القيمة مرحلة مستقلة: العميل ما يدفع على قيمة ما يعرفها، فلازم تُشرح بلغة تهمه قبل الحديث عن السعر.','في قائمة الأسعار والردود على الواتساب، كل خدمة كبيرة يرافقها سطر عن وش تشمل ومدة النتيجة المتوقعة، بدل رقم مجرد. الأخصائية تعرف تشرح الفرق بين بروتين وبروتين بجملتين.','ردّ الاستقبال على «بكم البروتين؟»: يشمل غسيل وتطبيق وسشوار، والنتيجة عادة كم أسبوع حسب نوع الشعر، والسعر كذا شامل الضريبة.','نسبة تحول استفسارات الأسعار في الواتساب إلى حجوزات.','لما يكون عدد الاستفسارات عالي والحجوزات قليلة.','لا تذكرون مدة نتيجة أو وعد ما تقدرون تضمنونه؛ اربطوه بنوع الشعر ومتابعة العناية.',array['nagle-pricing']::text[],'consensus',array['قيمة','واتساب','استفسارات','قائمة أسعار']::text[],'sales',8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-10','sales','السعر أقوى رافعة للربح','يشرح Simon أن تغيير السعر غالبًا يؤثر على الربح أكثر من تغيير مماثل في عدد العملاء أو التكاليف، لأن فرق السعر يروح مباشرة للربح، ولهذا يستاهل التسعير اهتمام الإدارة العليا.','بدل ما يكون الحل الوحيد زيادة عدد العميلات (والأخصائيات محدودات)، راجعوا تسعير الخدمات الأكثر طلبًا والمواعيد الممتلئة. القرار للشريكتين، مبني على أرقام الموقع لا على الإحساس.','خدمة السشوار محجوزة بالكامل في نهاية الأسبوع: تجربة تعديل بسيط على سعرها في هذي الأوقات وقياس الأثر على الإشغال والإيراد.','إجمالي الربح لكل خدمة قبل وبعد التعديل، وعدد الحجوزات، ونسبة الإلغاء.','لما تكون المواعيد ممتلئة والأرباح ما تتحسن، أو عند ارتفاع التكاليف.','الرفع بدون قيمة واضحة أو بشكل يبان استغلال يضر الثقة؛ اربطوه بمبدأ العدالة (sal-27).',array['simon-confessions']::text[],'consensus',array['تسعير','ربح','رفع السعر','إشغال']::text[],'finance',9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-11','sales','مركز السعر لازم يطابق التجربة','يناقش Simon أن المنشأة لازم تختار موقعها السعري (فاخر، متوسط، منخفض) وتكون كل تفاصيل التجربة منسجمة معه، لأن الخلط يربك العميل ويضعف الربح.','بتقييم ★4.8 وقاعدة عميلات كبيرة، حددوا: هل بيوتفريش خيار القيمة الممتازة أو الخيار الفاخر في الأحساء؟ بعدها خلّوا الضيافة وقائمة الأسعار والتغليف والعروض كلها تمشي على نفس الخط.','إذا الموقع فاخر، عروض «خصم ٥٠٪» المتكررة تتعارض معه؛ البديل هدايا أو ترقيات خدمة.','متوسط الفاتورة، ونسبة الحجوزات اللي تجي من عروض مقابل الحجوزات بالسعر الكامل.','عند تخطيط الهوية أو قبل التفكير في الامتياز التجاري (الفرانشايز).',null,array['simon-confessions']::text[],'consensus',array['تموضع','فاخر','هوية','فرانشايز','عروض']::text[],'finance',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-12','sales','صياغة الخسارة أقوى من صياغة المكسب','تقول نظرية الاحتمالات إن الناس يقيّمون النتائج كمكاسب وخسائر من نقطة مرجع، وإن الخسارة تؤثر أكثر من مكسب مماثل.','في رسائل المتابعة والتذكير، صياغة «لا تضيّعين نتيجة جلساتك» تكون أحيانًا أقوى من «احصلي على نتيجة أفضل». بس استخدموها بصدق وعلى شي فعلًا تملكه العميلة.','رسالة لعميلة ليزر تأخرت عن جلستها: موعدك القادم يحافظ على نتيجة الجلسات اللي خلصتيها، تبين نحجز لك؟','نسبة الرجوع للجلسة القادمة في الباقات، مقارنة نسختين من الرسالة (A/B) على فترتين.','لما يكثر التسرب في منتصف الباقات.','حجم النفور من الخسارة محل نقاش: Gal وRucker (2018، Journal of Consumer Psychology) يرون أنه أقل عمومية مما يُشاع. والتخويف المبالغ فيه أو الكاذب ممنوع أخلاقيًا ويضر السمعة.',array['kt-1979']::text[],'evidence',array['نفور من الخسارة','رسائل','تذكير','باقات','صياغة']::text[],'campaigns',11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-13','sales','الخصم المتكرر يغيّر نقطة المرجع','حسب نظرية الاحتمالات، العميل يحكم على السعر مقارنة بنقطة مرجعية في ذهنه؛ وإذا تعوّد على سعر العرض صار هو المرجع والسعر العادي يبان خسارة. وهذا ينسجم مع تحذير Nagle من تعليم العملاء انتظار الخصم.','قلّلوا الخصومات العامة على الخدمات الأساسية، وخلّوا العروض مرتبطة بمناسبة واضحة ووقت محدد. السعر العادي هو اللي يرسخ في الذاكرة.','بدل خصم دائم على الحمام المغربي، عرض محدد في موسم الصيف أو قبل رمضان فقط، والباقي بالسعر الكامل.','نسبة الحجوزات اللي تتركز داخل فترات العروض، وهل تقل الحجوزات بعد العرض مباشرة.','لما تلاحظون إن العميلات يحجزن فقط وقت العروض.',null,array['kt-1979','nagle-pricing']::text[],'evidence',array['نقطة مرجع','خصم','عروض','مواسم']::text[],'campaigns',12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-14','sales','أول رقم تشوفه العميلة يرسّي حكمها','وصف Tversky وKahneman تأثير الرسو: الرقم الأول المعروض يؤثر على التقديرات اللي بعده حتى لو ما له علاقة مباشرة.','في قائمة الأسعار وفي الاستشارة، ابدؤوا بالخيار الأشمل (الباقة الكاملة) ثم الخيارات الأبسط، فتبان الخيارات المتوسطة معقولة. وفي باقات العرايس اعرضوا الباقة الكاملة أول.','قسم الشعر في القائمة يبدأ بـ«باقة العناية الكاملة» ثم البروتين ثم الحمام الزيتي، بدل الترتيب من الأرخص.','توزيع الحجوزات بين مستويات الباقات قبل وبعد تغيير الترتيب.','عند تصميم القائمة أو صفحة الحجز.','الرسو من أكثر النتائج ثباتًا في التكرار (مشروع Many Labs 2014 كرره بنجاح)، لكن الرقم المرجعي لازم يكون خدمة حقيقية مطلوبة، لا سعر وهمي.',array['tk-1974']::text[],'evidence',array['رسو','قائمة أسعار','باقات','ترتيب']::text[],'sales',13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-15','sales','الخيار الطُعم: مفيد بحذر','وصف Huber وPayne وPuto (Journal of Consumer Research، 1982) أن إضافة خيار أضعف بوضوح من خيار آخر قد يزيد اختيار الخيار المتفوق عليه، وعرض Ariely أمثلة مشهورة على ذلك.','عند تصميم ثلاث مستويات لباقة، تأكدوا إن كل مستوى منطقي بذاته، وإن المستوى اللي تبونه يبان واضح القيمة مقارنة بجاره. لا تبنون استراتيجيتكم على هذا التأثير وحده.','باقة أظافر: «منكير» و«منكير + بديكير» و«منكير + بديكير + بارافين»، بفروق سعرية تخلي الوسطى أو الكاملة منطقية.','نسبة اختيار كل مستوى قبل وبعد تعديل الباقات.','عند بناء باقات متدرجة جديدة.','Frederick وLee وBaskin (2014) وجدوا أن التأثير يضعف كثيرًا أو يختفي في المواقف الواقعية والمعلومات المرئية؛ اعتبروه فرضية تختبرونها ببياناتكم.',array['ariely-pi','frederick-2014']::text[],'evidence',array['طعم','باقات','مستويات','تصميم العرض']::text[],'sales',14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-16','sales','جاذبية «مجانًا» تختلف عن الخصم','يعرض Ariely تجارب تشير إلى أن السعر صفر له جاذبية خاصة تتجاوز فرق السعر الفعلي، فإضافة شي مجاني قد تجذب أكثر من خصم بنفس القيمة.','بدل خصم صغير على الفاتورة، جرّبوا إضافة مجانية رخيصة التكلفة عليكم وعالية القيمة عند العميلة (ماسك شعر، رسمة ظفر وحدة)، بشرط تكون مرتبطة بخدمة أساسية.','حجز بروتين في أسبوع هادئ يجي معه ماسك ترطيب مجاني، بدل ٥٪ خصم.','نسبة الحجز في الفترة المستهدفة، وتكلفة الهدية مقارنة بقيمة الخصم المقابل.','لتنشيط الأيام الهادئة أو خدمة جديدة.','تجارب Ariely عن المجاني (منشورة مع Shampanier وMazar في Marketing Science 2007) مختبرية غالبًا. وتعامل «المجاني» يدخل ضمن العروض الترويجية، فراجعوا اشتراطات وزارة التجارة (sal-34).',array['ariely-pi']::text[],'evidence',array['مجاني','هدايا','عروض','أيام هادئة']::text[],'campaigns',15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-17','sales','الباقة المدفوعة مقدمًا حساب ذهني منفصل','يشرح Thaler أن الناس يوزعون فلوسهم على «حسابات» ذهنية، ويقيّمون كل صفقة داخل حسابها، فالدفعة الواحدة المقدمة تُحس بشكل مختلف عن دفع كل زيارة.','الباقات المدفوعة مقدمًا (ليزر، حمام مغربي شهري) تخلي كل زيارة لاحقة تُحس «مدفوعة»، فتسهّل الرجوع. اعرضوها على العميلات المنتظمات أصلًا، وبشروط واضحة للاستخدام والصلاحية.','باقة «٤ جلسات حمام مغربي» بتواريخ مقترحة مسجلة في ركاز من أول يوم.','نسبة استهلاك الباقات خلال صلاحيتها، ومعدل التجديد.','لما يكون عندكم عميلات يكررن نفس الخدمة بانتظام.',null,array['thaler-1985']::text[],'evidence',array['محاسبة ذهنية','باقات','دفع مقدم','ولاء']::text[],'vip',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-18','sales','الاستخدام يقل كلما بعد وقت الدفع','وجد Gourville وSoman أن أثر الدفع على الاستخدام يتلاشى مع الوقت: الاستخدام يرتفع بعد الدفع مباشرة ثم ينخفض، والدفعات الدورية تبقي التكلفة حاضرة وتدعم الاستمرار.','لا تكتفون ببيع الباقة؛ احجزوا الجلسات القادمة مع البيع، وذكّروا العميلة قبل كل موعد. للعضويات طويلة المدة فكروا بالدفع الشهري بدل السنوي إذا كان هدفكم الاستمرار والتجديد.','عضوية عناية شهرية تُدفع كل شهر، مع رسالة تذكير بالرصيد المتبقي في الباقة.','نسبة الجلسات المستهلكة من كل باقة شهريًا، ومعدل تجديد العضويات.','لما تلاحظون باقات تنتهي صلاحيتها بجلسات غير مستخدمة أو تجديد ضعيف.','الجلسات غير المستخدمة ممكن تبان ربح، لكنها تضعف رضا العميلة وتجديدها؛ لا تبنون أرباحكم عليها.',array['gourville-soman-1998']::text[],'evidence',array['باقات','عضوية','تجديد','تذكير','استهلاك']::text[],'vip',17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-19','sales','بطاقة الهدية تُصرف بنفسية الهدية','حسب المحاسبة الذهنية، الفلوس اللي تجي كهدية تُصرف بنفسية مختلفة عن الدخل العادي، وتُعامل كمساحة للدلال لا للضرورات.','اجعلوا بطاقات الهدايا تُستخدم في تجارب «دلع» (حمام مغربي، باقة عناية) لا مجرد رصيد نقدي، وصمموها بشكل يليق بمناسبات الأحساء (عيد، تخرج، ملكة، أم المولود).','بطاقة «يوم دلع» لصديقة العروس، مع اقتراح باقة محددة واسم المهدية.','عدد بطاقات الهدايا المباعة لكل موسم، ونسبة المستلمات اللي صرن عميلات راجعات بعد الاستخدام.','قبل الأعياد ومواسم التخرج والمناسبات.','ضريبيًا: حسب دليل ZATCA، القسيمة ذات القيمة الاسمية المؤهلة تُحتسب ضريبتها عند الاسترداد لا عند البيع؛ راجعوا التطبيق مع المحاسب. وحددوا الصلاحية وشروط الاستخدام بوضوح.',array['thaler-1985','zatca-retail']::text[],'evidence',array['هدايا','بطاقات هدية','مناسبات','ضريبة','قسائم']::text[],'gifts',18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-20','sales','الرقم الأيسر يحدد الإحساس بالسعر','بيّن Thomas وMorwitz أن الناس يتأثرون بأول رقم من اليسار في السعر، فيبان الفرق بين 199 و200 أكبر من حقيقته لأن الرقم الأول تغيّر.','في الخدمات اللي يقارنها الناس بالسعر (مانيكير، سشوار، تنظيف بشرة) ممكن يفيد السعر اللي تحت الحد المستدير. في الخدمات الفاخرة والباقات، السعر المستدير ينسجم أكثر مع الصورة الراقية.','سعر تنظيف البشرة الأساسي 149 بدل 150، بينما باقة العروس الكاملة سعرها مستدير.','حجوزات الخدمة قبل وبعد تغيير نهاية السعر، على فترة كافية ومع مراعاة الموسم.','عند مراجعة القائمة أو إطلاق خدمة تنافس على السعر.','مع إلزام عرض السعر شامل الضريبة، طبّقوا هذا على السعر النهائي اللي تشوفه العميلة لا على السعر قبل الضريبة.',array['thomas-morwitz-2005']::text[],'evidence',array['نهاية السعر','الرقم الأيسر','قائمة أسعار','تسعير نفسي']::text[],'finance',19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-21','sales','نهاية السعر تفيد أكثر لما المعلومة قليلة','في تجارب ميدانية، وجد Anderson وSimester أن الأسعار المنتهية بـ 9 رفعت الطلب، وكان الأثر أكبر في المنتجات الجديدة اللي ما عند العميل فكرة مسبقة عن سعرها.','الخدمات الجديدة (علاج جديد، تقنية أظافر جديدة) هي الأنسب لتجربة هذا الأسلوب، لأن العميلة ما عندها سعر مرجعي. الخدمات المعروفة سعرها في السوق أقل تأثرًا.','إطلاق «علاج فروة الرأس» الجديد بسعر ينتهي بـ 9 في أول ثلاث شهور، ومقارنة الطلب مع خدمة جديدة أخرى بسعر مستدير.','عدد الحجوزات في أول شهور الخدمة الجديدة.','عند إطلاق خدمات جديدة.','التجارب كانت على بيع منتجات بالكتالوج في أمريكا؛ أثرها على خدمات صالون في السعودية يحتاج اختبار من بياناتكم.',array['anderson-simester-2003']::text[],'evidence',array['نهاية السعر','خدمة جديدة','تجربة','إطلاق']::text[],'finance',20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-22','sales','طريقة كتابة السعر في القائمة تفرق','في تجربة على مطعم، أنفق الزبائن أكثر لما كانت الأسعار أرقام مجردة بدون رمز العملة، مقارنة برمز العملة أو كتابة السعر بالحروف؛ والتفسير المقترح أن تذكير العملة يذكّر بألم الدفع.','في القائمة المطبوعة أو الرقمية داخل الصالون، جرّبوا كتابة السعر رقمًا بسيطًا مع جملة عامة «جميع الأسعار بالريال وشاملة ضريبة القيمة المضافة»، ورتبوا الخدمات بأقسام واضحة بدل عمود أسعار طويل يشجع المقارنة بالسعر فقط.','قسم الشعر: اسم الخدمة وسطر وصف ثم الرقم بخط هادئ، بدون «ر.س» بجنب كل سطر.','متوسط الفاتورة قبل وبعد تغيير القائمة على فترات متقاربة الموسم.','عند إعادة تصميم قائمة الأسعار أو صفحة الحجز.','دراسة وحدة في مطعم واحد بعينة صغيرة؛ اعتبروها فكرة للاختبار. ولا تخفون السعر أو تخلونه غامض، فإظهار السعر الشامل للضريبة واجب (sal-33).',array['yang-kimes-2009']::text[],'evidence',array['قائمة أسعار','منيو','تصميم','عملة','ألم الدفع']::text[],'sales',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-23','sales','التجميع المختلط: الباقة بجانب الخدمة المنفردة','يميز Stremersch وTellis بين تجميع الأسعار وتجميع المنتجات، وبين التجميع الخالص (الباقة فقط) والمختلط (الباقة والمنفرد معًا)، ويريان أن المختلط غالبًا أكثر مرونة ويخدم شرائح مختلفة.','خلّوا كل خدمة متاحة منفردة، وقدموا بجانبها باقات منطقية لخدمات تُطلب عادة مع بعض. الباقة تخدم العميلة اللي تبي تجربة كاملة، والمنفرد يخدم اللي تبي شي محدد.','باقة «قبل المناسبة»: سشوار + مكياج + أظافر بسعر الباقة، مع بقاء كل خدمة متاحة بسعرها.','نسبة الفواتير اللي فيها أكثر من خدمة، ومتوسط الفاتورة لعميلات الباقات مقابل المنفرد.','لما تكون أغلب الفواتير خدمة وحدة، أو قبل مواسم المناسبات.','الباقة اللي تجبر العميلة على خدمة ما تبيها تضر الرضا؛ والتجميع الخالص قد يثير إشكالات تنافسية في بعض الأسواق حسب المراجعة نفسها.',array['stremersch-tellis-2002']::text[],'evidence',array['باقات','تجميع','مناسبات','متوسط الفاتورة']::text[],'sales',22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-24','sales','معادلة قيمة العرض (ممارسة)','يقترح Hormozi أن قيمة العرض في نظر العميل ترتفع مع حجم النتيجة المرغوبة وثقته بتحققها، وتنخفض مع طول الانتظار والجهد والتضحية المطلوبة منه.','عند تصميم أي باقة، اسألوا: هل النتيجة واضحة؟ هل العميلة واثقة إنها بتتحقق (صور قبل/بعد حقيقية بموافقة، أخصائية معروفة)؟ هل قللنا الانتظار والجهد (حجز سهل، مواعيد مرنة، خدمة منزلية)؟','باقة ليزر مع جدول جلسات محجوز مسبقًا، وتذكير آلي، وجلسة متابعة، تقلل الجهد على العميلة وترفع ثقتها.','نسبة إغلاق الباقة وعدد الإلغاءات أثناءها.','عند تصميم عرض جديد أو باقة موسمية.','هذا إطار ممارس من تجربة المؤلف، ليس دليلًا علميًا محكّمًا. وعروضه الأصلية كثيرًا ما تعتمد ضمانات ومكافآت قد لا تناسب صالون أو تخالف ضوابط الإعلان.',array['hormozi-offers']::text[],'practice',array['عرض','قيمة','باقات','ثقة','تصميم العرض']::text[],'campaigns',23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-25','sales','الوقت هو المخزون: قيسي إيراد الساعة','يقترح Kimes وSingh أن مراكز العناية تعامل ساعات العلاج المتاحة كمخزون، وتقيس الإيراد لكل ساعة علاج متاحة (RevPATH) بدل الاكتفاء بالإشغال أو متوسط الفاتورة.','احسبوا إيراد الساعة لكل أخصائية ولكل قسم (شعر، أظافر، ليزر). خدمة طويلة بسعر متوسط قد تكون أقل ربحية من خدمتين قصيرتين في نفس الوقت، والعكس.','مقارنة إيراد الساعة للحمام المغربي مقابل الأظافر في نفس الغرفة أو بنفس الأخصائية.','الإيراد مقسوم على ساعات العمل المتاحة لكل أخصائية وقسم، أسبوعيًا.','عند تحديد الخدمات اللي تتوسعون فيها، أو عند توزيع الأخصائيات على الأيام.','الإطار مفاهيمي وأمثلته افتراضية؛ أرقامكم من ركاز هي المعيار.',array['kimes-singh-2009']::text[],'practice',array['إيراد الساعة','إشغال','جدولة','إدارة الإيرادات']::text[],'finance',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-26','sales','أسعار وقت الهدوء بشروط منطقية','يوصي Kimes وSingh بأن يكون فرق السعر بين الأوقات قائمًا على «حواجز» منطقية واضحة (وقت اليوم، الحجز المبكر، الضمان)، ويحذران من الخصم العام لأنه يخفض الإحساس بالسعر الحقيقي.','بدل خصم عام، قدموا ميزة محددة في الأوقات الهادئة (صباح أيام الأسبوع مثلًا): ترقية خدمة بنفس السعر، أو إضافة صغيرة. والأوقات المزدحمة تبقى بالسعر الكامل مع اشتراط تأكيد الحجز.','«صباحيات الأحد إلى الأربعاء»: حجز بروتين يجي معه ترقية للماسك، بدون تغيير السعر المعلن.','نسبة الإشغال في الأوقات الهادئة، وإيراد الساعة فيها، قبل وبعد العرض.','لما يكون الفرق كبير بين امتلاء نهاية الأسبوع وفراغ الصباحيات.','أي فرق سعري لازم يكون معلن وواضح ومفهوم السبب، وإلا يبان غير عادل (sal-27).',array['kimes-singh-2009']::text[],'practice',array['أوقات هادئة','إشغال','ترقية','عروض','تسعير حسب الوقت']::text[],'campaigns',25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-27','sales','رفع السعر يُقبل إذا كان سببه عادل','وجد Kahneman وKnetsch وThaler أن الناس يتقبلون رفع السعر لما يكون بسبب ارتفاع تكلفة على المنشأة، ويرونه ظلمًا لما يكون استغلالًا لزيادة الطلب أو حاجة العميل، وقد يعاقبون المنشأة على ذلك.','عند رفع الأسعار، اشرحوا السبب الحقيقي (تكلفة منتجات، تحسين خدمة) بإعلان واضح ومسبق، وتجنبوا رفع السعر فجأة في موسم العيد أو الزواجات بدون تفسير. العميلات القديمات يستاهلن إشعار قبل التطبيق.','رسالة للعميلات قبل شهر: بسبب تحديث منتجات الصبغة لأنواع أعلى جودة، يتعدل سعر الصبغة من تاريخ كذا، والحجوزات الحالية بالسعر القديم.','تقييمات الصالون وتعليقاتها عن السعر، ونسبة رجوع العميلات بعد التعديل.','قبل أي تعديل في الأسعار.','يمشي مع Kimes وSingh اللي يلاحظان أن السعر الكامل في الذروة يُتقبل أكثر من «رسوم إضافية» تُضاف عليه.',array['kkt-1986','kimes-singh-2009']::text[],'evidence',array['عدالة','رفع السعر','ثقة','مواسم','تقييمات']::text[],'finance',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-28','sales','العربون وسياسة عدم الحضور','يقترح Kimes وSingh لمراكز العناية أدوات لتقليل عدم الحضور والإلغاء المتأخر: ضمان الحجز، مهلة إلغاء واضحة، عربون في أيام الذروة، وتأكيد قبل الموعد بيوم.','طبّقوا العربون على الخدمات الطويلة والمواعيد اللي يصعب تعويضها (مكياج العرايس، الحمام المغربي، الحجوزات الجماعية، الخدمات المنزلية)، مع سياسة إلغاء مكتوبة تُرسل مع تأكيد الحجز في ركاز وتذكير قبل يوم.','حجز مكياج عروس يتأكد بعد دفع عربون، ويُسترد أو يُحوّل لموعد ثاني إذا ألغت قبل المهلة المعلنة.','نسبة عدم الحضور والإلغاء المتأخر لكل خدمة قبل وبعد السياسة، وأثرها على الحجوزات الجديدة.','لما يرتفع عدم الحضور أو تضيع مواعيد الذروة.','الإطار مفاهيمي، وما وجدنا دراسة محكّمة على صالونات تحدد أثر العربون رقميًا؛ قيسوه من بياناتكم. وخلّوا السياسة معلنة قبل الدفع وعادلة، مع مرونة للظروف الطارئة.',array['kimes-singh-2009']::text[],'practice',array['عربون','عدم الحضور','إلغاء','سياسة','حجوزات']::text[],'appts',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-29','sales','منتج البيت امتداد للخدمة لا بيع منفصل','تتعامل مناهج مهن التجميل مثل Milady مع بيع المنتجات واقتراح الخدمات كجزء من خدمة العميلة المهنية: التوصية تنطلق من حالة العميلة وما يحافظ على نتيجتها.','الأخصائية تذكر المنتج اللي استخدمته أثناء الخدمة وليش يناسب العميلة، وتكتب التوصية في ملفها، والاستقبال تعرضه عند الدفع بدون ضغط. اختاروا تشكيلة صغيرة ومدروسة بدل رفوف كثيرة.','بعد صبغة: الأخصائية تقول «استخدمت لك شامبو يحافظ على اللون، إذا تبين تاخذينه للبيت عشان يثبت اللون أطول»، والاستقبال تجهزه عند الحساب إذا وافقت.','نسبة الفواتير اللي فيها منتج، ومبيعات المنتجات لكل أخصائية، ورجوع العميلات لشراء نفس المنتج.','لما تكون مبيعات المنتجات ضعيفة رغم كثرة الخدمات.','الأرقام المتداولة عن «النسبة المثالية» لمبيعات المنتجات من الإيراد غالبًا بدون مصدر واضح؛ حددوا هدفكم من بياناتكم.',array['milady-2022']::text[],'practice',array['منتجات','بيع إضافي','عناية منزلية','أخصائيات']::text[],'sales',28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-30','sales','البيع الإضافي بموافقة وبدون ضغط','يربط Milady الاقتراح بمصلحة العميلة، وتنص وزارة التجارة على حق المستهلك في الاختيار بحرية دون ضغط من العروض. البيع الأخلاقي: اقتراح واضح، سعر معلن قبل التنفيذ، وحق الرفض.','قاعدة ثابتة: ما تُضاف أي خدمة أو منتج للفاتورة قبل ما تعرف العميلة سعره وتوافق. اقتراح واحد مناسب يكفي، وإذا رفضت يُحترم رفضها ويُكتب في ملفها عشان ما يتكرر عليها الإلحاح.','أثناء المنكير: «تبين نضيف بارافين؟ سعره كذا ويرطب اليدين»؛ إذا قالت لا، تكمل الأخصائية بدون تعليق.','شكاوى أو تقييمات تذكر «ضغط» أو «فاجؤوني بالسعر» (هدفها صفر)، مع نسبة قبول الاقتراحات.','دائمًا، وخاصة عند ربط حوافز الأخصائيات بالمبيعات.','الحوافز على المبيعات تزيد الإغراء بالضغط؛ وازنوها بمؤشرات رضا العميلة والتقييمات.',array['milady-2022','moc-discounts']::text[],'consensus',array['أخلاقيات','موافقة','بيع إضافي','ثقة','حوافز']::text[],'sales',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-31','sales','الرد على «غالي»: قيمة أو خيار أصغر، لا خصم','يجمع هذا المبدأ بين Nagle (حماية السعر بربطه بالقيمة وتغيير نطاق العرض بدل نزول السعر) وRackham (فهم الحاجة قبل الرد).','لما تقول العميلة «غالي»، الخطوة الأولى سؤال: مقارنة بإيش؟ ثم توضيح الفرق في القيمة، أو عرض خيار أبسط يناسب ميزانيتها (خدمة أقصر، جلسات أقل، تقسيم الباقة). الخصم آخر خيار وبصلاحية محددة.','عميلة تتردد في باقة ليزر ٦ جلسات: تعرض الاستقبال البدء بجلسة منطقة وحدة، أو باقة أصغر، وتحتفظ بسعر الباقة الكاملة.','نسبة تحول الاعتراضات إلى حجز (بأي خيار)، ونسبة اللي احتجن خصم.','عند تدريب الاستقبال والأخصائيات، أو لما تكثر الخصومات اليدوية.',null,array['nagle-pricing','rackham-spin']::text[],'consensus',array['اعتراضات','سعر','استقبال','خصم','خيارات']::text[],'sales',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-32','sales','عضوية العميلات المميزات: قيمة متجددة','تجمع العضوية بين المحاسبة الذهنية (الاشتراك حساب منفصل) وما وجده Gourville وSoman من أن الدفع الدوري يحافظ على الاستخدام والتجديد أكثر من الدفعة الكبيرة البعيدة.','إذا قررتوا عضوية للعميلات المنتظمات، خلّوها مبنية على خدمة يكررنها فعلًا (سشوار أسبوعي، أظافر شهرية)، بدفع شهري، ومزايا واضحة (أولوية حجز، ترقية)، وسهولة إيقاف أو إلغاء معلنة.','«عضوية بيوتفريش الشهرية»: عدد محدد من جلسات السشوار شهريًا وأولوية في مواعيد نهاية الأسبوع.','عدد الأعضاء، معدل الاستمرار شهريًا، الاستخدام الفعلي، وإيراد الساعة للمواعيد اللي يحجزنها.','لما يكون عندكم شريحة كبيرة من العميلات يزرن بانتظام.','العضوية ممكن تشغل مواعيد الذروة بإيراد أقل؛ احسبوا أثرها على إيراد الساعة قبل التوسع.',array['gourville-soman-1998','thaler-1985','kimes-singh-2009']::text[],'evidence',array['عضوية','اشتراك','عميلات مميزات','ولاء','تجديد']::text[],'vip',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-33','sales','السعر المعلن لازم يكون شامل الضريبة','حسب دليل هيئة الزكاة والضريبة والجمارك لقطاع التجزئة، السعر المعلن للسلع والخدمات في السوق المحلي لازم يشمل ضريبة القيمة المضافة، ولا يجوز إضافة الضريبة عند الدفع على السعر المعروض.','كل الأسعار في القائمة، صفحة الحجز، الواتساب، والإعلانات تكون شاملة الضريبة. وعند الخصم، تُحسب الضريبة على المبلغ بعد الخصم.','إذا السعر المعلن للبروتين رقم معين، فهو اللي تدفعه العميلة بالضبط، والفاتورة توضح الضريبة المضمنة داخله.','مراجعة دورية لكل قنوات عرض الأسعار، وصفر شكاوى من «زيادة عند الكاشير».','عند تحديث القائمة أو أي حملة إعلانية.','راجعوا التفاصيل (مثل الفواتير الإلكترونية والإشعارات الدائنة للخصم اللاحق) مع محاسب معتمد ومن موقع الهيئة مباشرة.',array['zatca-retail']::text[],'law',array['ضريبة القيمة المضافة','نظام','قائمة أسعار','فواتير','زاتكا']::text[],'rules',32) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('sal-34','sales','التخفيض يحتاج ترخيص وسعر قبل وبعد','توضح وزارة التجارة أن المنشأة لازم تحصل على ترخيص قبل إعلان أي تخفيض، وتعرضه للمستهلك (برمز يمكن مسحه)، وتوضح نسبة الخصم والسعر قبل وبعد، وأن العروض المضللة تخضع لنظام مكافحة الغش التجاري.','قبل أي حملة «خصم» في المواسم، تأكدوا من ترخيص التخفيض عبر منصة الوزارة، وأعلنوا النسبة والسعر الأصلي والمخفض بوضوح، والسعر الأصلي لازم يكون سعر حقيقي كنتم تبيعون فيه.','حملة اليوم الوطني: ترخيص التخفيض مثبت في الصالون وفي الإعلان، والقائمة تبين سعر الخدمة الأصلي والمخفض ونسبة الخصم.','وجود الترخيص لكل حملة خصم (قائمة تحقق قبل النشر)، وعدم وجود ملاحظات رقابية.','قبل أي إعلان تخفيض أو تنزيلات.','بيان الوزارة يركز على المنتجات؛ تحققوا من الوزارة مباشرة من انطباق الاشتراطات على الخدمات وعلى العروض غير السعرية (هدية مجانية، ترقية)، ولا تعتمدون على هذا الملخص لتحديد الغرامات.',array['moc-discounts']::text[],'law',array['تخفيضات','ترخيص','وزارة التجارة','نظام','عروض','مكافحة الغش التجاري']::text[],'rules',33) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-01','experience','الأخصائية أولًا عشان العميلة تكون أولًا','يرتب ماير الأولويات بشكل معكوس: الفريق قبل الضيف، ثم المجتمع والموردين وأخيرًا المستثمرين؛ لأن الموظف اللي يحس بالاهتمام هو اللي يقدّم ضيافة صادقة، وهذا اللي يرجع على المستثمر بأفضل عائد على المدى الطويل.','رضا الأخصائيات والاستقبال هو أول حلقة في تجربة العميلة. جدول عادل، استراحة حقيقية بين المواعيد، وتقدير علني للي تتميز، كلها تنعكس على نبرة الأخصائية مع العميلة. الشريكتان تراجعان ضغط الجدول قبل ما تراجعان شكاوى العميلات.','لما يكون عند أخصائية الصبغة أربع مواعيد طويلة ورا بعض يوم الخميس، يوزّع الاستقبال موعد منها على زميلة أو يضيف فاصل، بدل ما تستقبل آخر عميلة وهي مرهقة.','قارنوا تقييمات العميلات وتعليقاتهن حسب الأخصائية وحسب كثافة يومها؛ وراقبوا دوران الأخصائيات وغيابهن مقابل نسبة رجوع عميلاتهن.','لما تلاحظون تقييمات أقل في أيام الذروة، أو تكرار شكاوى من نفس الأخصائية، أو استقالات متتالية.','هذا ما يعني إن العميلة تجي بالمرتبة الثانية في الموقف نفسه؛ المقصود إن رعاية الفريق هي الطريق لخدمتها، مو بديل عنها.',array['meyer-stt','heskett-spc-1994']::text[],'practice',array['فريق','ضيافة','رضا الموظفات','أولويات','ثقافة']::text[],'team',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-02','experience','الخدمة إتقان، والضيافة إحساس','يفرّق ماير بين الخدمة (الأداء الفني للمهمة بالمعيار المطلوب) والضيافة (إحساس الضيف إن أحد واقف معه ويهتم فيه). الخدمة اتجاه واحد، والضيافة حوار؛ والمنشأة المتميزة تحتاج الاثنين.','قصة نظيفة وصبغة بلون صحيح هذي الخدمة. أما الضيافة فهي إن الأخصائية تسأل العميلة وش تبي فعلًا، تشرح لها الخطوة الجاية، وتنتبه إذا الماي حار أو الكرسي مو مريح. العميلة تتذكر الإحساس أكثر من التفاصيل الفنية.','في خدمة البروتين، الأخصائية تشرح قبل البدء كم بتاخذ الجلسة وش بتحس فيه من ريحة أو حرارة، وتسأل في النص إذا تبي تغيّر جلستها.','صنّفوا التعليقات في التقييمات: كم تعليق يذكر النتيجة الفنية وكم يذكر التعامل والإحساس. ارتفاع النوع الثاني علامة إن الضيافة واصلة.','لما تكون النتائج الفنية ممتازة لكن العميلات ما يرجعون بالقدر المتوقع.',null,array['meyer-stt']::text[],'practice',array['ضيافة','تعامل','تجربة','تواصل','جودة']::text[],null,1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-03','experience','اجمعي النقاط عن كل عميلة','يطلب ماير من فريقه جمع معلومات صغيرة عن الضيوف باستمرار (تفضيلاتهم، مناسباتهم، الأخطاء اللي صارت معهم سابقًا) وتسجيلها، عشان الزيارة الجاية تبدأ من حيث انتهت الأولى.','كل ملاحظة تقولها العميلة تنحفظ في ملفها: درجة الصبغة ورقم الخلطة، طول القصة المفضل، حساسية من منتج، تحب الهدوء أو السوالف، قهوتها كيف. الاستقبال يقرأ الملف قبل وصولها، والأخصائية تقرأه قبل ما تبدأ.','عميلة قالت في زيارتها الأخيرة إن عرس أختها الشهر الجاي؛ يظهر في ملفها تنبيه، وتُسأل عن العرس في الحجز التالي وتُقترح لها باقة المكياج والشعر بالوقت المناسب.','نسبة ملفات العميلات النشطات اللي فيها ملاحظات تفضيل محدّثة، ومقارنة نسبة رجوع العميلات اللي ملفاتهن مكتملة باللي ملفاتهن فاضية.','دائمًا، وبالأخص لما تتغير الأخصائية على العميلة أو تنتقل لفرع جديد مستقبلًا.','سجّلوا اللي يخدم الخدمة فقط، ولا تحفظون معلومات شخصية حساسة أو صحية بدون موافقة صريحة (شوفي exp-32 وexp-33).',array['meyer-stt','ritz-gold']::text[],'practice',array['تفضيلات','ملف العميلة','تخصيص','ذاكرة','ولاء']::text[],'vip',2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-04','experience','ترحيب بالاسم، توقّع، ووداع دافئ','خطوات الخدمة الثلاث في معايير ريتز كارلتون: ترحيب صادق باسم الضيف، توقّع احتياجه وتلبيته قبل ما يطلب، ووداع دافئ باسمه.','الاستقبال ينادي العميلة باسمها من أول ما تدخل، والأخصائية تجهّز اللي تعرف إنها تحتاجه قبل ما تطلبه (مخدة للرقبة، شاحن، ماي بارد). وعند الخروج وداع شخصي مو مجرد إصدار فاتورة.','عميلة الحمام المغربي المعتادة تلاقي روبها ومقاسها جاهز، وفي الوداع تقول لها موظفة الاستقبال باسمها إن موعدها الجاي محجوز لها إذا تبي نفس اليوم.','متسوّقة سرية (من معارفكم) أو استبيان قصير بعد الزيارة يسأل: هل نُودِيتِ باسمك؟ هل حسيتي إن أحد توقّع احتياجك؟','عند تدريب أي موظفة استقبال أو أخصائية جديدة، ولما تزيد التعليقات اللي تصف التعامل بإنه جاف أو روتيني.','التطبيق الآلي بدون صدق يبان؛ الاسم وحده ما يكفي إذا الموظفة ما تنتبه للعميلة فعلًا.',array['ritz-gold']::text[],'practice',array['ترحيب','استقبال','وداع','توقع الاحتياج','معايير']::text[],'appts',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-05','experience','وظّفي للطبع، ودرّبي على المهارة','يرى ماير إن المهارات الفنية تنتعلّم، أما الدفء والفضول والتعاطف فصعب تدريبها؛ فيعطيها وزن أكبر في التوظيف.','في مقابلة الأخصائية الجديدة، اختبروا التعامل مثل ما تختبرون المهارة: كيف ترد على عميلة متضايقة، هل تسأل قبل ما تبدأ، هل تبتسم وهي مشغولة. أخصائية فنيًا ممتازة وجافة بالتعامل ممكن تخسرون بسببها عميلات أكثر مما تكسبون.','يوم التجربة للمتقدمة يتضمن خدمة فعلية لعميلة متطوعة (من الفريق) تمثل دور عميلة مترددة، ويلاحظ الاستقبال طريقة الحوار مو بس النتيجة.','تقييمات العميلات للأخصائيات الجدد في أول ثلاث شهور، ونسبة العميلات الجدد اللي يرجعون لنفس الأخصائية.','عند كل توظيف، وبالأخص لما تتوسعون أو تفكرون بالامتياز التجاري لأن الطبع ما ينتقل بالكتيّب.',null,array['meyer-stt']::text[],'practice',array['توظيف','فريق','تعامل','أخصائيات','امتياز']::text[],'team',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-06','experience','لفتة شخصية ما تتوقعها','يطرح غيدارا إن الضيافة الاستثنائية تجي من لفتات مصممة لشخص بعينه بناءً على شي قاله أو لاحظوه، مو من هدايا موحدة للكل. وخصص فريقه أشخاصًا مهمتهم تحويل الملاحظات الصغيرة للفتات.','خلّوا الاستقبال يلتقط جملة عابرة من العميلة ويحوّلها لفتة بسيطة: عروس، مولود جديد، نجاح بنت، تعب من دوام. اللفتة مو لازم تكون غالية؛ المهم إنها تخصها هي.','عميلة ذكرت وهي تسوي أظافرها إنها ولدت قريب وما عندها وقت لنفسها؛ في زيارتها الجاية تلقى كرت تهنئة باسم المولود وجلسة مساج يدين قصيرة هدية.','سجّلوا اللفتات في ملف العميلة، وقارنوا نسبة رجوع العميلات اللي وصلتهن لفتة مقابل غيرهن، وتابعوا كم تقييم أو منشور ذكر اللفتة.','لما تبون تتميزون عن صالونات بنفس الجودة والسعر، أو لعميلات قريبات من التوقف.','اللفتة اللي تبان مصطنعة أو تكشف إنكم تتبعون تفاصيل خاصة بشكل مزعج تعطي أثر عكسي؛ استخدموا فقط اللي قالته العميلة بنفسها.',array['guidara-uh']::text[],'practice',array['لفتات','تخصيص','مفاجأة','ضيافة','ولاء']::text[],'vip',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-07','experience','انضباط ٩٥٪ يموّل كرم ٥٪','يقترح غيدارا إدارة المصاريف بانضباط شديد أغلب الوقت، عشان يكون فيه مجال تصرفون بسخاء مقصود على لحظات قليلة تصنع ذكرى عند الضيوف والفريق.','حددوا بند ميزانية شهري صغير وواضح للفتات والمفاجآت، وعطوا الاستقبال صلاحية التصرف فيه بدون الرجوع لكم كل مرة. بالمقابل شدّوا على الهدر في المنتجات والوقت الضايع.','ميزانية شهرية ثابتة للفتات (ورد، كيك صغير، ترقية مجانية لخدمة) تُصرف من الاستقبال وتُسجّل في النظام مع سببها.','تكلفة اللفتات كنسبة من الإيراد الشهري، مقابل التقييمات والمنشورات والرجوع المرتبط بها.','لما تكون اللفتات عشوائية وتعتمد على مزاج اليوم، أو لما يتردد الفريق يتصرف لأنه ما يعرف وش المسموح.','النسبتين في كلام غيدارا تعبير عن فكرة مو معادلة محاسبية؛ حددوا رقمكم من هوامش ربحكم الفعلية.',array['guidara-uh']::text[],'practice',array['ميزانية','لفتات','صلاحيات','تكاليف','هدايا']::text[],'finance',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-08','experience','التجربة نفسها هي المنتج','يطرح باين وجلمور إن القيمة الاقتصادية تتدرج من السلع إلى المنتجات إلى الخدمات إلى التجارب، وإن المنشأة اللي «تمسرح» تجربة متكاملة تقدر تميّز نفسها وتسعّر فوق سعر الخدمة المجردة.','الصالون مو بس يبيع قصة أو صبغة؛ يبيع ساعة راحة وعناية في مكان خاص بالنساء. كل تفصيل يدخل في التجربة: الريحة عند الباب، الموسيقى، الإضاءة، تقديم القهوة، ترتيب الانتقال بين الغرف.','باقة «يوم العروس» تُصمَّم كتجربة متسلسلة: استقبال بغرفة خاصة، ضيافة، ترتيب الخدمات بدون انتظار بينها، وتصوير بموافقتها في النهاية.','متوسط الفاتورة في الباقات المصممة كتجربة مقابل نفس الخدمات منفصلة، ونسبة الحجوزات المتكررة للباقات.','لما تحسون إن المنافسة صارت على السعر فقط، أو لما تبون ترفعون الأسعار بدون ما تخسرون العميلات.','التجربة ما تعوّض ضعف الأساس؛ إذا الصبغة طلعت غلط ما تنفع الموسيقى. والإطار نظري تسويقي أكثر منه نتيجة تجريبية.',array['pine-gilmore-ee']::text[],'consensus',array['تجربة','تميز','تسعير','باقات','أجواء']::text[],null,7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-09','experience','الجمال والهروب: عالمين يناسبون الصالون','يقسم باين وجلمور التجارب لأربعة عوالم: ترفيهية، تعليمية، جمالية (الاستمتاع بالمكان)، وهروب (الانغماس في جو مختلف). أقوى التجارب تجمع أكثر من عالم.','العالم الجمالي والهروب هم الأقرب للصالون: مكان مريح للعين، وإحساس إن العميلة طلعت من ضغط البيت والدوام. والعالم التعليمي ممكن يضاف بشرح العناية المنزلية بعد الخدمة.','الحمام المغربي يُقدّم كتجربة هروب كاملة: الجوال في صندوق، إضاءة خافتة، وبعد الجلسة الأخصائية تشرح للعميلة روتين بسيط للبشرة بالبيت (عالم تعليمي).','تعليقات العميلات اللي تذكر الراحة والأجواء، ونسبة حجز الخدمات «التجريبية» (حمام مغربي، مساج) مقارنة بالخدمات الوظيفية.','عند تصميم خدمة جديدة أو تجديد الديكور أو ترتيب الغرف.',null,array['pine-gilmore-ee']::text[],'consensus',array['أجواء','حمام مغربي','تصميم الخدمة','راحة','تجربة']::text[],null,8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-10','experience','اصنعي لحظة ذروة مقصودة','وجد ريدلماير وكانيمان إن تقييم الناس لتجربة بعد انتهائها يتأثر بقوة بأشد لحظة فيها وبنهايتها، أكثر من مدتها الكاملة أو متوسطها.','بما إن الذاكرة تشيل أقوى لحظة، صمّموا لحظة ذروة إيجابية واضحة في كل خدمة طويلة، وخففوا أي لحظة مزعجة قوية (ألم، حرارة، انتظار مفاجئ) لأنها ممكن تصير هي الذروة.','في جلسة الصبغة الطويلة، لحظة كشف النتيجة قدام المراية تكون مدروسة: إضاءة جيدة، تصفيف سريع، والأخصائية تعرض الشعر من الجوانب. وفي الليزر، تبريد وتطمين في أشد جزء.','اسألوا في استبيان ما بعد الزيارة: وش أحلى لحظة؟ وش أكثر شي ضايقك؟ وتابعوا تكرار نفس اللحظة المزعجة في الإجابات.','عند تصميم أي خدمة تزيد عن ساعة، أو لما تتكرر شكوى من جزء معين من الخدمة.','التجارب الأصلية كانت على إجراءات طبية مؤلمة؛ الأثر في الخدمات الممتعة متوقع لكن ما يعني إن المدة والجودة الكلية ما تهم.',array['redelmeier-kahneman-1996']::text[],'evidence',array['ذروة ونهاية','ذاكرة','تصميم الخدمة','ألم','ليزر']::text[],null,9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-11','experience','آخر دقايق الزيارة تكتب ذاكرتها','من نفس قاعدة الذروة والنهاية: نهاية التجربة لها وزن كبير في الحكم عليها، فالنهاية المزعجة ممكن تخرّب تجربة كانت جيدة.','النهاية في الصالون غالبًا عند الكاشير: انتظار للدفع، فاتورة فيها مفاجأة، أو سؤال بارد. خلّوا الدفع سريع والسعر واضح من البداية، والوداع شخصي، وإذا فيه إضافة على السعر تتقال قبل الخدمة مو عند الدفع.','العميلة اللي طولت جلستها ما توقف بالطابور عند الكاشير؛ الاستقبال يجهز الفاتورة وهي في آخر خطوة، ويعطيها عينة صغيرة أو ورقة عناية وهي طالعة.','شكاوى أو تعليقات مرتبطة بالسعر أو الدفع، ووقت الانتظار عند الكاشير، والتقييمات اللي تنكتب في نفس يوم الزيارة.','لما تشوفون تقييمات متوسطة من عميلات كانت خدمتهن ممتازة، أو شكاوى من «ما قالوا لي السعر».',null,array['redelmeier-kahneman-1996']::text[],'evidence',array['نهاية الزيارة','كاشير','دفع','وداع','شفافية السعر']::text[],'after',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-12','experience','سلسلة: رضا الفريق ← جودة ← ولاء ← ربح','يربط نموذج سلسلة الخدمة والربح بين جودة البيئة الداخلية ورضا الموظفين وولائهم، ثم قيمة الخدمة ورضا العميل وولائه، ثم النمو والربح؛ ويطلب قياس كل حلقة بدل قياس الربح فقط.','لا تكتفون بمتابعة الإيراد. راقبوا الحلقات اللي قبله: رضا الأخصائيات، ثبات الفريق، جودة الخدمة، رجوع العميلات. ضعف أي حلقة يظهر في الربح بعد شهور، فالأفضل تلتقطونه بدري.','لوحة شهرية في الموقع فيها: نسبة بقاء الأخصائيات، متوسط التقييم، نسبة رجوع العميلات، ثم الإيراد، عشان تشوفون السلسلة كاملة.','تتبع المؤشرات الأربعة شهريًا ومقارنة اتجاهاتها؛ انخفاض الرجوع بعد خروج أخصائية مثال واضح على الحلقة.','في المراجعة الشهرية، وقبل قرارات مثل تقليل العمولات أو زيادة عدد المواعيد لكل أخصائية.','النموذج يصف علاقات مترابطة ظهرت في شركات كبيرة، ولكن قوة كل حلقة تختلف من منشأة لثانية؛ اختبروه على أرقامكم بدل ما تفترضونه.',array['heskett-spc-1994']::text[],'consensus',array['سلسلة الخدمة والربح','فريق','مؤشرات','ربح','ولاء']::text[],'finance',11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-13','experience','قيمة العميلة تتراكم مع الوقت','يوضح رايكهيلد إن العميل اللي يستمر يصير أكثر قيمة مع الوقت: يشتري أكثر، يكلّف أقل في الخدمة لأنه يعرف النظام، ويجيب غيره بالتوصية. فالاحتفاظ محرك أساسي للربح.','فكروا في العميلة كقيمة على سنين، مو كفاتورة زيارة. عميلة الصبغة اللي تجي كل كم أسبوع وتجيب أختها وبنتها قيمتها أكبر بكثير من أي عرض لجذب عميلة جديدة لمرة وحدة.','احسبوا في الموقع إجمالي ما صرفته كل عميلة من أول زيارة، واعرضوه للاستقبال بشكل تصنيف (بدون مبلغ) عشان يعطي العميلات الأعلى انتباه خاص.','متوسط الإنفاق السنوي للعميلة حسب مدة علاقتها بالصالون، ونسبة العميلات الجدد اللي جوا بتوصية من عميلة حالية (من سؤال «كيف عرفتنا؟»).','لما تقررون وين تصرفون ميزانية التسويق: على جذب الجديد أو على الاحتفاظ بالحالي.','الأرقام المشهورة عن أثر الاحتفاظ على الربح جاية من قطاعات معينة درستها Bain؛ لا تنقلونها لصالونكم، احسبوا قيمتكم من بياناتكم.',array['reichheld-le-1996']::text[],'consensus',array['قيمة العميلة','احتفاظ','ولاء','توصية','ربح']::text[],'vip',12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-14','experience','مو كل عميلة دائمة مربحة','وجد راينارتز وكومار إن العلاقة بين طول مدة العميل وربحيته أضعف من المتوقع: فيه عملاء دائمين قليلين الربح، وفيه عملاء قصيرين لكن مربحين. فالولاء يُدار حسب الربحية مو حسب المدة فقط.','قسّموا عميلاتكن حسب الربحية والتكرار معًا. فيه عميلة تجي كثير بس على العروض فقط، وفيه عميلة تجي قليل لكن خدماتها عالية القيمة. معاملة VIP تكون حسب القيمة الفعلية، والمزايا ما تتوزع على كل من طالت مدتها.','تصنيف في الموقع بأربع خانات: تكرار عالي وقيمة عالية (VIP)، تكرار عالي وقيمة قليلة (تشجيع على خدمات أعلى)، تكرار قليل وقيمة عالية (تذكير بمواعيدها)، والباقي (تواصل خفيف).','هامش الربح لكل شريحة، ونسبة المزايا المصروفة على كل شريحة مقارنة بعائدها.','لما يكبر برنامج المزايا وتحسون إن تكلفته ما ترجع، أو قبل تصميم مستويات VIP.','هذا رأي مخالف جزئيًا لطرح رايكهيلد؛ الاثنين يتفقون إن الولاء مهم، لكن يختلفون في افتراض إن الولاء يعني ربح تلقائيًا.',array['reinartz-kumar-2002','reichheld-le-1996']::text[],'evidence',array['VIP','ربحية','تصنيف العميلات','برنامج ولاء','عروض']::text[],'vip',13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-15','experience','سؤال التوصية أداة استماع','اقترح رايكهيلد سؤالًا واحدًا: ما مدى احتمال إنك توصي فينا لصديقة؟ ويُحسب الفرق بين المروّجين المتحمسين والمنتقدين. قيمته الكبرى في سهولته وفي متابعة المنتقدين.','أرسلوا السؤال بعد الزيارة برسالة قصيرة، مع سؤال مفتوح: وش أكثر شي عجبك أو ضايقك؟ الأهم من الرقم هو الاتصال بالعميلات اللي أعطوا درجة منخفضة خلال يوم أو يومين.','عميلة أعطت درجة منخفضة بعد قص الشعر؛ يتصل فيها الاستقبال ويعرض عليها تعديل مجاني مع نفس الأخصائية أو غيرها حسب رغبتها.','نسبة الردود، النتيجة الشهرية حسب الخدمة والأخصائية، ونسبة المنتقدات اللي تم التواصل معهن ورجعن.','كمؤشر شهري ثابت، وعند إطلاق خدمة جديدة أو انضمام أخصائية جديدة.','النقد المحكّم (Keiningham وزملاؤه) ما لقى إن NPS أفضل من مقاييس الرضا الأخرى في التنبؤ بالنمو؛ استخدموه للاستماع والمتابعة، مو كرقم وحيد للحكم.',array['reichheld-nps-2003','keiningham-nps-2007']::text[],'practice',array['NPS','توصية','استبيان','رضا','متابعة']::text[],'after',14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-16','experience','لا تختصرون رضا العميلات في رقم واحد','في دراسة طولية على شركات متعددة، ما تفوّق مؤشر صافي المروّجين على مقاييس الرضا التقليدية في التنبؤ بنمو الإيرادات، وهذا ينقض فكرة إنه «الرقم الوحيد» اللي تحتاجه المنشأة.','اقرؤوا أكثر من مؤشر مع بعض: تقييم قوقل، نتيجة سؤال التوصية، نسبة الرجوع، والشكاوى. السلوك الفعلي (رجعت أو ما رجعت) أصدق من أي إجابة في استبيان.','لوحة التجربة في الموقع تعرض جنب بعض: نسبة الرجوع خلال دورة الخدمة المعتادة، متوسط التقييم، عدد الشكاوى، ونتيجة التوصية.','تطابق المؤشرات أو تعارضها؛ إذا التقييم عالي والرجوع نازل، فالمشكلة في شي ما يسأل عنه الاستبيان (سعر، مواعيد، منافس).','لما يكون التقييم ممتاز لكن الحجوزات نازلة، أو العكس.',null,array['keiningham-nps-2007']::text[],'evidence',array['مؤشرات','NPS','قياس','رجوع العميلات','تقييمات']::text[],null,15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-17','experience','الانتظار المشغول أقصر من الفاضي','من أطروحات مايستر: الوقت اللي فيه شي يشغل الشخص يمر أسرع من الوقت الفاضي، وأفضل شغل هو اللي له علاقة بالخدمة نفسها.','إذا العميلة لازم تنتظر، خلّوا الانتظار مفيد: كتالوج ألوان أو تسريحات، استشارة سريعة مع الأخصائية، أو تجهيز مبدئي (غسيل، إزالة مناكير قديم). ولا تنتظر وهي تطالع الجدار.','عميلة الصبغة وصلت والأخصائية بآخر عميلتها؛ تجلس مع موظفة الاستقبال تختار درجة اللون من الكتالوج وتقدَّم لها القهوة، فتبدأ الخدمة وقرارها جاهز.','سؤال في استبيان ما بعد الزيارة عن الإحساس بالانتظار، والشكاوى المرتبطة بالتأخير، مقابل الوقت الفعلي المسجّل بين الوصول وبداية الخدمة.','لما يكون فيه انتظار لا مفر منه في أوقات الذروة (الخميس، قبل الأعياد والأعراس).',null,array['maister-waiting-1985']::text[],'consensus',array['انتظار','استقبال','ذروة','مواعيد','تجربة']::text[],'appts',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-18','experience','قولي لها كم بتنتظر وليش','يطرح مايستر إن الانتظار المجهول المدة أطول في الإحساس من الانتظار المعروف، والانتظار بدون تفسير أطول من الانتظار المفسَّر، والقلق يطوّل الإحساس بالوقت.','أي تأخير في الموعد يتبلّغ للعميلة قبل ما توصل إذا أمكن، برسالة فيها المدة المتوقعة والسبب. وإذا وصلت، الاستقبال يقول لها بوضوح كم دقيقة وليش، ويرجع لها إذا طال.','الأخصائية تأخرت بسبب عميلة عروس؛ يرسل النظام رسالة للعميلة الجاية يقول إن موعدها متأخر ربع ساعة تقريبًا ويعرض عليها تجي متأخرة أو تغيّر الموعد.','نسبة المواعيد المتأخرة اللي سبقها تبليغ، ومقارنة تقييمات المواعيد المتأخرة مع تبليغ وبدونه.','لما تزيد شكاوى التأخير، أو في الأيام اللي فيها خدمات طويلة غير متوقعة المدة (عرائس، تصحيح لون).','لا تعطون مدة أقصر من الحقيقة عشان تطمنونها؛ الوعد المكسور يضاعف الضيق.',array['maister-waiting-1985']::text[],'consensus',array['تأخير','رسائل','انتظار','مواعيد','شفافية']::text[],'appts',17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-19','experience','العدالة في الدور تبان للكل','من أطروحات مايستر: الانتظار اللي يحس الشخص إنه غير عادل (أحد تخطّاه بدون سبب واضح) يكون أثقل بكثير من انتظار عادل بنفس المدة.','إذا عندكم عميلات VIP أو أولويات، خلّوا الامتياز يصير في الحجز (مواعيد محجوزة لهن مسبقًا) مو في تقديمهن على عميلة جالسة قدامهن في الصالة. وإذا صار تقديم لسبب، يتوضح بلطف.','عميلة دائمة دخلت مباشرة بينما ثانية تنتظر؛ الاستقبال يوضح للمنتظرة إن تلك عندها موعد محجوز بهذا الوقت، ويعطيها وقتها المتوقع.','شكاوى «فيه وحدة دخلت قبلي»، وتعليقات المحسوبية في التقييمات.','عند تصميم برنامج VIP، وفي أيام الزحمة اللي يختلط فيها الحجز مع الحضور بدون موعد.',null,array['maister-waiting-1985']::text[],'consensus',array['عدالة','انتظار','VIP','أولوية','استقبال']::text[],'appts',18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-20','experience','ابدئي الخدمة بأسرع وقت ولو بخطوة','يلاحظ مايستر إن الانتظار قبل بداية الخدمة أثقل من الانتظار بعد ما تبدأ، لأن الشخص يبي يحس إنه دخل في الخدمة.','أول خطوة بعد الوصول تكون بدء فعلي ولو بسيط: استشارة، غسيل، أو تجهيز. الانتظار بعدها بين المراحل (مثل انتظار تثبيت الصبغة) يتقبّل أكثر.','عميلة المكياج تبدأ مباشرة بتنظيف وترطيب البشرة من مساعدة، حتى لو خبيرة المكياج بتبدأ بعد عشر دقايق.','الوقت بين تسجيل الوصول وأول خطوة فعلية، ومقارنته بالتقييمات.','لما يكون التأخير قصير ومتكرر، أو في الخدمات اللي لها مساعدة تقدر تبدأ التجهيز.',null,array['maister-waiting-1985']::text[],'consensus',array['بداية الخدمة','انتظار','تجهيز','مساعدات','مواعيد']::text[],'appts',19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-21','experience','الأبعاد الخمسة للجودة، والاعتمادية أولها','يقيس SERVQUAL جودة الخدمة بالفرق بين توقع العميل وإحساسه في خمسة أبعاد: الملموسات (المكان والمظهر)، الاعتمادية (تنفيذ الوعد بدقة)، الاستجابة (السرعة والاستعداد)، الثقة (الكفاءة والأمان)، والتعاطف (الاهتمام الفردي).','استخدموا الأبعاد الخمسة كقائمة مراجعة: هل المكان نظيف ومرتب؟ هل النتيجة مثل ما وعدنا وبالوقت؟ هل نرد على الرسائل بسرعة؟ هل العميلة مطمّنة لنظافة الأدوات وخبرة الأخصائية؟ هل نعاملها كشخص مو كرقم؟','استبيان ربع سنوي قصير بخمس عبارات، كل عبارة تمثل بُعد، وتختار العميلة من مقياس موافقة.','متوسط كل بُعد على حدة؛ أقل بُعد هو أولوية التحسين للربع الجاي.','في المراجعات الدورية، أو لما تحسون بتراجع عام وما تعرفون من وين.','انتقد كرونين وتايلور قياس الفرق بين التوقع والأداء، ولقوا إن قياس الأداء فقط (SERVPERF) أبسط وأعطى نتائج أفضل في دراستهم. للصالون، سؤال الأداء المباشر غالبًا يكفي.',array['pzb-servqual-1988','cronin-taylor-1992']::text[],'evidence',array['جودة الخدمة','SERVQUAL','استبيان','اعتمادية','نظافة']::text[],null,20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-22','experience','إصلاح الخطأ مهارة لها نظام','يطرح هارت وزملاؤه إن الأخطاء في الخدمة حتمية، وإن المنشآت المتميزة تخطط للتعافي منها: تشجع العميل يشتكي، تتصرف بسرعة، تدرّب وتمكّن موظفي الصف الأمامي، وتتعلم من كل خطأ.','اكتبوا دليل قصير للأخطاء المتكررة (لون مختلف، قصة أقصر، تأخير، تحسس) وكيف يتعامل معها الاستقبال والأخصائية فورًا: اعتذار، حل، وخيار تعويض محدد سلفًا. والخطأ ينسجّل عشان يُعالج سببه.','عميلة طلع لون الصبغة أغمق من المطلوب؛ الأخصائية تعتذر فورًا، وتعرض تصحيح مجاني بموعد قريب، ويُسجّل الخطأ مع رقم الخلطة لمراجعته.','عدد الأخطاء المسجلة شهريًا حسب النوع، والوقت بين الشكوى والحل، ونسبة رجوع العميلات اللي صار معهن خطأ وتعالج.','من أول يوم، ولما تتكرر نفس نوعية الخطأ.',null,array['hart-recovery-1990']::text[],'consensus',array['تعافي','أخطاء','شكاوى','تصحيح','تدريب']::text[],'after',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-23','experience','عطي الصف الأمامي صلاحية الحل','من توصيات هارت وزملائه: الموظف اللي يقابل العميل لازم يكون مدرّب ومخوّل يحل المشكلة في مكانها، لأن تحويلها لمدير وتأخيرها يزيد الضيق.','حددوا للاستقبال والأخصائيات حلول يقدرون يقدمونها بدون ما يرجعون للشريكات: تصحيح مجاني، خصم محدد، خدمة إضافية صغيرة. وأي شي أكبر من الحدود يرتفع لكم بنفس اليوم.','موظفة الاستقبال تقدر تعطي عميلة انتظرت كثير خصم محدد على الزيارة الجاية أو ترقية بسيطة، وتسجّل السبب في النظام.','نسبة الشكاوى المحلولة من أول تواصل، وتكلفة التعويضات الشهرية مقابل رجوع العميلات المتضررات.','لما تتأخر حلول الشكاوى لأنها تنتظر رد الشريكات، أو لما الموظفات يترددون يتصرفون.','الصلاحية بدون حدود واضحة وتسجيل ممكن تصير بوابة للمجاملات؛ الحدود والتوثيق جزء من التمكين.',array['hart-recovery-1990']::text[],'consensus',array['تمكين','صلاحيات','استقبال','تعويض','شكاوى']::text[],'rules',22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-24','experience','لا تراهنون على مفارقة التعافي','مفارقة التعافي تقول إن العميل اللي انحلت مشكلته ممتاز ممكن يصير أرضى من اللي ما صار معه خطأ. التحليل التجميعي لدي ماتوس وزملائه لقى أثر إيجابي على الرضا، لكن ما لقى أثر دال على نية الرجوع أو التوصية أو صورة المنشأة.','إصلاح الخطأ ضروري، لكنه ما يعوّض عن تجنبه. العميلة ممكن تطلع راضية عن طريقة التعامل بس قرار الرجوع يتأثر بالخطأ نفسه. فالاستثمار الأول في منع الخطأ (استشارة قبل الصبغة، اختبار حساسية)، والتعافي خط دفاع ثاني.','بدل الاعتماد على تصحيح اللون بعد الخطأ، تُعتمد خطوة إلزامية: الأخصائية تعرض درجة اللون على خصلة أو في الكتالوج وتأكد مع العميلة قبل الخلط.','قارنوا نسبة رجوع العميلات اللي صار معهن خطأ وانحل مع العميلات اللي ما صار معهن خطأ؛ لا تفترضون إنها أعلى.','لما يميل الفريق للتهاون بالخطأ بحجة «نعوّضها وخلاص».','الدراسات لقت إن تصميم الدراسة ونوع العينة والقطاع يأثرون على النتيجة، والأدلة الميدانية تقول إن الاعتذار وحده ممكن ما يكفي.',array['dematos-srp-2007','hart-recovery-1990']::text[],'evidence',array['مفارقة التعافي','أخطاء','وقاية','رضا','رجوع العميلات']::text[],null,23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-25','experience','الشكوى تنحل بثلاث عدالات','وجد تاكس وزملاؤه إن تقييم العميل لمعالجة شكواه يعتمد على ثلاث أنواع عدالة: عدالة النتيجة (التعويض المناسب)، عدالة الإجراء (سرعة وسهولة ووضوح)، وعدالة التعامل (احترام وتعاطف وصدق في الاعتذار).','أي شكوى تُعالج بالثلاث مع بعض: حل مناسب لحجم المشكلة، بدون ما تضطر العميلة تشرح قصتها لثلاث موظفات أو تنتظر أيام، وبنبرة محترمة ما فيها دفاع أو تلميح إنها هي السبب.','عميلة اشتكت من قصة غير متساوية: موظفة واحدة تستلم الشكوى للنهاية، تعتذر بدون جدال، تعرض تعديل في نفس الأسبوع، وترسل لها تأكيد بالموعد.','وقت حل الشكوى، عدد الموظفات اللي تعاملت معها الشكوى، ورضا العميلة عن الحل (سؤال واحد بعد إغلاقها).','عند كتابة سياسة الشكاوى وتدريب الاستقبال، ولما تشتكي العميلات من طريقة الرد أكثر من المشكلة نفسها.','التعويض الكبير ما يعوّض عن تعامل سيء؛ والتعامل اللطيف بدون حل فعلي يبان كلام.',array['tax-complaints-1998']::text[],'evidence',array['شكاوى','عدالة','اعتذار','تعويض','سياسات']::text[],'after',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-26','experience','تواصل بعد الزيارة بهدف واضح','الاهتمام الفردي والاستجابة من أبعاد جودة الخدمة، والتواصل بعد الزيارة يفتح باب للشكوى قبل ما تتحول لتقييم سلبي أو غياب صامت، وهذا من صلب تشجيع العميل يتكلم عند هارت وزملائه.','رسالة قصيرة في اليوم التالي للخدمات الحساسة (صبغة، بروتين، ليزر، بشرة) تسأل عن النتيجة وتذكّر بتعليمات العناية، بدون عروض في نفس الرسالة. والرد السلبي يتحوّل فورًا لمتابعة من الاستقبال.','بعد جلسة الليزر: رسالة في اليوم التالي تسأل عن احمرار أو تهيج، وتذكّر بتجنب الشمس، ورقم مباشر للتواصل إذا فيه شي غير طبيعي.','نسبة الرد على رسائل المتابعة، عدد المشاكل اللي انكشفت عن طريقها، ونسبة رجوع العميلات اللي وصلتهن متابعة مقابل غيرهن.','بعد كل خدمة لها نتيجة تظهر بعد أيام أو لها تعليمات عناية، وبعد أول زيارة لأي عميلة جديدة.','كثرة الرسائل تزعج؛ رسالة وحدة بهدف واضح أفضل من سلسلة رسائل. وتأكدوا من موافقة العميلة على التواصل (شوفي exp-34).',array['pzb-servqual-1988','hart-recovery-1990']::text[],'practice',array['متابعة','بعد الزيارة','رسائل','ليزر','عناية منزلية']::text[],'after',25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-27','experience','الغايبة تُسترجع قبل ما تنسى المكان','يرى توماس وبلاتبرغ وفوكس إن استرجاع العملاء المنقطعين يستاهل اهتمام مثل الاحتفاظ بالحاليين، وإن قرار الاسترجاع ومدة العلاقة الثانية لازم ينحسبون مع بعض عند اختيار من تستهدفون.','حددوا «الغياب» لكل عميلة حسب دورة خدمتها مو برقم ثابت للكل: عميلة الصبغة اللي تجي كل كم أسبوع تُعتبر متأخرة أسرع من عميلة القص الموسمي. والتواصل يبدأ بسؤال صادق عن سبب الغياب قبل أي عرض.','النظام يطلع قائمة أسبوعية بالعميلات اللي تجاوزن دورتهن المعتادة بوضوح؛ الاستقبال يرسل رسالة شخصية باسم أخصائيتها: افتقدناك، وإذا فيه شي ما عجبك نبي نعرفه.','نسبة العميلات الغايبات اللي رجعن بعد التواصل، وعدد الزيارات اللي سوينها بعد الرجوع (مدة العلاقة الثانية).','لما تنزل نسبة الرجوع، أو بعد خروج أخصائية لأن عميلاتها معرّضات للانقطاع.','مو كل غايبة تستاهل نفس الجهد؛ العميلة اللي ما رجعت إلا على العروض ممكن ترجع وتطلع مرة ثانية.',array['thomas-recapture-2004']::text[],'evidence',array['استرجاع','غياب','انقطاع','دورة الخدمة','رسائل']::text[],'away',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-28','experience','عرض الرجوع مغري، وبعده السعر الطبيعي','في دراسة توماس وبلاتبرغ وفوكس، كان الأنسب في القطاع اللي درسوه سعر منخفض لاسترجاع العميل ثم أسعار أعلى بعد ما يرجع.','عرض الاسترجاع يكون واضح القيمة ولمرة وحدة (خدمة مجانية مكمّلة أو خصم على الزيارة الأولى بعد الغياب)، وبعدها ترجع العميلة للسعر الطبيعي. لا تخلونها تتعود إن الغياب يجيب خصم.','عميلة غايبة من فترة طويلة يوصلها عرض: حمام زيت مجاني مع أول صبغة ترجع فيها، صالح لفترة محددة، وبعدها تعامل كأي عميلة.','نسبة قبول العرض، ونسبة العميلات اللي سوين زيارة ثانية بالسعر الكامل بعد العرض.','في حملات الاسترجاع الدورية، أو بعد المواسم اللي يقل فيها الحضور.','الدراسة الأولى طُبقت على قطاع معين، فالفكرة العامة قابلة للنقل لكن حجم الخصم المناسب لازم ينختبر عندكم بمجموعات صغيرة.',array['thomas-recapture-2004']::text[],'evidence',array['عرض استرجاع','تسعير','خصم','حملات','غياب']::text[],'winback',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-29','experience','بطاقة الولاء تبدأ بخطوة محسوبة','وجد نونيز ودريز إن البطاقة اللي تبدأ وفيها جزء مكتمل مسبقًا (مثلًا عشر خانات مع خانتين هدية) يكملها الناس أكثر وأسرع من بطاقة أقصر تبدأ فاضية، مع إن المطلوب فعليًا نفس العدد.','إذا سويتوا بطاقة ختم أو نقاط رقمية، خلوها تبدأ وفيها تقدم حقيقي مع سبب واضح (هدية التسجيل أو أول زيارة)، عشان تحس العميلة إنها بدأت الطريق.','بطاقة الأظافر الرقمية: الخدمة المجانية بعد عدد معيّن من الزيارات، والبطاقة تنفتح وفيها ختمين «هدية انضمامك».','نسبة إكمال البطاقات، ومتوسط الوقت بين الزيارات قبل وبعد إطلاق البطاقة.','عند تصميم أو تجديد برنامج الولاء.','الدراسة لقت إن سبب المنحة وطريقة عرض التقدم يأثرون على قوة الأثر؛ ولا تخلون البرنامج يتحول لخصم دائم يقلل هامشكم.',array['nunes-dreze-2006']::text[],'evidence',array['بطاقة ولاء','نقاط','ختم','برنامج ولاء','تحفيز']::text[],'vip',28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-30','experience','اطلبي التقييم من الكل وبدون مقابل','سياسة قوقل تمنع تقديم أي حافز (فلوس، خصم، خدمة مجانية) مقابل كتابة تقييم أو تعديله أو حذفه، وتمنع طلب التقييم من العملاء الراضين فقط أو منع السلبي. المسموح: تشجيع التقييم الصادق بدون مقابل وبدون توجيه محتواه.','رسالة طلب التقييم تنرسل لكل العميلات بنفس الطريقة، بدون فلترة مسبقة بسؤال «هل أنتِ راضية؟» عشان ترسلون الرابط بس للراضيات. ولا يتربط أي خصم أو هدية بكتابة التقييم.','بعد الزيارة بيوم: رسالة شكر فيها رابط التقييم، بصيغة: يهمنا رأيك الصادق سواء كان حلو أو فيه ملاحظة. والسحب على الهدايا الشهري ما يكون مشروط بالتقييم.','عدد التقييمات الجديدة شهريًا ومعدل الاستجابة لرسالة الطلب، مع متابعة إن ما فيه تقييمات انحذفت من قوقل.','عند كتابة رسالة طلب التقييم أو تصميم أي حملة فيها هدايا.','التقييمات المحفّزة أو الانتقائية معرّضة للحذف والملف التجاري معرّض لقيود؛ تقييم ★4.8 الحقيقي أثمن من رقم مصطنع.',array['google-reviews-policy']::text[],'practice',array['تقييمات','قوقل','سياسة','حوافز','سمعة']::text[],'reviews',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-31','experience','لا إلحاح ولا حصص تقييم للموظفات','تمنع سياسة قوقل الضغط على العميل يقيّم وهو داخل المحل، وطلب محتوى معيّن في التقييم مثل ذكر اسم موظف، ووضع حصص أو أهداف لعدد التقييمات على الموظفين.','لا تطلب الأخصائية من العميلة تقييم وهي جالسة على الكرسي أو عند الكاشير، ولا تقول لها «اكتبي اسمي». ولا تنحط حوافز أو أهداف للأخصائيات على عدد تقييماتهن في قوقل؛ قيسوا أداءهن بأرقامكم الداخلية.','بدل لوحة «قيّمينا الحين» عند الكاشير، يُرسل الرابط تلقائيًا من النظام بعد الزيارة، وتقييم الأخصائيات يكون من الاستبيان الداخلي.','تقييم الأخصائيات من الاستبيان الداخلي ونسبة رجوع عميلاتهن، مو من عدد مرات ذكر اسمهن في قوقل.','عند وضع أهداف وحوافز للفريق، أو عند تدريب الاستقبال على طلب التقييمات.',null,array['google-reviews-policy']::text[],'practice',array['تقييمات','حوافز الفريق','قوقل','أخصائيات','سياسة']::text[],'reviews',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-32','experience','الصورة بموافقة صريحة ولغرض محدد','نظام حماية البيانات الشخصية يعتبر أي بيانات تحدد شخصًا بيانات شخصية، ويشترط موافقة واضحة ومحددة لكل غرض، مع حق سحبها بسهولة. والصورة اللي تُظهر العميلة بيانات شخصية.','في صالون نسائي بالأحساء، الخصوصية والستر جزء أساسي من الثقة. ما تتصور أي عميلة إلا بإذنها، وموافقة «صورة للملف الداخلي» تختلف عن «صورة للنشر»، والنشر يكون بدون وجه أو بموافقة مكتوبة صريحة. ولا جوالات للموظفات في غرف الخدمة.','قبل تصوير نتيجة صبغة للإنستقرام، تختار العميلة في نموذج رقمي: لا تصوير / تصوير للملف فقط / نشر بدون وجه / نشر بالوجه، وتقدر تسحب موافقتها وتنحذف الصورة.','نسبة الصور المنشورة اللي لها موافقة مسجلة (لازم تكون كاملة)، وعدد طلبات الحذف وسرعة تنفيذها.','قبل أي تصوير للمحتوى أو للبورتفوليو، وعند توظيف موظفة تسويق أو تعاون مع مصورة.','النظام ملزم ونفاذه بدأ في 2023 تحت إشراف سدايا، وإساءة التصوير ممكن تدخل أيضًا تحت أنظمة أخرى تحمي الحياة الخاصة؛ ارجعوا لنص النظام الرسمي أو مستشار قانوني للتفاصيل.',array['pdpl']::text[],'law',array['خصوصية','تصوير','موافقة','حماية البيانات','ستر']::text[],'rules',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-33','experience','معلوماتها الصحية أمانة حساسة','يصنّف نظام حماية البيانات الشخصية البيانات الصحية ضمن البيانات الحساسة، ومعالجتها تحتاج موافقة صريحة وما يجوز استخدامها للتسويق.','معلومات مثل الحساسية من منتجات، الحمل، حالة الجلد قبل الليزر، أو أدوية تأثر على البشرة، تنحفظ في ملف العميلة لأنها ضرورية لسلامتها، لكن بموافقتها الصريحة، وبصلاحية اطلاع محدودة (الأخصائية المعنية)، وما تُستخدم أبدًا في استهداف عروض.','نموذج الاستشارة قبل الليزر يشرح ليش نحتاج المعلومة، وتوافق العميلة عليه، وتظهر الملاحظة الصحية لأخصائية الليزر فقط مو لكل الاستقبال.','نسبة ملفات الخدمات الحساسة اللي فيها موافقة موثقة، ومراجعة دورية لمن يقدر يشوف الملاحظات الصحية في النظام.','عند بناء نماذج الاستشارة في الموقع، وعند إعطاء صلاحيات المستخدمين.','ما ذكرنا أرقام مواد أو عقوبات لأنها تحتاج تأكيد من النص الرسمي واللوائح المحدثة.',array['pdpl']::text[],'law',array['بيانات صحية','ليزر','حساسية','خصوصية','صلاحيات']::text[],'rules',32) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('exp-34','experience','رسائل التسويق بإذنها وإيقافها بضغطة','حسب نظام حماية البيانات الشخصية، الرسائل التسويقية تعتمد على موافقة الشخص، ولازم يكون عنده طريقة سهلة يوقفها.','فرّقوا في النظام بين رسائل الخدمة (تأكيد موعد، تذكير، متابعة بعد خدمة) ورسائل التسويق (عروض، مواسم). التسويقية ما تنرسل إلا للي وافقت، وكل رسالة فيها طريقة واضحة للإيقاف تُحترم فورًا.','عند التسجيل تختار العميلة: أبغى عروض المواسم نعم/لا. ورسالة عرض العيد فيها سطر: إذا ما تبين رسائل العروض ردي بكلمة إيقاف.','نسبة الموافقات التسويقية من إجمالي العميلات، ونسبة الإيقاف بعد كل حملة (ارتفاعها علامة إزعاج).','قبل أي حملة رسائل جماعية، وعند استيراد أرقام العميلات من نظام الحجز.','هذا ما يلغي الحاجة لمراجعة أنظمة الاتصالات الخاصة بالرسائل؛ والنظام نفسه فيه تفاصيل تحتاج استشارة للعلاقات القائمة.',array['pdpl']::text[],'law',array['رسائل','تسويق','موافقة','إيقاف','حملات']::text[],'campaigns',33) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-01','operations','اشتغلوا على الصالون مو بس داخله','يرى Gerber أن أغلب أصحاب المشاريع الصغيرة يغرقون في العمل اليومي بأيديهم، بينما المطلوب وقت ثابت لبناء الأنظمة التي تخلي المشروع يمشي بدونهم.','خصصوا وقت أسبوعي ثابت لشهد وأميرة بعيد عن الأرضية والاستقبال، يكون فقط لمراجعة الأرقام وكتابة الإجراءات وحل المشاكل المتكررة. أي مشكلة تتكرر مرتين تتحول لإجراء مكتوب بدل ما تنحل كل مرة بالجوال.','بدل ما تتصل الاستقبال بشهد كل ما وصلت عميلة متأخرة، تكتبون قاعدة واضحة للتأخير (كم دقيقة مسموح، ومتى تُختصر الخدمة أو يُعاد الحجز) وتعلقونها في دليل الاستقبال.','عدد المرات اللي تحتاج فيها الأخصائيات أو الاستقبال يرجعون للملاك في الأسبوع، وعدد الإجراءات المكتوبة في الموقع. الهدف أن الأول ينزل والثاني يزيد.','لما تحسون إن الصالون يوقف أو يرتبك إذا غابت وحدة من الشريكات، أو لما تكثر الاتصالات اليومية للاستفسار.','مو معناه الابتعاد عن العميلات؛ في صالون قائم على العلاقة الشخصية حضور الملاك له قيمة. الفكرة إن الحضور يكون اختيار مو ضرورة.',array['gerber-emyth']::text[],'practice',array['أنظمة','إدارة','تفويض','الملاك','إجراءات']::text[],'rules',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-02','operations','ابنوا الفرع الحالي كنموذج قابل للتكرار','يقترح Gerber أن يُدار المشروع كأنه أول فرع في سلسلة امتياز: كل شي موثق ومتوقع ويقدر يشغّله شخص عادي مدرّب، وليس موهبة فردية.','قبل أي تفكير بالامتياز، لازم يكون عندكم في الموقع: دليل خدمات بمدد وأدوات محددة، قوائم افتتاح وإغلاق، معايير ترحيب، وقواعد حجز وإلغاء. الصالون اللي ما يقدر يكرر نفسه داخل نفس الفرع ما يقدر يكرر نفسه في مدينة ثانية.','خدمة البروتين: ورقة واحدة فيها الخطوات بالترتيب، المنتج المعتمد، الكمية حسب طول الشعر، التهوية، والرسالة بعد الخدمة. أي أخصائية جديدة تقدر تتبعها.','نسبة الخدمات اللي لها إجراء مكتوب من قائمة الخدمات، وتقارب التقييمات بين الأخصائيات لنفس الخدمة (لو فيه فرق كبير، فالجودة معتمدة على الشخص مو على النظام).','لما تبدؤون تفكرون بفرع ثاني أو امتياز، أو لما تتعين أخصائية جديدة وتاخذ وقت طويل حتى توصل للمستوى.','التوثيق الزائد يقتل المرونة. اكتبوا الخطوات الحرجة والمعايير، واتركوا مساحة للأخصائية في التفاصيل الفنية والذوق.',array['gerber-emyth']::text[],'practice',array['امتياز','فرانشايز','توسع','توثيق','نموذج']::text[],'rules',1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-03','operations','وزّعوا أدوار الفنية والمديرة والرائدة','يصف Gerber ثلاث شخصيات داخل صاحب المشروع: الفنية اللي تنفذ، والمديرة اللي تنظم، والرائدة اللي تخطط للمستقبل. المشاكل تبدأ لما تطغى الفنية على الباقي.','حددوا بوضوح مين من الشريكتين مسؤولة عن التشغيل اليومي (الجداول، المخزون، الجودة) ومين مسؤولة عن النمو (الخدمات الجديدة، الشراكات، الامتياز). ولو وحدة منهن تشتغل كأخصائية، احجزوا لها ساعات إدارة في الجدول مثل أي حجز.','في نظام الحجز تُقفل ساعتين صباح الأحد باسم «إدارة» لشهد، وما تنحجز لأي عميلة.','الساعات الأسبوعية المخصصة للإدارة والتخطيط مقابل ساعات الخدمة لكل شريكة، وهل المهام الإدارية المؤجلة تقل.','لما تتأجل القرارات المهمة شهور لأن الكل مشغول بالخدمة، أو لما يصير تداخل بين الشريكتين في القرارات.',null,array['gerber-emyth']::text[],'practice',array['أدوار','شراكة','إدارة','تخطيط','وقت']::text[],'team',2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-04','operations','قوائم قصيرة عند نقاط التوقف','يوضح Gawande أن القائمة الفعالة قصيرة، تركز على الخطوات اللي يسهل نسيانها وخطرها كبير، وتُقرأ عند نقطة توقف محددة. ويفرّق بين قائمة «اقرأ ثم نفّذ» وقائمة «نفّذ ثم تأكّد».','لا تكتبون قائمة طويلة لكل شي. اختاروا لحظات محددة: قبل بدء الصبغة، قبل البروتين، قبل خروج العميلة. كل قائمة من ٥ إلى ٩ بنود تقريبًا، بلغة واضحة، وتكون مطبوعة عند المحطة أو على جهاز الاستقبال.','قبل الصبغة (نفّذ ثم تأكّد): هل سألنا عن حساسية سابقة؟ هل سجلنا رقم اللون في ملف العميلة؟ هل الأدوات من المعقم؟ هل المنتج داخل الصلاحية؟','عدد الأخطاء المتكررة (لون غلط، نسيان تسجيل الوصفة، شكوى حساسية) قبل وبعد تطبيق القائمة، من سجل الشكاوى والملاحظات.','لما تتكرر أخطاء بسيطة رغم إن الأخصائيات خبيرات، أو مع تعيين موظفات جدد.','القائمة ما تعلّم المهارة، هي تمنع النسيان فقط. وإذا طالت وصارت روتين شكلي، الناس توقع عليها بدون ما تقراها.',array['gawande-checklist']::text[],'practice',array['قائمة تحقق','أخطاء','جودة','صبغة','سلامة']::text[],'kit',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-05','operations','دليل القوائم من غرف العمليات','في دراسة Haynes وزملائه، طُبّقت قائمة منظمة الصحة العالمية للسلامة الجراحية في ثمانية مستشفيات، وانخفضت الوفيات من ١٫٥٪ إلى ٠٫٨٪ والمضاعفات الكبرى من ١١٪ إلى ٧٪ بعد التطبيق.','الدرس للصالون مو الأرقام نفسها، بل إن حتى الفرق الخبيرة جدًا تستفيد من وقفة قصيرة منظمة قبل الإجراء: تأكيد هوية العميلة والخدمة، والمنتج، والحساسية، وتعريف الفريق ببعضه في الخدمات المشتركة (مثل تجهيز عروس).','قبل تجهيز العروس: دقيقة اجتماع بين أخصائية الشعر والمكياج والأظافر لتأكيد الترتيب والتوقيت ومين تبدأ.','شكاوى التأخير والأخطاء في الخدمات المشتركة، والتزام الفريق بالوقفة (سجل بسيط في الموقع).','في الخدمات الطويلة أو اللي يشترك فيها أكثر من أخصائية، أو في المواسم المزدحمة.','الدراسة قارنت قبل وبعد بدون مجموعة ضابطة عشوائية، وسياقها جراحي. فلا تنقلون النسب للصالون كوعود.',array['haynes-2009','gawande-checklist']::text[],'evidence',array['قائمة تحقق','دليل','فريق','عروس','تنسيق']::text[],'kit',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-06','operations','قائمة افتتاح يومية ثابتة','تطبيق مباشر لفكرة القوائم: افتتاح المكان كل يوم بنفس الخطوات يمنع إن العميلة الأولى تكتشف المشكلة قبلكم.','الموظفة اللي تفتح تمر على قائمة في الموقع: التكييف والتهوية شغالة، أجهزة التعقيم جاهزة وفيها أدوات معقمة، المغاسل فيها صابون ومناشف، المنتجات المفتوحة داخل صلاحيتها، الحمام المغربي نظيف وجاهز، وجدول اليوم مراجع مع الحجوزات غير المؤكدة.','تفتح الاستقبال الموقع الساعة ٩:٤٥، تعلّم على البنود، وأي بند ما اكتمل يطلع تنبيه للمديرة المناوبة.','نسبة الأيام اللي اكتملت فيها القائمة قبل أول موعد، وعدد المشاكل اللي اكتُشفت أثناء الخدمة بدل وقت الافتتاح.','من أول يوم، وخاصة لما تتبدل الموظفات المسؤولات عن الفتح.',null,array['gawande-checklist','rcu-guide-2022']::text[],'practice',array['افتتاح','يومي','قائمة','نظافة','تجهيز']::text[],'kit',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-07','operations','قائمة إغلاق تحمي يوم بكرة','الإغلاق المنظم يجهّز اليوم التالي ويقفل المخاطر: الأجهزة، النفايات، المحاليل، والنقد.','قائمة الإغلاق تشمل: تفريغ المحلول المطهر المستعمل، جمع النفايات والأدوات الحادة في حاويات مقفلة، فصل الأدوات المستعملة عن النظيفة، إطفاء أجهزة التسخين والشمع، مطابقة صندوق اليوم مع النظام، وتسجيل المنتجات اللي قربت تخلص.','آخر موظفة تقفل تصوّر جهاز الشمع مطفي وتعلّم في الموقع، وتكتب «الصبغة رقم كذا باقي علبتين».','فروقات الصندوق اليومية، وعدد مرات نفاد منتج بدون تنبيه مسبق.','دائمًا، وخاصة بعد الأيام المزدحمة أو المواسم.',null,array['gawande-checklist','rcu-guide-2022']::text[],'practice',array['إغلاق','يومي','نفايات','صندوق','أمان']::text[],'kit',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-08','operations','إجراء قياسي لكل خدمة','في الـLean، العمل القياسي يحدد ثلاث أشياء: الإيقاع المطلوب، وتسلسل الخطوات بالضبط، والكمية اللازمة من المواد عند المحطة. ويُعلّق في مكان العمل.','لكل خدمة رئيسية (قص، صبغة، بروتين، مناكير، تنظيف بشرة، حمام مغربي) اكتبوا: المدة الفعلية، الخطوات بالترتيب، الأدوات والمنتجات المطلوبة قبل دخول العميلة، ونقطة الجودة اللي لازم تتأكد منها الأخصائية قبل التسليم.','الحمام المغربي: تجهيز الغرفة والمواد خلال وقت محدد قبل الموعد، ترتيب ثابت للخطوات، وكمية محددة من الصابون المغربي والكيس لكل عميلة.','الفرق بين المدة المكتوبة والمدة الفعلية في نظام الحجز، واستهلاك المنتج لكل خدمة، وتقييمات الخدمة لكل أخصائية.','لما تختلف مدة نفس الخدمة كثير بين الأخصائيات، أو لما يتفاوت استهلاك المنتجات بدون سبب.','مدرسة الـLean نفسها تحذر من تحويل الإجراء لقيد جامد؛ الإجراء نقطة بداية تتطور، مو قانون ثابت.',array['lei-lexicon','womack-lean']::text[],'consensus',array['إجراء','SOP','خدمة','مدة','جودة']::text[],'rules',7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-09','operations','التحسين المستمر يبدأ من الإجراء المكتوب','حسب معجم الـLean، العمل القياسي هو الأساس اللي يُبنى عليه التحسين المستمر (كايزن)، ويُحدَّث كلما تغيرت الظروف، والعاملون أنفسهم يقترحون التعديلات.','الأخصائيات هن أكثر من يعرف وين يضيع الوقت. خصصوا اجتماع قصير شهري تقترح فيه كل وحدة تحسين واحد على إجراء خدمة، وتُجرّب أسبوعين، ثم يُعتمد أو يُلغى بناءً على الأرقام.','أخصائية الأظافر تقترح تجهيز صينية مناكير كاملة لكل موعد بدل جمع الأدوات أثناء الخدمة. تُجرّب أسبوعين ويُقاس الوقت.','عدد الاقتراحات المطبّقة كل شهر، وتغيّر مدة الخدمة أو تقييمها بعد كل تعديل.','لما يستقر الإجراء الأساسي وتبون تحسنون بدون قرارات كبيرة من فوق.','لا تغيرون الإجراء كل أسبوع بدون قياس، وإلا ترجعون للفوضى.',array['lei-lexicon']::text[],'consensus',array['كايزن','تحسين','فريق','اقتراحات','تطوير']::text[],'team',8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-10','operations','نظام 5S للمحطات والمخزن','خمس خطوات من الـLean: فرز المطلوب من غير المطلوب، ترتيب كل شي في مكان محدد، التنظيف، تثبيت المعايير، والانضباط للاستمرار عليها.','طبقوها على كل محطة ومخزن: شيلوا المنتجات القديمة والمكررة، خصصوا مكان مُعلَّم لكل أداة، نظفوا بجدول ثابت، صوّروا شكل المحطة المثالي وعلقوه، وراجعوه أسبوعيًا.','درج أدوات الصبغة: صورة ملصقة داخل الدرج توضح مكان الفرش والأوعية والقفازات، وأي أخصائية تفتحه تعرف وش ناقص.','الوقت اللي تقضيه الأخصائية في البحث عن الأدوات، ونتيجة جولة 5S الأسبوعية (درجة بسيطة لكل محطة في الموقع).','لما تتكرر جملة «وين راح...؟»، أو لما يتكدس المخزن بمنتجات ما تُستخدم.',null,array['lei-lexicon']::text[],'consensus',array['5S','ترتيب','نظافة','مخزن','محطة']::text[],'kit',9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-11','operations','حددوا القيمة من عين العميلة','يبدأ التفكير الرشيق عند Womack وJones بتعريف القيمة من وجهة نظر العميل النهائي، ثم رسم كل الخطوات اللي يمر فيها وحذف اللي ما تضيف له شي.','ارسموا رحلة العميلة من الحجز في ركاز حتى الخروج والرسالة بعدها. لكل خطوة اسألوا: هل العميلة تحس بقيمة هنا؟ الانتظار في الاستقبال، تكرار نفس الأسئلة، والدفع البطيء خطوات تأخذ وقت بدون قيمة.','العميلة الراجعة تُسأل كل مرة عن لون صبغتها. لو مسجل في ملفها، الخطوة تختفي وتحس إن الصالون يعرفها.','متوسط وقت الانتظار من الوصول لبداية الخدمة، ووقت الدفع، وتعليقات التقييمات اللي تذكر الانتظار أو التنظيم.','لما تذكر التقييمات الانتظار أو الفوضى، أو قبل إعادة تصميم الاستقبال.',null,array['womack-lean']::text[],'consensus',array['قيمة','رحلة العميلة','انتظار','تيار القيمة','تجربة']::text[],'appts',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-12','operations','اصطادوا الهدر في يوم الصالون','الـLean يسمي كل نشاط يستهلك وقت أو موارد بدون قيمة للعميل «هدر» (مودا): انتظار، حركة زائدة، تنقّل، مخزون زائد، إعادة عمل، وتجهيز أكثر من اللازم.','أمثلة الهدر في الصالون: أخصائية تمشي للمخزن عدة مرات أثناء الخدمة، صبغة مخلوطة زيادة وتنرمى، إعادة تصحيح لون، غرفة جاهزة والعميلة ما وصلت. اختاروا نوع واحد كل شهر واشتغلوا عليه.','تسجيل كمية الصبغة المخلوطة والمستخدمة فعليًا لمدة أسبوعين يكشف كم يُرمى، وبعدها تحددون كميات قياسية حسب طول الشعر.','تكلفة المنتجات لكل خدمة، وعدد خدمات التصحيح المجانية، والوقت الضائع بين المواعيد.','لما ترتفع تكلفة المواد بدون زيادة في الخدمات، أو لما يحس الفريق بالضغط والإيراد ما زاد.','مو كل وقت بدون خدمة هدر؛ الضيافة والكلام مع العميلة جزء من القيمة في صالون مثل بيوتفريش.',array['womack-lean']::text[],'consensus',array['هدر','مودا','تكلفة','منتجات','كفاءة']::text[],'kit',11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-13','operations','اعرفوا وين عنق الزجاجة','تقول نظرية القيود عند Goldratt إن إنتاج أي نظام محكوم بأضيق نقطة فيه، وأول خطوة دائمًا تحديد هذا القيد.','القيد في الصالون ممكن يكون غرفة الحمام المغربي، أو أخصائية البروتين الوحيدة، أو كراسي الغسيل، أو الاستقبال وقت الذروة. راجعوا نظام الحجز: وش الخدمة اللي تنحجز أبعد وقت مسبق؟ ووش المورد اللي دايم ممتلئ؟','لو مواعيد الحمام المغربي محجوزة أسبوع مقدمًا بينما كراسي القص فاضية، فالغرفة هي القيد، مو عدد الأخصائيات.','نسبة امتلاء كل مورد (غرفة، كرسي، أخصائية) في ساعات الذروة، وعدد الطلبات المرفوضة أو المؤجلة لكل خدمة.','لما تسمعون «ما فيه موعد» كثير وفي نفس الوقت فيه موظفات فاضيات.',null,array['goldratt-goal']::text[],'consensus',array['اختناق','قيود','طاقة','غرف','أخصائيات']::text[],'appts',12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-14','operations','لا تضيعون دقيقة من وقت القيد','الخطوة الثانية والثالثة عند Goldratt: استغلال القيد لأقصى حد، ثم ربط كل شي ثاني بإيقاعه. ساعة ضايعة عند القيد ساعة ضايعة على الصالون كله.','إذا كانت أخصائية البروتين هي القيد: الغسيل والتجفيف الأولي تسويه مساعدة، والمنتج والأدوات جاهزة قبل وصول العميلة، وما تنحجز لها خدمات بسيطة يقدر غيرها يسويها.','تحويل حجوزات السشوار البسيطة من أخصائية البروتين لأخصائيات ثانيات يفتح لها موعدين بروتين إضافيين في الأسبوع.','ساعات الخدمة الفعلية للمورد القيد مقابل ساعاته المتاحة، وعدد الخدمات عالية القيمة اللي يقدمها أسبوعيًا.','بعد ما تحددون القيد، وقبل أي تفكير بتوظيف أو شراء.','عند Goldratt، تشغيل المورد اللي مو قيد بكامل طاقته ما يزيد الناتج، بل يكدّس العمل. فلا تقيسون نجاح كل موظفة بامتلاء جدولها.',array['goldratt-goal']::text[],'consensus',array['قيود','استغلال','جدولة','إنتاجية','مساعدات']::text[],'appts',13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-15','operations','وسّعوا القيد بعد ما تستغلونه','الخطوة الرابعة والخامسة: إذا استُغل القيد بالكامل ولا زال يحدّ الطلب، يُرفع (توظيف، غرفة إضافية)، ثم تبدأ الدورة من جديد لأن القيد ينتقل لمكان ثاني.','لا توظفون أخصائية جديدة أو تبنون غرفة ثانية إلا بعد ما تثبت أرقامكم إن القيد مستغل تمامًا وإن الطلب موجود. وبعد التوسعة راقبوا وين صار القيد الجديد (ممكن يصير الاستقبال أو المواقف).','بعد إضافة غرفة حمام مغربي ثانية، صار القيد عدد الأخصائيات المدربات عليه، فصار التدريب هو الخطوة التالية.','قائمة الانتظار أو الطلبات المرفوضة قبل وبعد التوسعة، والعائد على الاستثمار من الإيراد الإضافي.','لما يكون المورد القيد ممتلئ باستمرار رغم التحسينات، والطلب ثابت مو موسمي فقط.','توسعة قيد موسمي (مثل العيد والأعراس) بتكلفة دائمة خطأ شائع؛ قارنوا ذروة الموسم مع باقي السنة.',array['goldratt-goal']::text[],'consensus',array['توسعة','توظيف','استثمار','قيود','طاقة']::text[],'finance',14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-16','operations','قيسوا الإيراد لكل ساعة متاحة','تقترح Kimes وSingh قياس أداء السبا بالإيراد لكل ساعة علاج متاحة، لأن المخزون الحقيقي هو الوقت. المقياس يجمع نسبة الامتلاء ومتوسط الصرف في رقم واحد.','احسبوا لكل غرفة وكل كرسي وكل أخصائية: الإيراد مقسوم على الساعات المتاحة، مو الساعات المحجوزة. هذا يكشف إن غرفة فاضية نص اليوم وأسعارها عالية ممكن تكون أضعف من غرفة مزحومة بأسعار متوسطة.','مقارنة الإيراد لكل ساعة متاحة بين غرفة البشرة وغرفة الحمام المغربي، صباحًا ومساءً، تبيّن وين تركزون العروض.','الإيراد لكل ساعة متاحة لكل مورد وكل فترة من اليوم والأسبوع، ومقارنته شهريًا.','لما تقررون التسعير أو العروض أو ساعات الدوام، أو لما الإيراد الكلي ما يوضح وين المشكلة.','التركيز على هذا الرقم فقط ممكن يدفع لضغط الحجوزات على حساب التجربة. راقبوا التقييمات ورجوع العميلات معه.',array['kimes-singh-2009']::text[],'evidence',array['إيراد','طاقة','تسعير','مقياس','غرف']::text[],'finance',15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-17','operations','اضبطوا مدة الخدمة ووقت التبديل','من أدوات إدارة الإيرادات في السبا حسب Kimes وSingh: تعريف مدة الخدمة بدقة، وإشعار واضح بانتهائها، وتقليل وقت التبديل بين عميلة وعميلة.','حددوا لكل خدمة مدتها الفعلية مع وقت التجهيز والتنظيف، وسجلوها في ركاز بهالشكل. وقللوا وقت تجهيز الغرف بتجهيز مسبق للمواد ومساعدة تنظف بينما الأخصائية تودّع العميلة.','تنظيف البشرة يُعرض «ساعة» لكن الخدمة نفسها أقل، والباقي للتجهيز؛ لو الوقت مكتوب صح، الجدول ما يتأخر طول اليوم.','متوسط التأخير التراكمي في الجدول آخر اليوم، والوقت بين نهاية موعد وبداية التالي في نفس الغرفة.','لما تتأخر المواعيد المسائية دائمًا، أو لما تشتكي العميلات من الانتظار رغم إن عندهم موعد.','اختصار الخدمة نفسها لتوفير الوقت يضر الجودة؛ المستهدف وقت التجهيز والتبديل، مو وقت العميلة.',array['kimes-singh-2009']::text[],'evidence',array['مدة','جدولة','تأخير','تبديل','غرف']::text[],'appts',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-18','operations','قللوا عدم اليقين في الحضور','تذكر Kimes وSingh أن السبا يقدر يقلل الغياب والإلغاء المتأخر بأدوات مثل العربون أو ضمان الحجز، والتأكيد المسبق، وتسهيل إعادة الجدولة الطوعية.','طبقوا عربون على الخدمات الطويلة والمواعيد اللي عليها طلب (عرايس، بروتين، حمام مغربي في الويكند)، مع سياسة إلغاء واضحة ومعلنة وقت الحجز. وسهّلوا تغيير الموعد بدل الإلغاء.','حجز تجهيز عروس يتأكد بعربون، وترسل الاستقبال تأكيد قبل الموعد بيوم مع رابط لتغيير الموعد.','نسبة عدم الحضور والإلغاء المتأخر لكل خدمة، قبل وبعد تطبيق العربون والتأكيد.','لما ترتفع نسبة عدم الحضور، خاصة في الخدمات الطويلة أو أوقات الذروة.','العربون الصارم على كل شي ممكن ينفّر العميلات الدائمات. فرّقوا بين العميلة الجديدة واللي عندها سجل التزام.',array['kimes-singh-2009']::text[],'evidence',array['عربون','إلغاء','غياب','حجز','سياسة']::text[],'appts',17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-19','operations','أسعار متمايزة بأسباب مفهومة','يطرح Kimes وChase السعر والمدة كرافعتين استراتيجيتين، وتضيف Kimes وSingh أن التسعير المتمايز يحتاج «حواجز» واضحة (وقت اليوم، نوع الغرفة، مستوى الأخصائية، شروط الحجز) حتى تحس العميلة إنه عادل.','بدل الخصومات العامة، استخدموا فروقات مفهومة: أخصائية أولى بسعر أعلى، أو إضافة مجانية في الأوقات الهادية مع بقاء السعر الأساسي. هذا يحمي قيمة الخدمة ويوزع الطلب.','أيام الأحد والاثنين الصبح: عند حجز البروتين تُضاف جلسة ماسك مجانًا، بدل خصم على السعر.','امتلاء الفترات الهادية، ومتوسط الفاتورة فيها، وهل السعر الأساسي حافظ على مستواه في الفترات القوية.','لما يكون الصباح وبداية الأسبوع فاضي والمساء والويكند ممتلئ.','حسب Kimes وSingh، الخصم العام المتكرر يضعف القيمة المدركة. وأي فرق سعر بدون سبب واضح للعميلة يُفهم كاستغلال.',array['kimes-chase-1998','kimes-singh-2009']::text[],'evidence',array['تسعير','خصومات','أوقات هادية','عدالة','عروض']::text[],'finance',18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-20','operations','قرارات للذروة وقرارات للهدوء','خطوات التطبيق عند Kimes وSingh: بيانات أساس، فهم أسباب تذبذب الأداء، توصيات مختلفة للفترات المزدحمة والهادية، تدريب الفريق وربط الحوافز بالأهداف، ثم المتابعة مقابل الأساس.','قسموا الأسبوع لفترات قوية وهادية حسب بيانات ركاز. في القوية: لا خصومات، أولوية للخدمات الطويلة والعالية، عربون. في الهادية: إضافات، باقات، حملات للعميلات المنقطعات، وتدريب داخلي.','بعد رمضان والعيد تكون فترة هادية: تُستغل للتدريب على خدمة جديدة وحملة رجوع للعميلات اللي ما زارتكم من ثلاث شهور.','الإيراد لكل ساعة متاحة في كل فترة مقارنة بالأساس قبل التغيير.','عند وضع خطة شهرية أو موسمية، أو لما تبون تفهمون ليش شهر أضعف من الثاني.',null,array['kimes-singh-2009']::text[],'evidence',array['مواسم','ذروة','تخطيط','حوافز','بيانات']::text[],'seasons',19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-21','operations','رسائل التذكير ترفع الحضور','وجدت مراجعة Cochrane أن رسائل الجوال للتذكير رفعت الحضور مقارنة بعدم التذكير (من ٦٧٫٨٪ إلى ٧٨٫٦٪ في الدراسات المشمولة)، وأثرها قريب من الاتصال الهاتفي بتكلفة أقل. ودرجة اليقين منخفضة إلى متوسطة.','فعّلوا تذكير آلي من ركاز أو واتساب قبل الموعد، فيه الوقت والخدمة واسم الأخصائية وطريقة التأكيد أو التغيير بضغطة. والاتصال الهاتفي خلّوه للخدمات الطويلة أو العميلات اللي سجلهن فيه غياب.','رسالة قبل الموعد بيوم: «موعدك للصبغة بكرة الساعة ٥ مع الأخصائية نورة، للتأكيد ردي ١ ولتغيير الموعد ردي ٢».','نسبة عدم الحضور قبل وبعد تفعيل التذكير، ونسبة الردود بالتأكيد أو التغيير.','دائمًا، وخاصة لما يرتفع الغياب أو في المواعيد المحجوزة من وقت بعيد.','الدراسات كلها في مواعيد صحية، فالنسب ما تنطبق بالضرورة على الصالون. قيسوا أرقامكم أنتم.',array['gurol-cochrane-2013']::text[],'evidence',array['تذكير','رسائل','غياب','حجز','واتساب']::text[],'appts',20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-22','operations','قواعد الحجز تتفصّل على بيئتكم','تبيّن مراجعة Cayirli وVeral أن أفضل قاعدة لتوزيع المواعيد تعتمد على ظروف المكان: نسبة الغياب، والحضور بدون موعد، وتأخر الوصول، وتفاوت مدة الخدمة. ما فيه قاعدة واحدة تناسب الكل.','حللوا بيانات ركاز: كم نسبة اللي يجون بدون موعد؟ كم نسبة الغياب لكل خدمة؟ ومتى؟ بناءً عليها قرروا: هل تتركون فراغات للحضور المباشر؟ هل تسمحون بحجز زائد بسيط في الخدمات القصيرة اللي غيابها عالي؟','لو تبين إن مواعيد الأظافر السريعة عليها غياب أعلى، ممكن تتركون فتحة احتياطية للحضور المباشر بدل حجز زائد على خدمة طويلة.','وقت انتظار العميلات، ووقت الفراغ عند الأخصائيات، والوقت الإضافي آخر اليوم. التوازن بين الثلاثة هو الهدف.','لما يكون الجدول إما مزحوم مع انتظار طويل أو فاضي مع غياب، أو عند تغيير نظام الحجز.','الحجز الزائد على خدمات طويلة أو للعرايس خطير على السمعة؛ إذا حضرت الكل، وحدة بتتضرر.',array['cayirli-veral-2003']::text[],'evidence',array['جدولة','حجز','حضور مباشر','غياب','قواعد']::text[],'appts',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-23','operations','الامتلاء الكامل مو هدف لكل موظفة','يجمع منطق نظرية القيود مع إدارة الإيرادات على أن الاستغلال يُقاس عند المورد اللي يحدّ الإيراد، وأن تشغيل كل شي بطاقته القصوى يكدّس الانتظار بدل ما يزيد الناتج.','تابعوا نسبة الاستغلال لكل كرسي وغرفة وأخصائية، لكن افهموها حسب الدور: القيد لازم يكون شبه ممتلئ، أما الموارد الثانية فوجود هامش فيها يمتص التأخير والحضور المباشر ويحمي تجربة العميلة.','أخصائيات القص بامتلاء متوسط يقدرون يستقبلون عميلات بدون موعد ويساعدون في الغسيل لما تتأخر أخصائية الصبغة.','نسبة الاستغلال لكل مورد، مع وقت الانتظار والتأخير التراكمي، ومقارنتها بالإيراد لكل ساعة متاحة.','عند تقييم أداء الأخصائيات أو التفكير في تقليل العدد أو زيادته.',null,array['goldratt-goal','kimes-singh-2009']::text[],'consensus',array['استغلال','طاقة','تقييم','انتظار','هامش']::text[],'team',22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-24','operations','نقطة إعادة طلب لكل منتج','في إدارة المخزون، نقطة إعادة الطلب هي المستوى اللي إذا وصل له الصنف تطلبونه فورًا، وتساوي الاستهلاك المتوقع خلال مدة التوريد مضافًا له مخزون احتياطي يغطي التذبذب.','لكل منتج أساسي (صبغات الأرقام الأكثر طلبًا، البروتين، الشمع، القفازات) حددوا: كم تستهلكون في الأسبوع، وكم ياخذ المورد حتى يوصل، وكم احتياطي تحتاجون في المواسم. وسجلوها في الموقع ليطلع تنبيه تلقائي.','إذا المورد ياخذ أسبوع والصالون يستهلك علبتين بروتين أسبوعيًا، فنقطة الطلب علبتين زائد احتياطي، والاحتياطي يزيد قبل موسم الأعراس.','عدد مرات نفاد الأصناف، والخدمات اللي تأجلت بسبب نقص منتج، وقيمة المخزون المكدّس.','لما ينفد منتج فجأة، أو لما تلاحظون كراتين منتجات ما تتحرك.','الأرقام تعتمد على بياناتكم الفعلية؛ ابدأوا بتقدير بسيط وعدّلوه كل شهر.',array['silver-pyke-2017']::text[],'consensus',array['مخزون','إعادة طلب','احتياطي','مورد','نفاد']::text[],'kit',23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-25','operations','الأقرب انتهاءً يُستخدم أولًا','للمنتجات اللي لها صلاحية، الصرف يكون حسب تاريخ الانتهاء الأقرب. والمنتجات المستوردة كثير منها يحمل رمز العلبة المفتوحة اللي يبين كم شهر تبقى صالحة بعد الفتح.','رتبوا المخزن بحيث الأقرب انتهاءً قدّام، واكتبوا تاريخ الفتح على كل عبوة مفتوحة (هذا مطلوب في أدلة التزيين النسائي البلدية)، وراقبوا مدة ما بعد الفتح. المنتج منتهي الصلاحية ما يُستخدم ولا يُباع.','ملصق صغير على علبة الأوكسجين: «فُتحت ١٠/٥» مع رمز المدة بعد الفتح، والموقع يذكّر قبل انتهاء المدة.','قيمة المنتجات المرمية بسبب الانتهاء كل شهر، ونتيجة الجرد الأسبوعي للصلاحيات.','دائمًا، وخاصة مع الصبغات ومنتجات البشرة والمنتجات اللي تُفتح وتُستخدم على عدة عميلات.','رمز ما بعد الفتح جاي من اللائحة الأوروبية وليس نظامًا سعوديًا، لكنه مفيد كمرجع؛ المرجع الملزم هو تاريخ الصلاحية وتعليمات الهيئة العامة للغذاء والدواء.',array['silver-pyke-2017','eu-cosmetics-1223','rcu-guide-2022','sfda-cosmetics-law']::text[],'law',array['صلاحية','مخزون','تاريخ الفتح','منتجات','جرد']::text[],'kit',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-26','operations','مو كل الأصناف تستاهل نفس المتابعة','يقترح مرجع Silver وزملائه تصنيف الأصناف حسب أهميتها المالية (تصنيف ABC): القليل من الأصناف يشكّل غالبًا جزء كبير من قيمة المخزون، فيستاهل متابعة أدق.','رتبوا المنتجات حسب قيمة استهلاكها السنوية. الأصناف الغالية والمستهلكة كثير (البروتين، صبغات معينة) جرد أسبوعي ونقطة طلب دقيقة. المستهلكات الرخيصة (قطن، مناديل) متابعة أبسط بكمية ثابتة.','البروتين يُجرد كل أسبوع بالعدد، والمناديل تُطلب كرتون كل شهر بدون عدّ.','دقة الجرد في الأصناف الغالية (الفرق بين النظام والعدّ الفعلي)، والوقت المصروف على الجرد.','لما يكون الجرد متعب وياخذ وقت، أو لما تكتشفون فروقات في المنتجات الغالية.','النسب الشائعة مثل «٢٠٪ من الأصناف تمثل ٨٠٪ من القيمة» تقريبية وليست قاعدة؛ احسبوا التوزيع من بياناتكم.',array['silver-pyke-2017']::text[],'consensus',array['مخزون','ABC','جرد','تكلفة','أولويات']::text[],'kit',25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-27','operations','نظافة اليدين في لحظات محددة','تحدد منظمة الصحة العالمية خمس لحظات لنظافة اليدين في الرعاية: قبل لمس المريض، قبل الإجراء النظيف، بعد التعرض لسوائل الجسم، بعد لمس المريض، وبعد لمس محيطه.','عدّلوها للصالون: قبل لمس العميلة، قبل أي خدمة فيها جلد مجروح أو قريب منه (تنظيف البشرة، المناكير، الشمع)، بعد خلع القفازات، بعد كل عميلة، وبعد لمس الأدوات المستعملة والنفايات. ووفروا مغسلة أو معقم قريب من كل محطة.','لوحة صغيرة فوق مغسلة كل قسم توضح اللحظات الخمس بصيغة الصالون.','جولة ملاحظة أسبوعية تسجّل الالتزام، وتوفر الصابون والمعقم في كل محطة، وأي شكوى عدوى أو التهاب.','في تدريب كل موظفة جديدة، وبعد أي شكوى عن التهاب أو عدوى جلدية.','النموذج مصمم للمنشآت الصحية؛ الصالون يستفيد من المبدأ لكنه مو منشأة طبية، والمرجع الملزم هو اشتراطات البلدية.',array['who-hand-2009','rcu-guide-2022']::text[],'consensus',array['نظافة','أيدي','عدوى','تدريب','سلامة']::text[],'team',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-28','operations','التعقيم بعد كل عميلة والأدوات الأحادية','تنص الاشتراطات المحدّثة لمحلات التزيين النسائي على معايير لتعقيم الأدوات واستخدام الأدوات أحادية الاستخدام. والأدلة البلدية التفصيلية تطلب تنظيف الأدوات ثم تعقيمها بعد كل جلسة، وإتلاف الأدوات الأحادية بعد استخدامها.','قسّموا الأدوات لنوعين: أدوات تُعقم بعد كل عميلة (مقصات، أدوات أظافر معدنية) وأدوات تُرمى (أعواد الشمع، المبارد الورقية، المرايل البلاستيكية). عيدان الشمع ما ترجع للوعاء، والفرش والإسفنج تُنظف وتُعقم بين كل عميلة.','كل عميلة مناكير يُفتح لها كيس أدوات معقم أمامها، وهذا ممكن يكون نقطة ثقة تُذكر في التسويق.','سجل يومي لدورات جهاز التعقيم، ومخزون الأدوات الأحادية، ونتائج زيارات التفتيش البلدية.','دائمًا. وعند أي تفتيش، أو تحديث للاشتراطات، أو شكوى عن التهاب بعد خدمة.','التفاصيل الرقمية (عدد أجهزة التعقيم لكل كرسي، حرارة الماء) تختلف بين الأدلة؛ اعتمدوا النص الحالي من منصة بلدي وأمانة الأحساء.',array['momah-2025','rcu-guide-2022']::text[],'law',array['تعقيم','أدوات','استخدام واحد','بلدية','عدوى']::text[],'rules',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-29','operations','اشتراطات البلدية: الترخيص والخدمات المنزلية','حسب تحديث وزارة البلديات والإسكان لاشتراطات محلات التزيين النسائي: الترخيص يخضع لنظام إجراءات التراخيص البلدية، ويحتاج موافقة الدفاع المدني وسجل تجاري يشمل النشاط، مع فصل الاستقبال بجدار يمنع الرؤية ولوحة منع دخول الرجال، ولا تُقدَّم الخدمات خارج المحل إلا بترخيص خاص عبر منصة بلدي.','بما إن بيوتفريش يقدم خدمات منزلية، تأكدوا إن عندكم الترخيص الخاص بها في منصة بلدي، وإن السجل التجاري يغطي كل الأنشطة. وراجعوا الترخيص مع كل تجديد أو إضافة خدمة.','ملف في الموقع فيه: رخصة البلدية وتاريخ انتهائها، موافقة الدفاع المدني، ترخيص الخدمات المنزلية، مع تنبيه قبل الانتهاء بشهرين.','عدد الوثائق السارية من المطلوبة، والأيام المتبقية على أقرب انتهاء، وملاحظات التفتيش.','قبل إضافة أي خدمة جديدة أو توسيع الخدمات المنزلية، وعند التجديد السنوي، وقبل أي امتياز.','لا تعتمدون على ملخصات الأخبار؛ النص الكامل مرفق في صفحة الوزارة ويتحدث. ولا تذكرون غرامات بأرقام إلا من جدول المخالفات الرسمي.',array['momah-2025']::text[],'law',array['ترخيص','بلدي','خدمات منزلية','اشتراطات','دفاع مدني']::text[],'rules',28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-30','operations','شهادات صحية سارية لكل العاملات','اشترطت لائحة التزيين النسائي البلدية شهادات صحية للعاملات، والأدلة البلدية التفصيلية تشرح إنها تثبت الخلو من الأمراض المعدية وتُجدد قبل انتهائها، مع سجل رقابة صحية يُحفظ في المحل.','سجلوا لكل أخصائية وموظفة استقبال ومساعدة تاريخ انتهاء شهادتها الصحية في الموقع، مع تنبيه قبل الانتهاء. وأي موظفة تظهر عليها أعراض مرض معدي توقف عن الخدمة حتى تتعافى.','لوحة الفريق في الموقع تلوّن الشهادة بالأحمر إذا باقي أقل من شهر، وتمنع إدخال الموظفة الجديدة في الجدول قبل رفع شهادتها.','نسبة الشهادات السارية من إجمالي الفريق، وعدد الأيام اللي اشتغلت فيها موظفة بشهادة منتهية (المفروض صفر).','عند التوظيف، وقبل انتهاء أي شهادة، وقبل الزيارات التفتيشية.','مدة صلاحية الشهادة وطريقة إصدارها تُؤكد من منصة بلدي، لأن الإجراءات تتحدث.',array['momra-2015','rcu-guide-2022']::text[],'law',array['شهادة صحية','موظفات','بلدية','تجديد','فريق']::text[],'team',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-31','operations','منتجات مُدرجة لدى الهيئة فقط','يمنع نظام منتجات التجميل تداول أي منتج تجميلي قبل إدراجه لدى الهيئة العامة للغذاء والدواء، ويمنع تداول المنتج المغشوش أو منتهي الصلاحية. والأدلة البلدية للتزيين النسائي تمنع المستحضرات ذات الطبيعة الطبية وتمنع تحضير خلطات تجميلية وبيعها.','اشتروا من موردين موثوقين وتأكدوا إن المنتج مدرج لدى الهيئة قبل استخدامه أو بيعه في الصالون. لا تستخدمون منتجات من مصادر شخصية أو «شنطة سفر»، ولا تصنعون خلطات منزلية للبيع.','في بطاقة كل منتج بالموقع: المورد، ورقم الإدراج أو إثباته، وتاريخ الصلاحية.','نسبة المنتجات في المخزون اللي معها إثبات إدراج، وأي منتج يُكتشف بدون مصدر واضح.','عند إضافة منتج أو مورد جديد، أو بيع منتجات للعميلات، أو أي تحذير من الهيئة عن منتج.','اسم النظام الرسمي «نظام منتجات التجميل» (وليس «نظام مستحضرات التجميل»). وللتفاصيل والعقوبات ارجعوا للنص الرسمي ولائحته التنفيذية.',array['sfda-cosmetics-law','rcu-guide-2022','momra-2015']::text[],'law',array['هيئة الغذاء والدواء','منتجات','إدراج','مورد','نظام']::text[],'kit',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-32','operations','البروتين والكيراتين: تهوية وقراءة الملصق','أصدرت OSHA الأمريكية تنبيه خطر لأن بعض منتجات تنعيم الشعر تحتوي على الفورمالديهايد أو مواد تطلقه مع الحرارة، وقاست مستويات فوق حدها قصير المدى في صالونات. وتقول إن عبارة «خالي من الفورمالديهايد» على الملصق ما تضمن عدم التعرض.','اعتمدوا قائمة منتجات بروتين محددة مع صحيفة بيانات السلامة لكل منتج، وابحثوا فيها عن الفورمالديهايد وأسمائه البديلة (مثل الميثيلين جلايكول). قدموا الخدمة في مكان مهوّى جيدًا وبعيد عن باقي العميلات، ودرّبوا الأخصائيات على القفازات والتهوية.','خدمة البروتين تُحجز في محطة قريبة من شفاط مخصص، وما تنحجز جنبها خدمة أظافر أو مكياج في نفس الوقت.','شكاوى الأخصائيات أو العميلات من حرقة العين أو الأنف أو الصداع أثناء البروتين، ووجود صحيفة بيانات سلامة لكل منتج كيميائي.','عند اختيار منتج بروتين جديد، أو أي شكوى تهيج، أو تجديد التهوية.','OSHA جهة أمريكية؛ ذكرها هنا كمرجع علمي للخطر. المرجع الملزم في السعودية هو إدراج المنتج لدى الهيئة العامة للغذاء والدواء واشتراطات البلدية.',array['osha-formaldehyde','sfda-cosmetics-law']::text[],'evidence',array['بروتين','كيراتين','فورمالديهايد','تهوية','سلامة مهنية']::text[],'kit',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-33','operations','الليزر خدمة طبية تحتاج ترخيص صحي','حذّرت وزارة الصحة من إزالة الشعر بالليزر دون ترخيص، وأوضحت إنها تُمارس في منشأة صحية مرخصة ومن ممارس صحي حاصل على تصريح، وذكرت المشاغل ضمن المحلات غير المرخصة لها. ولائحة التزيين النسائي البلدية منعت الأجهزة الطبية والليزر في المشاغل، والهيئة العامة للغذاء والدواء أوقفت أجهزة ليزر بدون إذن تسويق.','قبل تقديم أو تسويق أي خدمة ليزر، تأكدوا رسميًا من وزارة الصحة وأمانة الأحساء إن الترخيص الحالي يسمح بها. الأسلم إن خدمة الليزر تكون داخل منشأة صحية مرخصة (مثل شراكة مع عيادة جلدية) ويقدمها ممارس مصرح، والجهاز معه إذن تسويق من الهيئة.','ملف خدمة الليزر في الموقع فيه: جهة الترخيص الصحي، اسم الممارس وتصريحه، إذن تسويق الجهاز، ونظارات الحماية وتاريخها.','اكتمال الوثائق الأربع قبل أي حجز ليزر، وأي ملاحظة تفتيش أو شكوى حرق.','قبل إضافة الليزر أو إزالة الشعر بالأجهزة، وقبل أي إعلان عنها، وعند الامتياز.','هذا مجال تتغير فيه الأنظمة وفيه عقوبات؛ لا يُعتمد على هذا الملخص كرأي نظامي. اسألوا وزارة الصحة والأمانة مباشرة واحفظوا الرد مكتوب.',array['moh-laser-2012','momra-2015','sfda-laser-2017']::text[],'law',array['ليزر','إزالة شعر','وزارة الصحة','ترخيص','أجهزة طبية']::text[],'rules',32) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-34','operations','الكاميرات خارجية فقط والخصوصية أولًا','لائحة التزيين النسائي البلدية منعت الكاميرات الداخلية وسمحت بالخارجية فقط، والأدلة البلدية تضيف حفظ التسجيل مدة محددة وتسليمه للجهات الرسمية عند الطلب.','لا تركبون أي كاميرا داخل الصالون حتى لو كان الهدف الأمان أو متابعة المخزون. استخدموا بدائل: جرد دوري، صلاحيات في النظام، وقفل المخزن. والكاميرات الخارجية تغطي المدخل فقط بدون كشف الداخل.','بدل كاميرا على المخزن، كل سحب منتج غالي يُسجل باسم الأخصائية في الموقع، والجرد الأسبوعي يكشف الفرق.','فروقات الجرد في الأصناف الغالية، وملاحظات التفتيش.','عند تجهيز فرع جديد أو تحديث نظام الأمان، أو لما تظهر مشكلة فقد منتجات.','تحقّقوا من النص الحالي في اشتراطات 2025 لأن التفاصيل ممكن تتحدث.',array['momra-2015','rcu-guide-2022']::text[],'law',array['كاميرات','خصوصية','أمان','بلدية','مخزون']::text[],'rules',33) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ops-35','operations','صيانة وقائية بجدول مو بعد العطل','الخطوة الثالثة في 5S تجمع التنظيف مع فحص المعدات، والأدلة البلدية تطلب صيانة أنظمة التهوية والتكييف وفق الكود السعودي. الفكرة: الصيانة تُجدول قبل ما يتعطل الجهاز وقت الزحمة.','سوّوا جدول صيانة في الموقع لكل جهاز: التكييف والشفاطات، أجهزة التعقيم، سخانات الماء والشمع، كراسي الغسيل، أجهزة البشرة، وغرفة الحمام المغربي (البخار والرطوبة والتصريف). كل جهاز له موعد فحص دوري ومسؤولة.','قبل موسم الأعراس والعيد بشهر: فحص شامل للتكييف والشفاطات وأجهزة التعقيم، لأن أي عطل وقتها يعني إلغاء مواعيد.','عدد الأعطال المفاجئة، والمواعيد الملغاة بسبب عطل، ونسبة الصيانات المنفذة في وقتها.','عند بداية كل سنة وقبل المواسم، ولما يتكرر عطل نفس الجهاز.',null,array['lei-lexicon','rcu-guide-2022']::text[],'practice',array['صيانة','أجهزة','تكييف','تهوية','مواسم']::text[],'kit',34) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-01','people','الأساسيات قبل الحماس: وضوح المطلوب والأدوات','أبحاث Gallup اللي طلعت منها أسئلة Q12 تقول إن الارتباط بالعمل يبدأ من القاعدة: الموظفة تعرف وش المتوقع منها، وعندها الأدوات والمواد اللي تحتاجها عشان تشتغل صح. بعدها تجي الأمور الأعلى مثل التقدير والتطور والمعنى.','قبل أي برنامج تحفيز، تأكدون إن كل أخصائية تعرف بالضبط معايير خدمتها (مدة الخدمة، خطوات الاستشارة، متى تحجز الزيارة الجاية) وإن أدواتها ومنتجاتها متوفرة قبل الدوام. نقص صبغة أو جهاز معطل يهد الحماس أسرع من أي شي ثاني.','تسوون بطاقة «معيار الخدمة» لكل خدمة رئيسية (صبغة، بروتين، تنظيف بشرة) في صفحة الفريق، ومعها قائمة تجهيز صباحية تتأكد منها الاستقبال: المنتجات، المناشف، الأجهزة.','عدد مرات تأجيل أو تعديل خدمة بسبب نقص مواد أو أدوات في الشهر، ونسبة الالتزام بمدة الخدمة المحددة في ركاز.','لما تشتكي الأخصائيات من الفوضى، أو تختلف جودة نفس الخدمة من أخصائية لأخصائية.','أسئلة Q12 أداة مملوكة لـ Gallup ولها صياغة محمية؛ استخدموا الفكرة وصيغوا أسئلتكم بكلامكم، ولا تعتبرون استبيانكم الداخلي مطابقًا لمقياس Gallup.',array['buckingham-fbar']::text[],'evidence',array['ارتباط','وضوح الدور','أدوات','Q12','معايير الخدمة']::text[],'team',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-02','people','حددوا النتيجة واتركوا الطريقة للأخصائية','حسب Buckingham وCoffman، المديرون المتميزون يختارون الموهبة، ويحددون النتائج المطلوبة بوضوح بدل ما يفرضون كل خطوة، ويركزون على نقاط قوة الشخص، ويحطونه في المكان اللي يناسبه.','في الخدمات الفنية حددوا النتيجة: رضا العميلة، صحة الشعر بعد الصبغة، رجوعها خلال المدة المعتادة. وخلّوا للأخصائية مساحة في أسلوبها. الخطوات الإلزامية تكون فقط في السلامة والنظافة (اختبار الحساسية، التعقيم).','بدل ما تقولون «سوي البلياج بهذي الطريقة بالضبط»، تقولون: المطلوب لون مطابق للصورة اللي اختارتها العميلة، بدون تقصف، وصورة قبل وبعد في ملفها.','نسبة رجوع عميلات كل أخصائية، وعدد طلبات إعادة الخدمة أو التعديل المجاني.','لما تحسون إنكم تراقبون كل تفصيلة بنفسكم، أو الأخصائيات الخبيرات يشتكون من التدخل.','ترك الطريقة مقبول في الجانب الفني فقط؛ إجراءات السلامة والنظافة والليزر لازم تكون موحدة وغير قابلة للتفاوض.',array['buckingham-fbar']::text[],'practice',array['إدارة بالنتائج','استقلالية','معايير','ثقة']::text[],'team',1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-03','people','وزّعوا الخدمات حسب نقاط القوة','مدرسة Gallup لنقاط القوة ترى إن أكبر مجال لنمو الشخص هو في المجالات اللي هو قوي فيها أصلًا، وإن الاستثمار في تطوير القوة يعطي أكثر من محاولة إصلاح كل ضعف.','اعرفوا وش تتميز فيه كل أخصائية: وحدة ممتازة في الألوان، ثانية في التعامل مع العرايس، ثالثة في هدوء جلسات البشرة. وجّهوا الحجوزات والعميلات الجدد حسب ذلك في ركاز، وخلّوا التدريب يعمّق تميزها.','في موسم الأعراس توجّهون حجوزات مكياج العرايس للأخصائية اللي تقييماتها الأعلى في المكياج، وتدربون الثانية معها كمساعدة بدل ما توزعونها بالتساوي.','متوسط تقييم كل أخصائية حسب نوع الخدمة، ومتوسط الفاتورة لكل أخصائية في تخصصها مقارنة بغيره.','لما يكون توزيع الحجوزات عشوائي، أو أخصائية تتعب في خدمة ما تحبها وتتميز في غيرها.','التركيز على القوة ما يعني تجاهل ضعف يمس السلامة أو تجربة العميلة الأساسية؛ هذا لازم يتعالج بالتدريب. وانتبهوا لا يصير التخصص سبب إن أخصائية تاخذ كل الحجوزات المربحة والباقيات يقل دخلهم.',array['buckingham-clifton-strengths','buckingham-fbar']::text[],'practice',array['نقاط القوة','توزيع الحجوزات','تخصص','تطوير']::text[],'team',2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-04','people','الأمان النفسي: خلّوا الغلطة تنقال بسرعة','Edmondson وجدت إن الفرق اللي أعضاؤها يحسون بأمان يسمح لهم يعترفون بالأخطاء ويسألون ويطرحون مخاوفهم بدون خوف من الإحراج أو العقاب، تتعلم أكثر، وهذا التعلم مرتبط بأداء أفضل.','في الصالون الغلطة المخفية أخطر من الغلطة المعلنة: تفاعل حساسية، لون طلع غلط، حرق بسيط من جهاز. لازم الأخصائية تبلغ فورًا بدون ما تخاف من التوبيخ أمام الزميلات، عشان تتصرفون مع العميلة قبل ما تكتب تقييم سيئ.','تخصصون خمس دقائق في اجتماع الأسبوع لـ«وش تعلمنا هالأسبوع؟»، وأول وحدة تتكلم عن غلطتها الشريكة نفسها، عشان تعطي المثال.','عدد الحوادث المسجلة في سجل الملاحظات (المفروض يرتفع أول فترة لأن الإبلاغ زاد)، مقابل عدد الشكاوى اللي توصل من العميلات بدون ما يكون الفريق بلّغ عنها.','لما تكتشفون مشاكل من التقييمات قبل ما تسمعونها من الفريق، أو الأخصائيات يسكتون في الاجتماعات.','الأمان النفسي ما يعني التساهل مع تكرار نفس الخطأ أو الإهمال؛ هو أن الإبلاغ ما يُعاقب، أما المعايير فتبقى عالية.',array['edmondson-1999']::text[],'evidence',array['أمان نفسي','أخطاء','إبلاغ','تعلم','شكاوى']::text[],'team',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-05','people','طريقة شغل الفريق أهم من مين فيه','بحث Google (مشروع أرسطو) وجد إن طريقة تعامل الفريق مع بعض أهم من تركيبته، ورتّب خمس ديناميكيات: الأمان النفسي أولًا، ثم الاعتمادية، ثم وضوح الهيكل والأدوار، ثم المعنى، ثم الإحساس بالأثر.','بدل ما تدورون على «الأخصائية الخارقة»، اشتغلوا على علاقة الفريق: تسليم العميلة بين الأخصائيات يكون واضح، المواعيد تنحترم، كل وحدة تعرف دورها، والكل يشوف أثر شغله على العميلة.','لما عميلة تسوي صبغة ثم أظافر، الأخصائية الأولى تبلغ الثانية بالوقت المتوقع بالضبط عبر ركاز أو الاستقبال، فما تنتظر العميلة ولا تنضغط الثانية.','متوسط تأخر بدء الخدمات عن موعدها، وملاحظات العميلات عن الانتظار في التقييمات.','لما يكون عندكم أخصائيات ممتازات فرديًا لكن تجربة العميلة متقطعة أو فيها احتكاك.','هذا بحث داخل شركة تقنية كبيرة؛ Google نفسها تنبّه إن عوامل مثل حجم الفريق ممكن تفرق في بيئات ثانية. خذوا الترتيب كدليل، مو كقانون.',array['google-aristotle','edmondson-1999']::text[],'evidence',array['فريق','تعاون','اعتمادية','أدوار','تسليم العميلة']::text[],'team',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-06','people','الاستقلالية والإتقان والهدف في الشغل الإبداعي','Pink يلخص أبحاث الدافعية في ثلاث محركات للعمل اللي يحتاج إبداع وتفكير: الاستقلالية في كيف ومتى أشتغل، والإتقان والتحسن المستمر، والهدف أو المعنى من الشغل.','الشعر والمكياج شغل إبداعي، فالأخصائية تتحمس لما يكون لها رأي في الأسلوب، ومسار واضح تتقن فيه تقنيات جديدة، وتحس إن شغلها يفرّح العميلة في مناسبة مهمة لها.','كل أخصائية تختار تقنية وحدة تبي تتقنها هالربع (مثل البالياج أو مكياج العرايس الناعم)، والصالون يوفر لها تدريب وعميلات للتطبيق، وتعرض شغلها في حساب الصالون باسمها.','عدد الخدمات الجديدة اللي صارت كل أخصائية قادرة تقدمها، ونسبة بقاء الأخصائيات في الصالون (دوران الموظفات).','لما تحسون الأخصائيات الخبيرات ملّوا أو يفكرون يطلعون لصالون ثاني.','Pink نفسه يفرّق: هذي المحركات أقوى في الشغل غير الروتيني. والكتاب تبسيط شعبي للأبحاث، فالأصل العلمي هو نظرية تقرير المصير (ppl-11).',array['pink-drive']::text[],'consensus',array['تحفيز','استقلالية','إتقان','معنى','إبداع']::text[],'team',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-07','people','الشغل الروتيني يحتاج توجيه واضح مو إلهام','Pink يوضح إن المكافآت المشروطة «إذا سويتي كذا تاخذين كذا» أقل ضررًا في المهام الروتينية اللي ما فيها دافع داخلي كبير أصلًا، وإن العمل الروتيني يحتاج توجيه، بينما العمل غير الروتيني يعتمد على التوجيه الذاتي.','التعقيم، ترتيب المحطة، جرد المنتجات، تسجيل الخدمة في ركاز: هذي مهام روتينية تنجح فيها قوائم واضحة ومتابعة ومكافأة بسيطة، مو محاضرات عن الشغف.','قائمة تعقيم وإغلاق يومية بخانات تأشير، والاستقبال تراجعها، والفريق اللي يلتزم شهر كامل ياخذ مكافأة جماعية بسيطة.','نسبة أيام الالتزام بقائمة الإغلاق، وملاحظات النظافة في تقييمات العميلات.','لما تنهمل مهام النظافة والتجهيز رغم إن الخدمات الفنية ممتازة.','حتى في الروتين، الشرح ليش المهمة مهمة (سلامة العميلة، سمعة الصالون) يرفع الالتزام. ولا تخلطون: مكافأة على التعقيم شي، ومكافأة مشروطة على الإبداع شي ثاني.',array['pink-drive']::text[],'practice',array['روتين','نظافة','تعقيم','قوائم','مكافآت']::text[],'rules',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-08','people','المكافأة المفاجئة بعد الإنجاز أسلم من الوعد المسبق','حسب Pink، إذا بتعطون مكافأة خارجية على شغل إبداعي، الأفضل تكون غير متوقعة وتنعطى بعد انتهاء العمل، لأن الوعد المسبق يحوّل الشغل الممتع إلى وسيلة ويقلل الإحساس بالاستقلالية.','بدل «اللي تجيب أعلى تقييم هالشهر تاخذ جائزة»، لاحظوا الشغل المميز بعد ما يصير وكافئوه بشكل مفاجئ ومحدد.','عروس كتبت تقييم مؤثر عن مكياجها، فالشريكة تشكر الأخصائية قدام الفريق وتهديها يوم إجازة إضافي أو قسيمة، بدون ما يكون فيه مسابقة معلنة.','عدد التقييمات اللي تذكر اسم أخصائية بالمدح، ومقارنتها قبل وبعد تطبيق التقدير المفاجئ.','لما تفكرون تسوون مسابقات شهرية على التقييمات أو المبيعات.','المكافأة المفاجئة لو صارت منتظمة كل شهر تتحول لوعد متوقع وتفقد الفكرة.',array['pink-drive','deci-koestner-ryan-1999']::text[],'evidence',array['تقدير','مكافأة','مفاجأة','تقييمات','مسابقات']::text[],'team',7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-09','people','أصلحوا مسببات الاستياء أولًا','Herzberg فرّق بين عوامل صحية (الراتب، ظروف العمل، الإشراف، العلاقات، الأمان الوظيفي) غيابها يسبب الاستياء لكن وجودها ما يحفز بحد ذاته، وبين دوافع حقيقية مثل الإنجاز والتقدير والمسؤولية والنمو.','ما ينفع تحفيز أخصائية رواتبها تتأخر، أو غرفة الاستراحة ضيقة، أو جدولها يتغير كل يوم. صلّحوا هذي أولًا لأنها تمنع الاستياء، ثم ابنوا التحفيز فوقها.','تثبيت موعد صرف الرواتب، وتجهيز ركن استراحة نظيف فيه مكان للصلاة والأكل، قبل إطلاق أي برنامج حوافز.','أسباب الاستقالة أو الشكوى المسجلة في ملفات الفريق، ونسبة الغياب غير المخطط.','لما تسمعون تذمر عام من الظروف، أو الحوافز ما تجيب نتيجة.','النظرية مبنية على مقابلات يتذكر فيها الناس مواقف، وتقسيمها الحاد بين النوعين ما هو مسلّم عند كل الباحثين؛ في الصالونات مثلًا الدخل المرتبط بالأداء ممكن يحفز فعلًا. استخدموها كقائمة فحص، مو كقانون.',array['herzberg-1959']::text[],'practice',array['رضا','استياء','رواتب','ظروف العمل','استراحة']::text[],'team',8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-10','people','المسؤولية والنمو يحفزون أكثر من المزايا','الشق الثاني من نظرية Herzberg: الدوافع اللي ترفع الرضا فعلًا مرتبطة بالشغل نفسه، مثل الإنجاز والتقدير والمسؤولية وفرص التقدم.','أعطوا الأخصائية المتميزة مسؤولية حقيقية: تدريب الجديدات، الإشراف على قسم الأظافر، اختيار منتجات قسمها. هذا يرفع انتماءها أكثر من ميزة مادية صغيرة.','أقدم أخصائية بشرة تصير مسؤولة عن قسم البشرة: تقترح البروتوكولات وتراجع جودة شغل الزميلات وتشارك في اختيار المورد.','استمرار الأخصائيات المتميزات (مدة البقاء)، وجودة القسم اللي تشرف عليه (تقييمات القسم وتكرار زيارات عميلاته).','لما ما عندكم سلّم وظيفي واضح والمتميزات يحسون إنهم وصلوا السقف.','المسؤولية الإضافية بدون صلاحية أو مقابل تتحول لعبء؛ وضّحوا الصلاحيات والمقابل كتابيًا.',array['herzberg-1959']::text[],'practice',array['مسؤولية','ترقية','نمو','إشراف','سلم وظيفي']::text[],'team',9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-11','people','ثلاث حاجات نفسية: الاستقلالية والكفاءة والانتماء','نظرية تقرير المصير (Ryan وDeci) تقول إن الدافعية الذاتية والرفاه يزيدون لما تنشبع ثلاث حاجات: الاستقلالية (إحساس الشخص إنه يختار)، والكفاءة (إحساسه إنه قادر ويتحسن)، والانتماء (إحساسه إنه مرتبط بالناس حوله).','اسألوا عن كل قرار إداري: هل يعطي الأخصائية خيار؟ هل يحسسها إنها تتقن؟ هل يقربها من الفريق؟ مثلًا: خيارات في الجدول، تدريب يوصلها لمستوى أعلى، وجلسات جماعية.','لما تضيفون خدمة جديدة (مثل نوع بروتين جديد)، تختار الأخصائيات مين تبي تتدرب عليها أول، يتدربون مع بعض، وأول من تتقنها تدرب البقية.','استبيان ربع سنوي قصير بأسئلتكم أنتم عن الإحساس بالاختيار والتطور والانتماء، مع تتبع الدوران.','لما تصممون أي نظام جديد (حوافز، جداول، تدريب) وتبون تتأكدون إنه ما يقتل الحماس.',null,array['ryan-deci-2000']::text[],'evidence',array['دافعية ذاتية','استقلالية','كفاءة','انتماء','تقرير المصير']::text[],'team',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-12','people','المكافأة المادية المشروطة ممكن تضعف الحماس الداخلي','التحليل التجميعي لـ Deci وKoestner وRyan وجد إن المكافآت المادية المتوقعة والمشروطة بأداء المهمة تميل تضعف الدافعية الذاتية للمهام الممتعة، بينما المديح والملاحظة الإيجابية الشفهية تميل ترفعها.','قبل ما تربطون كل شي بالفلوس (عمولة على كل منتج، بونص على كل تقييم)، تذكرون إن الأخصائيات يحبون شغلهم أصلًا. الكلمة الإيجابية المحددة من الشريكة لها أثر حقيقي، ومجانية.','بدل بونص على كل عبوة شامبو تنباع، الاستقبال تشارك في مجموعة الفريق رسالة عميلة رجعت تشكر أخصائية على نصيحة المنتج.','نسبة العميلات اللي يشترون منتج بعد الخدمة، ومقارنتها مع شكاوى «ضغط البيع» في التقييمات.','لما تصممون عمولات المنتجات أو حوافز التقييمات.','فيه نقاش علمي حول هذا الأثر وحجمه؛ باحثون آخرون رأوا إن المكافآت أقل ضررًا مما يُقال. والصالون يحتاج دخل عادل مرتبط بالأداء، فالمطلوب التوازن مو إلغاء الحوافز.',array['deci-koestner-ryan-1999']::text[],'evidence',array['حوافز','عمولة','مديح','دافعية','بيع المنتجات']::text[],'sales',11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-13','people','الخصم والغرامة ممكن يصيرون «سعر» للمخالفة','في تجربة Gneezy وRustichini بدور حضانة، فرض غرامة على تأخر الأهالي زاد التأخر بدل ما يقلله، لأن الغرامة حوّلت الإحساس بالواجب إلى صفقة مدفوعة، واستمر التأخر الزائد حتى بعد إلغاء الغرامة.','لو تحطون خصم ثابت على التأخر الصباحي، ممكن بعض الأخصائيات يعتبرونه «سعر» ويتأخرون مرتاحين. ركزوا على الالتزام كاحترام للعميلات والزميلات، والتعامل الفردي مع المتكررة.','بدل خصم تلقائي، الشريكة تكلم الأخصائية المتأخرة على انفراد: عميلتك الساعة عشرة انتظرت عشرين دقيقة، وش اللي يساعدك تلتزمين؟ ومع التكرار تطبقون لائحة الجزاءات المعتمدة.','عدد مرات التأخر عن أول موعد في اليوم، وعدد المواعيد اللي تأخر بدؤها بسبب الأخصائية.','لما تفكرون تحطون خصومات أو غرامات على التأخر أو الغياب.','هذا ما يلغي لائحة تنظيم العمل والجزاءات النظامية؛ هو تنبيه إن الغرامة وحدها ممكن ترسل رسالة غلط. وأي جزاء مالي لازم يكون متوافق مع نظام العمل ولائحة المنشأة.',array['gneezy-fine-2000']::text[],'evidence',array['غرامات','خصم','تأخر','التزام','اقتصاد سلوكي']::text[],'rules',12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-14','people','الثقة أساس الفريق والنتائج في القمة','Lencioni يصور مشاكل الفرق كهرم: غياب الثقة يسبب الخوف من الخلاف، وهذا يسبب التزام ضعيف بالقرارات، ثم تهرّب من محاسبة الزميلات، وأخيرًا ضياع التركيز على النتائج الجماعية لحساب المصالح الفردية.','إذا الأخصائيات يتكلمون عن بعض بدل ما يتكلمون مع بعض، أو كل وحدة تهتم بعميلاتها بس، المشكلة غالبًا في أساس الهرم. ابدأوا ببناء الثقة قبل ما تطلبون المحاسبة.','في اجتماع شهري، كل أخصائية تشارك وش تحتاج من زميلاتها عشان يومها يمشي أسهل، والشريكتين يبدأون بأنفسهم ويعترفون وش ممكن يسوون أحسن.','عدد الخلافات اللي توصل للإدارة، ونسبة الخدمات المشتركة (عميلة تاخذ خدمتين من أخصائيتين) اللي تمت بدون تأخير أو شكوى.','لما تكثر النميمة أو الشلل داخل الفريق، أو تتكرر نفس المشاكل بدون حل.','الكتاب قصة إدارية مبنية على خبرة استشارية، مو دراسة تجريبية؛ استخدموه كأداة تشخيص.',array['lencioni-2002']::text[],'practice',array['ثقة','فريق','محاسبة','نتائج','شلل']::text[],'team',13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-15','people','الخلاف على الفكرة صحي، والخلاف الشخصي يُعالج بسرعة','Lencioni يرى إن الفرق القوية تتناقش بصراحة في الأفكار والقرارات، وإن تجنب النقاش بحجة المجاملة يطلع قرارات ضعيفة ما يلتزم بها أحد. المطلوب نقاش على الموضوع، مو هجوم على الشخص.','لما تختلف أخصائيتين على توزيع العميلات أو المناوبات، لا تتركونه يتراكم ولا تحسمونه بسرعة بدون سماعهم. اجمعوهم، خلّوا كل وحدة تطرح وجهة نظرها عن المشكلة نفسها، ثم قرار واضح يلتزم به الكل.','خلاف على مين تاخذ العميلات الجديدات اللي ما حددوا أخصائية: تجلسون مع الطرفين، تتفقون على قاعدة مكتوبة (بالدور، أو حسب التخصص)، وتنحفظ في صفحة القواعد.','عدد الخلافات المتكررة على نفس الموضوع (المفروض يقل بعد كتابة القاعدة).','لما يكون فيه احتقان صامت، أو نفس الخلاف يرجع كل شهر.','لو الخلاف تحوّل لإساءة أو تنمر أو مخالفة نظامية، هذا ما يُعالج بالنقاش بس؛ يتطبق عليه لائحة تنظيم العمل.',array['lencioni-2002','edmondson-1999']::text[],'practice',array['خلاف','نزاع','قرارات','توزيع العميلات','مناوبات']::text[],'rules',14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-16','people','الصراحة مع الاهتمام: لا مجاملة تضر ولا قسوة','Kim Scott تقول إن الملاحظة الفعالة تجمع بين الاهتمام الشخصي بالموظف والتحدي المباشر له. المجاملة اللي تسكت عن المشكلة عشان ما تجرح (تسميها التعاطف المدمّر) تضر الموظف أكثر من الصراحة.','في بيئة الأحساء القريبة اجتماعيًا، سهل تسكتون عن أخصائية شغلها تراجع عشان العشرة. لكن السكوت يخليها تخسر عميلاتها بدون ما تعرف ليش. قولوا الملاحظة بوضوح ومن منطلق إنكم تبونها تنجح.','«لاحظت إن ثلاث عميلات من عميلاتك ما رجعوا بعد البروتين الشهر هذا. أنا أبيك تكونين أقوى وحدة في البروتين، تعالي نشوف مع بعض وش اللي صار في الخطوات».','نسبة رجوع عميلات الأخصائية بعد الملاحظة بشهرين، مقارنة بقبلها.','لما تلاحظون تراجع في أداء أخصائية وتترددون تكلمونها.','الصراحة تكون على السلوك والشغل، في وقته، وعلى انفراد في حالة النقد. المدرسة نفسها تحذر من الصراحة بدون اهتمام لأنها تتحول لقسوة.',array['scott-candor']::text[],'practice',array['ملاحظات','صراحة','تقييم الأداء','كوتشينغ','تراجع أداء']::text[],'team',15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-17','people','أهداف محددة وصعبة أفضل من «سوي أحسن ما عندك»','Locke وLatham يلخصون عقود من الأبحاث: الأهداف المحددة والصعبة تؤدي لأداء أعلى من الأهداف المبهمة مثل «ابذل جهدك»، بشرط الالتزام بالهدف ووجود تغذية راجعة عن التقدم.','بدل «نبي مبيعات منتجات أكثر»، حطوا هدف محدد لكل أخصائية مبني على أرقامها هي من ركاز، أعلى شوي من مستواها الحالي، مع تحديث أسبوعي تشوف فيه وين وصلت.','أخصائية الشعر هدفها هالشهر إن عدد العميلات اللي يحجزون موعدهم الجاي قبل ما يطلعون يرتفع عن مستواها في الشهر الماضي، وتشوف رقمها كل أحد في صفحة الفريق.','نسبة الحجز المسبق للزيارة الجاية، ومتوسط الفاتورة، لكل أخصائية مقارنة بخط الأساس حقها.','لما تبون تحسين رقم معين وواضح (الحجز المسبق، بيع المنتجات، الخدمات الإضافية).','الهدف الصعب جدًا أو المربوط بمكافأة كبيرة ممكن يدفع لضغط البيع على العميلة أو التلاعب بالأرقام. والهدف لازم يكون في شي تقدر الأخصائية تتحكم فيه.',array['locke-latham-2002']::text[],'evidence',array['أهداف','أداء','مبيعات','حجز مسبق','تغذية راجعة']::text[],'sales',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-18','people','للمهارة الجديدة: هدف تعلم قبل هدف أرقام','من نتائج Locke وLatham إن المهام المعقدة الجديدة على الشخص يكون فيها هدف التعلم (إتقان الاستراتيجية الصح) أنفع من هدف الأداء الرقمي، لأن الضغط على الرقم بدري يشتت عن التعلم.','الأخصائية الجديدة أو اللي تتعلم خدمة جديدة (الليزر، الحمام المغربي) لا تحاسبونها على عدد العميلات أو المبيعات أول فترة؛ حاسبوها على إتقان خطوات البروتوكول.','أخصائية جديدة في الليزر، هدفها أول شهر: تطبيق خطوات الاستشارة واختبار البقعة والإعدادات صح في كل جلسة تحت إشراف، وبعدها يبدأ هدف الحجوزات.','نسبة الجلسات المطابقة للبروتوكول في مراجعة المشرفة، وعدد الملاحظات أو المضاعفات.','مع كل موظفة جديدة، أو خدمة جديدة تدخل الصالون.',null,array['locke-latham-2002']::text[],'evidence',array['تدريب','مهارة جديدة','أهداف تعلم','ليزر','موظفة جديدة']::text[],'team',17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-19','people','التقدم اليومي الصغير يرفع الحماس','Amabile وKramer وجدوا من يوميات الموظفين إن أقوى شي يرفع المزاج والحماس في يوم العمل هو الإحساس بالتقدم في شغل له معنى، حتى لو كان تقدم صغير، وإن العوائق والانتكاسات تأثيرها السلبي قوي.','دور الإدارة إنها تشيل العوائق اليومية من طريق الأخصائيات (نقص منتج، جهاز خربان، جدول مضغوط) وتخليهم يشوفون تقدمهم.','لوحة أسبوعية في صفحة الفريق تعرض «إنجازات الأسبوع»: أول عميلة بالياج لأخصائية متدربة، تقييم مميز، عميلة رجعت بعد غياب طويل.','عدد العوائق المبلغ عنها اللي انحلّت خلال ٤٨ ساعة، ومزاج الفريق في استبيان قصير شهري.','لما يكون الضغط عالي (موسم الأعراس، العيد، رمضان) والفريق متعب.',null,array['amabile-kramer-2011']::text[],'evidence',array['تقدم','إنجازات صغيرة','حماس','عوائق','مواسم']::text[],'team',18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-20','people','التقدير المحدد والمتكرر جزء من الإدارة اليومية','أبحاث Gallup اللي بني عليها كتاب Buckingham وCoffman تجعل التقدير على الشغل الجيد خلال فترة قريبة من علامات الفريق المرتبط بعمله، ونظرية تقرير المصير تبين إن الملاحظة الإيجابية الشفهية تدعم الدافعية.','التقدير يكون محدد (وش اللي سوته بالضبط وأثره على العميلة)، وقريب من وقت الحدث، وبالطريقة اللي تحبها الأخصائية: بعضهم يحب قدام الفريق، وبعضهم يفضّل كلمة خاصة.','الشريكة تكتب للأخصائية: «العميلة اللي كانت خايفة من الصبغة طلعت مبسوطة وحجزت مرة ثانية، طريقتك في طمأنتها فرقت».','استبيان الفريق: هل حسيتي بتقدير على شغلك خلال الأسبوعين الماضية؟ مع متابعة الدوران.','دائمًا، وخصوصًا بعد المواسم المزدحمة أو مع أخصائيات جدد.','التقدير العام والمكرر («يعطيكم العافية كلكم») ما يكفي؛ ولا يكون التقدير دائمًا لنفس الأخصائية المتميزة.',array['buckingham-fbar','deci-koestner-ryan-1999']::text[],'consensus',array['تقدير','مديح','شكر','ارتباط','استبقاء']::text[],'team',19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-21','people','العمولة: تحفز الإنتاجية لكن لها أثمان','العمولة على الخدمات ممارسة شائعة في صناعة التجميل. أدلة الصناعة تبين إنها بسيطة وتناسب الأخصائية اللي جدولها ممتلئ، لكنها صعبة على الجديدات، ونفس النسبة تنطبق على الخدمة الرخيصة والغالية، ورواتب الخدمة ترتفع مع المبيعات بغض النظر عن تكاليف الصالون.','قبل ما تعتمدون نسبة عمولة، احسبوها على أرقام أضعف شهر عندكم مو أقواه، واحسبوا نسبة إجمالي رواتب الخدمة من إجمالي الإيراد. وانتبهوا إن العمولة الفردية ممكن تخلي كل أخصائية «مستقلة» تتنافس على العميلات.','تجربون جدول العمولة المقترح على أرقام رمضان أو الشهور الهادية من ركاز، وتشوفون هل يبقى للصالون هامش يغطي الإيجار والمنتجات وحصة الشريكتين.','نسبة رواتب الخدمة من إجمالي الإيراد شهريًا، وعدد الخلافات على توزيع العميلات.','لما تصممون أو تراجعون نظام الأجور، أو لما يكثر التنافس بين الأخصائيات على العميلات.','هذي ممارسة صناعة، مو دراسة محكّمة. والنسب المتداولة في المصادر الأمريكية ما تنطبق بالضرورة على السوق السعودي وتكاليفه.',array['zenoti-commission','ducoff-tbp']::text[],'practice',array['عمولة','أجور','رواتب','تكاليف','تنافس']::text[],'sales',20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-22','people','الأجر الجماعي: راتب ثابت مع مكافأة على أداء الفريق','Neil Ducoff من Strategies يدافع عن نظام أجر قائم على الفريق: الأخصائية تاخذ أجر بالساعة أو ثابت، والمكافأة مرتبطة بأهداف الصالون وبعوامل أوسع من المبيعات مثل رجوع العميلات الجدد والتطور الفني والالتزام والعمل الجماعي.','يناسب الصالون اللي يبي فريق متعاون وتجربة موحدة للعميلة، خصوصًا لو تبون مستقبلًا نموذج امتياز تجاري يعتمد على النظام مو على نجمة وحدة.','راتب ثابت لكل أخصائية حسب مستواها، ومكافأة ربع سنوية للفريق كامل لو ارتفعت نسبة رجوع العميلات الجدد للزيارة الثانية، مع جزء فردي على التطور الفني.','نسبة رجوع العميلات الجدد للزيارة الثانية، ودوران الموظفات، ونسبة الرواتب من الإيراد.','لما يكون التنافس الفردي يضر تجربة العميلة، أو تبون تبنون نظام قابل للتكرار في فروع.','المصدر رأي ممارس يبيع تدريب على هذا النظام، ونقاده يرون إن الأخصائيات عاليات الإنتاج ممكن يطلعون لصالونات بالعمولة. أي تحويل يحتاج تدرج وشفافية واتفاق مكتوب.',array['ducoff-tbp']::text[],'practice',array['أجر جماعي','راتب ثابت','مكافأة الفريق','امتياز تجاري','تعاون']::text[],'sales',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-23','people','الأنظمة المختلطة والشرائح: وضوح وشفافية قبل كل شي','أدلة الصناعة تعرض بدائل: عمولة بشرائح ترتفع مع الإيراد، أو راتب أساسي مع عمولة، أو خصم تكلفة المنتجات المستهلكة قبل احتساب العمولة، وعمولة منفصلة وأقل على بيع المنتجات. لكل نوع مزايا ومخاطر.','الراتب الأساسي مع العمولة يعطي الأخصائية استقرار ويسمح لكم تجدولون تدريب وأعمال غير الخدمة، والشرائح تعطي مسار واضح لزيادة الدخل. أما خصم تكلفة المنتجات فيحمي هامش خدمات مثل الصبغة والبروتين، بشرط تكون الحسبة مكشوفة للأخصائية.','راتب أساسي ثابت لكل أخصائية، وعمولة تبدأ بعد حد إيراد شهري، وشريحة أعلى لما توصل حد ثاني، وكل هذا ظاهر لها في صفحة خاصة تشوف فيها أرقامها.','عدد الأخصائيات اللي يوصلون كل شريحة (لو ما أحد يوصل، الحدود غير واقعية)، ونسبة الرواتب من الإيراد في الشهور الهادية.','لما تعيدون تصميم الأجور أو تضيفون أخصائيات جدد ما عندهم قاعدة عميلات.','الشرائح اللي ما توصلها أحد تحبط، وخصم تكلفة المنتجات بدون شفافية تحسه الأخصائية تخفيض مخفي للدخل. المصدر شركة برمجيات صالونات، فاقرأوه كممارسة.',array['zenoti-commission']::text[],'practice',array['شرائح','راتب وعمولة','تكلفة المنتجات','عمولة المنتجات','شفافية']::text[],'sales',22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-24','people','التهيئة بالـ C الأربعة: نظام، وضوح، ثقافة، علاقات','دليل SHRM (Bauer) يقسم تهيئة الموظف الجديد لأربع مستويات: الامتثال للأنظمة والسياسات، والوضوح في الدور والتوقعات، والثقافة وطريقة الشغل غير المكتوبة، والعلاقات مع الزملاء. التهيئة القوية تتجاوز الأوراق إلى الثقافة والعلاقات.','أول أسبوعين للأخصائية الجديدة مخططين: الأوراق والعقد ولائحة العمل، ثم معايير الخدمة والسلامة، ثم «كيف نتعامل مع عميلاتنا في بيوتفريش»، مع زميلة مرافقة تعرفها على الفريق.','خطة مكتوبة في صفحة الفريق: اليوم الأول جولة وتعريف وعقد، الأسبوع الأول مراقبة ومساعدة لأخصائية خبيرة، الأسبوع الثاني خدمات تحت إشراف، ونهاية الشهر جلسة مراجعة مع الشريكة.','نسبة الموظفات الجدد اللي يكملون فترة التجربة، وتقييمات أول عشرين عميلة لكل موظفة جديدة.','مع كل تعيين جديد، وخصوصًا قبل المواسم لما تتوظف أكثر من وحدة مرة وحدة.',null,array['bauer-shrm-2010']::text[],'practice',array['تهيئة','موظفة جديدة','تدريب','فترة التجربة','ثقافة']::text[],'team',23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-25','people','الجدول المستقر ينعكس على المبيعات والإنتاجية','في تجربة Williams وزملائها العشوائية بمتاجر Gap، الفروع اللي طبّقت ممارسات جداول أكثر ثباتًا وقابلية للتوقع سجلت ارتفاع في المبيعات بنحو ٧٪ وفي إنتاجية العمل بنحو ٥٪ مقارنة بالفروع الضابطة. ووجدت الدراسة إن تقلب الطلب ما يفسر إلا جزء صغير من تقلب الساعات.','نشر الجدول قبل فترة كافية، وثبات أوقات بداية ونهاية الدوام، وأيام عمل متقاربة من أسبوع لأسبوع، يخلي الأخصائية تقدر ترتب حياتها وعائلتها، وهذا مهم جدًا لموظفات عندهم التزامات بيت وأطفال.','جدول أسبوعين يُنشر في صفحة الفريق قبل بدايته، بفترات ثابتة (صباحي/مسائي)، والتغيير بعد النشر يكون بموافقة الأخصائية.','عدد تعديلات الجدول بعد نشره، ونسبة الغياب المفاجئ، ونسبة إشغال المواعيد لكل أخصائية.','لما يكثر الغياب أو الاعتذار المتأخر، أو تشتكي الأخصائيات من تغيير الدوام.','الدراسة في قطاع التجزئة الأمريكي؛ الأرقام تخصها هي، والمطلوب منكم تقيسون الأثر من أرقامكم. وأغلب مصادر عدم الاستقرار كانت قرارات إدارية، مو تقلب العميلات.',array['williams-sss-2018']::text[],'evidence',array['جدول','مناوبات','استقرار','غياب','إنتاجية']::text[],'team',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-26','people','تبديل المناوبات المنظم وفريق أساسي بساعات مضمونة','من الممارسات اللي جربتها دراسة الجداول المستقرة: تبديل المناوبات بين الموظفين عبر تطبيق، وجدولة أساسية متقاربة من أسبوع لأسبوع، وحد أدنى مضمون من الساعات لفريق أساسي من الموظفين بدوام جزئي.','اسمحوا للأخصائيات يبدلون مناوباتهم بينهم عبر الموقع بشرط تكون البديلة مؤهلة للخدمات المحجوزة، وثبّتوا فريق أساسي للأوقات المزدحمة (مساء الخميس، ليالي رمضان، قبل العيد) بتوزيع عادل ومعلن.','زر «اطلبي تبديل» في صفحة الجدول: الأخصائية تعرض مناوبتها، زميلة مؤهلة تقبل، والشريكة توافق بضغطة، والحجوزات تنتقل في ركاز.','عدد طلبات التبديل اللي اكتملت، وتوزيع مناوبات الذروة على الأخصائيات (هل هو متوازن؟).','لما تكون مناوبات الذروة والمواسم مصدر تذمر أو إحساس بعدم العدل.','التبديل الحر بدون ضوابط ممكن يخلي العميلة تتفاجأ بأخصائية ما تعرفها؛ بلّغوا العميلة إذا تغيرت أخصائيتها.',array['williams-sss-2018']::text[],'evidence',array['تبديل المناوبات','عدالة','ذروة','رمضان','عيد']::text[],'team',25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-27','people','مناخ الخدمة: اللي تعيشه الأخصائية تحسه العميلة','أبحاث Schneider وزملائه تبين إن إدراك موظفي الخط الأمامي لمناخ الخدمة (هل الصالون يكافئ ويدعم ويتوقع خدمة ممتازة؟) مرتبط بجودة الخدمة اللي يحسها العملاء، وإن هذا المناخ يحتاج أساس من الموارد مثل التدريب والأدوات والدعم.','ما ينفع تطلبون من الأخصائية تبتسم وتهتم بالعميلة وهي نفسها ما تحس إن الإدارة تهتم بالخدمة. خلّوا الخدمة الممتازة هي اللي تنمدح وتنكافأ ويُتكلم عنها في الاجتماعات، مو بس الإيراد.','كل اجتماع أسبوعي يبدأ بقصة خدمة مميزة من الأسبوع، وكل قرار (منتج جديد، تعديل جدول) يُسأل فيه: وش أثره على تجربة العميلة؟','متوسط تقييم الصالون ومحتوى التقييمات عن التعامل، مقارنة باستبيان الفريق عن دعم الإدارة للخدمة.','لما ينزل التقييم أو تتكرر ملاحظات عن التعامل رغم إن الشغل الفني ممتاز.','العلاقة تشتغل في الاتجاهين: رضا العملاء وولاؤهم يقوون مناخ الخدمة بعد. فلا تفسرون أي رقم واحد كسبب مباشر.',array['schneider-1998']::text[],'evidence',array['مناخ الخدمة','تجربة العميلة','تقييمات','تعامل','دعم']::text[],'team',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-28','people','اشتغلوا على الصالون، مو بس داخله','Gerber يشرح إن أغلب المشاريع الصغيرة يبدأها شخص فني ممتاز في حرفته، فيغرق في الشغل اليومي ويصير المشروع معتمد عليه شخصيًا. الحل إنه يبني نظام موثق يشتغل بدونه، كأنه يجهز المشروع للتكرار.','لو كل قرار وكل عميلة صعبة وكل طلبية لازم تمر على شهد أو أميرة، الصالون يقف لما تغيب وحدة منهم. وثّقوا الإجراءات (الاستقبال، الشكاوى، الطلبيات، الإغلاق) عشان الفريق يمشيها بنفسه.','دليل تشغيل في صفحة القواعد فيه: كيف تتعامل الاستقبال مع عميلة زعلانة، متى تعطي تعويض وبأي حد، ومين يوافق على طلبية منتجات.','عدد القرارات اليومية اللي تحتاج تدخل الشريكتين (سجلوها أسبوع)، وهل يمشي الصالون بنفس الأرقام لما تكون وحدة منهم مسافرة.','لما تحسون إنكم ما تقدرون تاخذون إجازة، أو قبل التفكير في فرع ثاني أو امتياز تجاري.','التوثيق المبالغ فيه يقتل المرونة؛ وثّقوا اللي يتكرر ويأثر على العميلة أو الفلوس، واتركوا الباقي لحكم الفريق.',array['gerber-emyth']::text[],'practice',array['تفويض','اعتماد على المالك','إجراءات','توثيق','امتياز تجاري']::text[],'rules',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-29','people','لكل وظيفة رئيسية شخص واحد مسؤول','في نظام EOS لـ Wickman، مخطط المسؤوليات يرسم الوظائف الرئيسية في المشروع (عادة المبيعات والتسويق، والتشغيل، والمالية) ويحدد لكل وظيفة شخص واحد مسؤول. وجود أكثر من اسم على نفس الوظيفة يسبب التعطيل والخلاف.','مع شراكة مناصفة بين شهد وأميرة، أهم شي توزيع المسؤولية بوضوح: مثلًا وحدة مسؤولة عن الفريق والتشغيل، والثانية عن التسويق والمالية، وكل وحدة صاحبة القرار النهائي في مجالها، مع قرارات كبرى مشتركة متفق عليها.','مخطط من صفحة واحدة: التشغيل والفريق (اسم واحد)، التسويق والعميلات (اسم واحد)، المالية والمشتريات (اسم واحد)، ومشرفة الاستقبال مسؤولة عن الحجوزات وركاز.','عدد المهام اللي تتأخر لأن «كل وحدة حسبت الثانية بتسويها»، ووقت اتخاذ القرارات المتكررة.','لما يتكرر الخلاف بين الشريكتين على مين يقرر، أو الفريق يسمع توجيهات متضاربة.','هذي أداة ممارسة من نظام استشاري تجاري، مو دراسة. والمخطط ما يغني عن اتفاقية شراكة مكتوبة تحدد الصلاحيات والقرارات المشتركة.',array['wickman-traction']::text[],'practice',array['مسؤوليات','شراكة','هيكل','تفويض','قرارات']::text[],'rules',28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-30','people','ساعات العمل والراحة والإضافي حسب نظام العمل','حسب وزارة الموارد البشرية: لا يجوز تشغيل العامل أكثر من ثماني ساعات يوميًا أو ٤٨ ساعة أسبوعيًا، وتنخفض في رمضان إلى ست ساعات يوميًا أو ٣٦ أسبوعيًا. ولا يشتغل أكثر من خمس ساعات متواصلة بدون راحة للصلاة والأكل لا تقل عن نصف ساعة، ولا يبقى في مكان العمل أكثر من ١٢ ساعة في اليوم. والإضافي يُدفع بأجر الساعة مضاف له ٥٠٪ من الأجر الأساسي. والجمعة يوم الراحة الأسبوعية، ويجوز استبداله لبعض الأعمال بعد إبلاغ مكتب العمل.','الصالونات تشتغل لساعات طويلة ومساء، خصوصًا في رمضان والأعياد والأعراس. صمموا الفترات بحيث ما تتجاوز الحدود، واحسبوا الإضافي نظاميًا، وخلّوا وقت الراحة فعلي مو «خذي لقمة بين عميلتين».','في رمضان يكون الدوام فترتين مسائيتين لكل أخصائية بدل فترة طويلة، وأي ساعات زيادة ليلة العيد تتسجل في الموقع وتنحسب إضافي.','ساعات كل أخصائية الأسبوعية من الجدول، وعدد الفترات اللي تجاوزت خمس ساعات بدون راحة.','عند تصميم الجداول، وقبل رمضان والعيد ومواسم الأعراس.','هذا ملخص من صفحة الوزارة؛ التفاصيل والاستثناءات (مثل حالات زيادة الساعات وتحديد يوم الراحة) ترجع لنص نظام العمل ولائحته التنفيذية وعقد العمل الموثق.',array['hrsd-labor']::text[],'law',array['ساعات العمل','رمضان','راحة','عمل إضافي','نظام العمل']::text[],'rules',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-31','people','الإجازة السنوية ومكافأة نهاية الخدمة','حسب وزارة الموارد البشرية: الإجازة السنوية لا تقل عن ٢١ يومًا، وتصير ٣٠ يومًا بعد خمس سنوات متصلة. ومكافأة نهاية الخدمة تُحسب على آخر أجر: نصف شهر عن كل سنة من الخمس الأولى، وشهر عن كل سنة بعدها، وأجزاء السنة بنسبتها. وفي الاستقالة: ثلث المكافأة بعد سنتين وأقل من خمس، وثلثاها من خمس إلى أقل من عشر، وكاملة بعد عشر سنوات.','سجلوا تاريخ بداية كل أخصائية وأجرها في الموقع عشان تعرفون رصيد إجازاتها والتزام نهاية الخدمة المتراكم. وخططوا الإجازات بحيث ما تتجمع في المواسم، بالاتفاق المسبق.','صفحة الفريق تعرض لكل أخصائية رصيد إجازتها وتقدير مكافأة نهاية الخدمة المتراكمة، والإجازات تنطلب قبلها بوقت كافي وتتوزع على مدار السنة.','الالتزام المالي المتراكم لنهاية الخدمة (يدخل في تخطيط السيولة)، ورصيد الإجازات غير المستخدمة.','عند التعيين، وعند طلب الإجازات، وعند أي استقالة أو إنهاء عقد.','نظام العمل عُدّل وبدأ تطبيق التعديلات في ٢٠٢٥ وشملت بعض الإجازات (مثل إجازة الوضع)؛ ارجعوا لنص النظام المحدّث ولمنصة قوى قبل أي حساب نهائي، وفي الحالات الخاصة استشيروا مختص.',array['hrsd-labor']::text[],'law',array['إجازة سنوية','نهاية الخدمة','استقالة','حقوق','نظام العمل']::text[],'rules',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('ppl-32','people','توطين الصالونات النسائية: الوظائف الإدارية سعودية بالكامل','بالقرار الوزاري رقم 141602 وتاريخ 11/09/1444هـ، تُوطّن الوظائف الإدارية في منافذ التزيين النسائية (نشاط الصالونات النسائية) بالكامل، مثل مديرة الفرع ونائبتها ومشرفة الموارد البشرية والكاشير والاستقبال وخدمة العملاء. وفي الوظائف الفنية (المكياج، العناية بالشعر، العناية بالبشرة، التصوير)، المنشأة اللي عندها عشر عاملات فنيات غير سعوديات أو أكثر لازم توظف سعودية وحدة على الأقل. وتُستثنى وظائف مثل العناية بالأظافر والعناية بالجسم والنظافة والتوصيل. وبدأ التطبيق بعد مهلة في 11/06/1445هـ.','الاستقبال والكاشير وخدمة العملاء والإشراف الإداري في بيوتفريش لازم يكونون سعوديات. ومع ~10 أخصائيات، تأكدوا من عدد الفنيات غير السعوديات بعد استبعاد المهن المستثناة، لأنه يحدد إذا يلزمكم توظيف أخصائية فنية سعودية.','تحطون في صفحة الفريق مؤشر يحسب تلقائيًا: عدد الوظائف الإدارية وكلها سعودية؟ وعدد الفنيات غير السعوديات في المهن المشمولة، وينبهكم لو وصل العدد للحد.','نسبة السعوديات في الوظائف الإدارية (المفروض ١٠٠٪)، وعدد الفنيات غير السعوديات في المهن المشمولة.','عند أي توظيف أو استقالة في الاستقبال أو الإدارة، وعند زيادة عدد الأخصائيات.','قرارات التوطين تتحدث؛ ارجعوا للدليل الإجرائي المنشور في موقع وزارة الموارد البشرية لشروط احتساب الموظفة (نوع العقد، التوثيق، العمل المرن عبر منصة مرن) والمسميات بالضبط قبل أي قرار توظيف. والدليل يذكر إن تصنيف نطاقات ما يؤثر على احتساب نسبة هذا التوطين.',array['hrsd-salon-localization']::text[],'law',array['توطين','سعودة','استقبال','صالونات نسائية','وظائف إدارية']::text[],'rules',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-01','growth','الربح يُقتطع أولًا مو آخر الشهر','يقلب Michalowicz المعادلة التقليدية: بدل ما يكون الربح هو اللي يتبقى بعد المصاريف، يُقتطع الربح من كل دخل أولًا وتشتغل المصاريف بما بقي. والفكرة مبنية على أن المصاريف تتمدد لتأكل أي مبلغ متاح.','مع كل دفعة تحصيل من ركاز ونقاط البيع، تحوّلون نسبة صغيرة تحددونها أنتم لحساب ربح منفصل قبل أي صرف. ابدأوا بنسبة صغيرة تقدرون تلتزمون فيها وارفعوها كل ربع سنة.','بيوتفريش تحدد يومين ثابتين في الشهر للتحويل من حساب الدخل لحساب الربح، وما ينلمس حساب الربح إلا للتوزيع على شهد وأميرة كل ربع.','رصيد حساب الربح نهاية كل ربع، ونسبة الربح الفعلي من إجمالي الإيراد في صفحة المالية مقارنة بالربع السابق.','لما تكون الإيرادات زينة لكن ما يتبقى شي آخر الشهر، أو لما المصاريف تكبر كل ما زاد الدخل.','النسب الجاهزة في الكتاب أمثلة أمريكية؛ النسبة الصحيحة تُبنى من أرقام الصالون نفسه. والمنهج أداة انضباط نقدي وما يغني عن قوائم مالية محاسبية سليمة.',array['michalowicz-pf']::text[],'practice',array['ربح','نقد','انضباط مالي','حسابات','توزيع أرباح']::text[],'finance',0) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-02','growth','حساب مستقل لكل غرض مالي','يقترح المنهج توزيع الدخل على حسابات لكل منها غرض: دخل، ربح، أجر المالك، ضرائب، ومصاريف تشغيل، عشان كل ريال يكون له مكان معروف قبل صرفه.','افصلوا حساب الدخل عن حساب التشغيل، وخصصوا حساب للضريبة والزكاة يتغذى من كل تحصيل، عشان ما تتفاجؤون بالمستحقات. التحويل يكون بمواعيد ثابتة مو حسب المزاج.','حساب «ضريبة وزكاة» في بيوتفريش يستقبل جزء من كل دفعة، فإذا جا موعد إقرار ضريبة القيمة المضافة يكون المبلغ جاهز بدون ما ينسحب من رواتب الأخصائيات.','عدد المرات اللي اضطريتوا فيها تسحبون من حساب لغير غرضه، وهل غطى حساب الضريبة المستحق بالكامل وقت الإقرار.','لما تختلط فلوس الصالون ببعض، أو لما تتأخر مستحقات حكومية بسبب نقص السيولة.','كثرة الحسابات بدون متابعة تتحول لتعقيد؛ الأهم الالتزام بمواعيد التحويل. واستشيروا محاسبًا في تقدير الضريبة والزكاة بدل الاعتماد على نسب تقريبية.',array['michalowicz-pf']::text[],'practice',array['حسابات بنكية','ضريبة','زكاة','سيولة','تنظيم مالي']::text[],'finance',1) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-03','growth','أجر الشريكتين بند ثابت مو بقايا','يعامل المنهج أجر المالك كبند مستقل يُقتطع بانتظام، منفصل عن الربح؛ الأجر مقابل الشغل، والربح مكافأة الملكية.','شهد وأميرة تشتغلان في الصالون، فلازم يكون لكل وحدة أجر عن دورها التشغيلي يتحدد كتابيًا، وبعدها يتوزع الربح بالتساوي حسب الشراكة. هذا يحمي الشراكة لما يختلف حجم شغل كل وحدة.','لو أميرة تدير الاستقبال يوميًا وشهد تتابع الموردين والتسويق، كل وحدة لها أجر حسب دورها، والربح الربعي يتقسم مناصفة بعدها.','هل صُرف أجر الشريكتين في موعده كل شهر، وهل يغطي حساب أجر الملاك ثلاثة أشهر قادمة.','لما تحسون إن وحدة منكم تشتغل أكثر من الثانية بدون مقابل واضح، أو لما تفكرون في توظيف مديرة تشغيل وتحتاجون تعرفون تكلفة الدور الحقيقية.','بدون أجر محسوب للملاك، يطلع الصالون أربح مما هو فعلًا، وهذا يضلل أي حساب للامتياز لأن صاحبة الامتياز بتحتاج تدفع لمديرة.',array['michalowicz-pf']::text[],'practice',array['شراكة','أجر المالك','رواتب','توزيع أرباح']::text[],'finance',2) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-04','growth','اعرفوا كم يوم يصمد الصالون بدون دخل','يقيس معهد JPMorgan Chase «أيام الاحتياطي النقدي»: متوسط الرصيد اليومي مقسومًا على متوسط المصروف اليومي. وجدت الدراسة أن المنشأة الصغيرة الوسيطة في عيّنتهم الأمريكية تملك ٢٧ يومًا، وقطاع الخدمات الشخصية ٢١ يومًا، أي أن نصف المنشآت تعيش تقريبًا شهر بشهر.','احسبوا الرقم لصالونكم كل شهر من كشف الحساب: متوسط الرصيد ÷ متوسط المصروف اليومي (رواتب، إيجار، منتجات). حددوا حدًا أدنى لا تنزلون تحته قبل أي توسع.','لو تعطل نظام الحجز أو صار إغلاق مؤقت للصيانة، بيوتفريش تعرف مسبقًا إن عندها احتياطي يغطي الرواتب والإيجار لفترة معروفة.','أيام الاحتياطي النقدي شهريًا في صفحة المالية، واتجاهها خلال ستة أشهر.','قبل أي قرار فرع ثاني أو تجهيزات كبيرة، ولما يقل الرصيد بعد موسم ضعيف.','أرقام الدراسة أمريكية من 2015 وتوصف الواقع ولا تحدد الرقم المثالي؛ هدفكم يتحدد حسب تقلّب دخلكم والتزاماتكم.',array['jpmc-cash']::text[],'evidence',array['سيولة','احتياطي نقدي','مخاطر','تدفق نقدي']::text[],'finance',3) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-05','growth','خططوا السيولة على مواسم الأحساء','وجدت دراسة JPMorgan Chase أن الدخل والمصروف اليومي في المنشآت الصغيرة يمشون مع بعض بشكل متقارب جدًا، وهذا يعني أن أي هبوط في الدخل يضغط مباشرة على القدرة على الدفع.','الطلب في صالون نسائي يرتفع قبل الأعياد ومواسم الأعراس والتخرج ويهدأ في فترات السفر. ارسموا تقويم سنوي للدخل المتوقع من بيانات ركاز للسنوات الماضية، وجمّعوا احتياطي في الذروة لتغطية الهدوء.','بيوتفريش تحجز جزء من دخل أسابيع ما قبل العيد لتغطية رواتب أشهر الصيف، وتؤجل شراء الأجهزة لما بعد الموسم.','مقارنة الدخل الشهري الفعلي بالتقويم المتوقع، وأقل رصيد وصل له الحساب خلال الفترات الهادئة.','عند إعداد ميزانية السنة، وقبل الالتزام بأي مصروف ثابت جديد.',null,array['jpmc-cash','michalowicz-pf']::text[],'evidence',array['مواسم','عيد','أعراس','صيف','تدفق نقدي','ميزانية']::text[],'finance',4) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-06','growth','هامش المساهمة لكل خدمة','يفرّق تحليل Marn وRosiello بين التكاليف المتغيرة (اللي تتحرك مع كل عملية بيع) والثابتة، ويبيّن أن ربحية كل عملية تعتمد على الفرق بين السعر الصافي والتكلفة المتغيرة. هذا الفرق هو هامش المساهمة.','لكل خدمة احسبوا: السعر الصافي بعد الخصومات ناقص المنتجات المستهلكة وعمولة الأخصائية وأي رسوم دفع. الخدمات اللي تستهلك منتجات غالية مثل البروتين والصبغة تحتاج حساب دقيق من سجل المخزون.','جلسة بروتين سعرها مرتفع لكن تستهلك منتج غالي ووقت طويل، فقد يطلع هامشها أقل من قص وتسريحة أبسط. الرقم الحقيقي يطلع من ربط سجل المخزون بالفاتورة.','هامش المساهمة بالريال ونسبته لكل خدمة شهريًا، من ربط فواتير ركاز باستهلاك المخزون.','قبل تعديل الأسعار، أو قبل إطلاق عرض، أو لما تحسون إن خدمة مشهورة ما تجيب ربح.','توزيع الإيجار والرواتب الثابتة على الخدمات بالتساوي يضلل؛ خلوا التكاليف الثابتة لحساب نقطة التعادل.',array['marn-price']::text[],'consensus',array['هامش','تكلفة متغيرة','تسعير','مخزون','ربحية الخدمة']::text[],'finance',5) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-07','growth','نقطة التعادل الشهرية بالمواعيد','التكاليف الثابتة تُغطى من مجموع هوامش المساهمة؛ نقطة التعادل هي حجم المبيعات اللي يغطي التكاليف الثابتة بالضبط، وكل ما بعدها ربح.','اجمعوا التكاليف الثابتة الشهرية (إيجار، رواتب أساسية، أنظمة، تأمين) واقسموها على متوسط هامش المساهمة للموعد الواحد. يطلع لكم عدد المواعيد اللازم شهريًا للتعادل.','إذا طلع إن بيوتفريش تتعادل عند عدد معين من المواعيد شهريًا، يصير كل موعد بعده ربح، ويتضح كم موعد يحتاج الفرع الثاني ليوقف على رجوله.','عدد المواعيد المكتملة مقابل عدد التعادل، واليوم من الشهر اللي يوصل فيه الصالون للتعادل.','شهريًا، وعند التفكير بفرع جديد أو توظيف أخصائية إضافية براتب ثابت.','متوسط الهامش يتغير مع تغيّر خليط الخدمات؛ أعيدوا الحساب لما يتغير الطلب بين الشعر والأظافر والليزر.',array['marn-price','michalowicz-pf']::text[],'consensus',array['نقطة التعادل','تكاليف ثابتة','مواعيد','تخطيط']::text[],'finance',6) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-08','growth','الربح لكل ساعة أخصائية','في الخدمات، الطاقة المحدودة هي الوقت. فمقارنة الخدمات بالهامش لكل ساعة أدق من مقارنتها بالسعر أو بالهامش لكل عملية.','اقسموا هامش المساهمة لكل خدمة على مدتها الفعلية في ركاز (مع وقت التجهيز والتنظيف). في أوقات الذروة أعطوا الأولوية للخدمات الأعلى ربحًا للساعة، ووجهوا الخدمات الطويلة الأقل ربحًا لأوقات الهدوء.','إذا طلع الحمام المغربي أعلى بالساعة من خدمة طويلة ثانية، يصير له أولوية في مواعيد الخميس المسائية، والخدمة الثانية تنعرض بأيام الأسبوع الهادئة.','الهامش لكل ساعة حجز لكل خدمة، ونسبة إشغال وقت الأخصائيات في الذروة وخارجها.','لما تمتلئ مواعيد الذروة وتبغون ترفعون الربح بدون توسعة، أو عند تصميم الباقات.','لا تلغون خدمة منخفضة الربح قبل ما تتأكدون إنها ما تجيب عميلات يطلبن خدمات ثانية؛ راجعوا سلة العميلة كاملة.',array['marn-price']::text[],'consensus',array['طاقة','وقت الأخصائية','إشغال','ذروة','ربحية']::text[],'finance',7) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-09','growth','السعر أقوى رافعة للربح','حسب تحليل Marn وRosiello لمتوسط اقتصاديات ٢٤٦٣ شركة، تحسين السعر ١٪ بدون خسارة حجم يرفع الربح التشغيلي ١١٫١٪، مقابل ٣٫٣٪ فقط لزيادة الحجم ١٪. والعكس صحيح: خصم ١٪ يمسح نفس النسبة من الربح.','قبل أي خصم عام، احسبوا كم عميلة إضافية تحتاجون عشان تعوضون الربح المفقود. تعديلات سعرية صغيرة ومدروسة على الخدمات المطلوبة غالبًا أربح من حملة خصومات.','بدل خصم عام على كل الخدمات في رمضان، بيوتفريش تثبّت الأسعار وتضيف قيمة (مثل ماسك مجاني مع الصبغة) تكلفتها المتغيرة أقل من قيمة الخصم.','متوسط الفاتورة والهامش قبل وبعد أي تعديل سعر، مع مراقبة عدد الحجوزات ونسبة رجوع العميلات.','لما تفكرون بخصم، أو لما ترتفع تكاليف المنتجات وتترددون في رفع السعر.','الأرقام متوسط شركات أمريكية متنوعة وليست خاصة بالصالونات؛ أثرها عليكم يعتمد على هامشكم الفعلي ومدى حساسية عميلاتكم للسعر.',array['marn-price']::text[],'evidence',array['تسعير','خصومات','ربح','رفع الأسعار']::text[],'sales',8) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-10','growth','انتبهوا للسعر اللي يدخل الجيب فعلًا','يقدّم المقال مفهوم «شلال السعر»: السعر المعلن يتآكل بخصومات وحوافز خارج الفاتورة حتى يوصل لـ«سعر الجيب» اللي يدخل الشركة فعلًا، وهو المقياس الصحيح لجاذبية كل عملية.','اجمعوا كل التسربات: كوبونات، باقات مخفضة، خدمات مجانية للمؤثرات، عمولات منصات، رسوم أجهزة الدفع، وأخطاء الاستقبال في الخصم. قارنوا السعر المعلن بالصافي لكل خدمة.','خدمة معلنة بسعر معين، لكن بعد باقة الخمس جلسات ورسوم الدفع وخصم الصديقة يطلع صافيها أقل بكثير. بيوتفريش تكتشف هذا من تقرير الخصومات في ركاز.','الفرق بين السعر المعلن ومتوسط السعر الصافي لكل خدمة، ومجموع الخصومات الشهرية كنسبة من الإيراد.','لما يكون الإيراد زين لكن الربح ما يتحرك، أو بعد موسم عروض كثيرة.',null,array['marn-price']::text[],'evidence',array['خصومات','باقات','كوبونات','صافي السعر','تسرب']::text[],'sales',9) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-11','growth','قوة التسعير تجي من التميز مو من الخصم','يرى Porter أن الميزة المستدامة تأتي من أداء أنشطة مختلفة أو بطريقة مختلفة تخلق قيمة فريدة، وهذا ما يسمح بسعر أعلى. والمنافسة على نفس الأشياء تقود لتقارب الخدمات وحرب أسعار.','حددوا ما يميزكم ويصعب تقليده: تقييم ٤٫٨ من آلاف العميلات، أخصائيات مستقرات، خدمة منزلية منظمة. ابنوا السعر على هذا التميز، وخلوا رسائلكم تبرزه بدل ما تنافسون على السعر.','بيوتفريش ترفع سعر خدمات الأخصائيات الأقدم والأعلى تقييمًا، وتشرح الفرق للعميلة عند الحجز بدل ما تساوي السعر بين الجميع.','نسبة العميلات اللي يخترن الخيار الأعلى سعرًا، واستقرار الحجوزات بعد رفع السعر، والتقييمات.','لما يفتح منافس قريب بأسعار أقل، أو لما تحسون إنكم مضطرين للخصم باستمرار.',null,array['porter-strategy','marn-price']::text[],'consensus',array['تميز','قوة تسعير','منافسة','هامش','علامة']::text[],'sales',10) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-12','growth','التميز التشغيلي ضروري لكنه مو استراتيجية','يفرّق Porter بين الفعالية التشغيلية (أداء نفس الأنشطة بشكل أفضل من المنافسين) والاستراتيجية (أداء أنشطة مختلفة). الأولى ضرورية لكنها سهلة التقليد، فما تكفي وحدها لميزة دائمة.','تحسين سرعة الاستقبال والحجز الإلكتروني والنظافة شي لازم، لكن أي صالون في الأحساء يقدر ينسخه. اسألوا: وش نسوي بطريقة مختلفة عن غيرنا؟','تطبيق نظام تذكير بالمواعيد يرفع الكفاءة، لكن المنافسين يقدرون يطبقونه. الاستراتيجي هو مثلًا تخصص واضح في فئة معينة من الخدمات أو العميلات يبنى حوله كل شي.','عدد الأشياء في قائمة «ما يميزنا» اللي ما يقدمها أي منافس قريب، ونسبة العميلات الجديدات اللي يذكرنها في «كيف عرفتنا؟».','لما تكون كل خطط التطوير تحسينات تشغيلية بس، ولما يقلدكم المنافسون بسرعة.',null,array['porter-strategy']::text[],'consensus',array['استراتيجية','تموضع','كفاءة','منافسة']::text[],null,11) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-13','growth','الاستراتيجية تعني تختارون وش ما تسوونه','يؤكد Porter أن جوهر الاستراتيجية هو المقايضات: اختيار ما لا تفعله الشركة، لأن محاولة خدمة الكل تضعف التموضع. والتوافق بين الأنشطة يجعل النظام كله صعب التقليد.','قرروا صراحة: أي خدمات أساسية لهويتكم، وأي خدمات تقدمونها بس لأن العميلات طلبنها وتشتت الأخصائيات والمخزون. كل نشاط (توظيف، تدريب، ديكور، رسائل) لازم يدعم نفس الاختيار.','لو قررت بيوتفريش إن هويتها العناية بالشعر والبشرة بمستوى عالٍ، قد تتوقف عن خدمة قليلة الطلب تحتاج جهاز خاص ومخزون، وتوجه التدريب والتسويق للشعر والبشرة.','نسبة الإيراد من الخدمات الأساسية المختارة، وعدد أصناف المخزون الراكدة بعد التقليص.','لما تكبر قائمة الخدمات وتتعب الأخصائيات من التنقل، أو قبل الامتياز لأن صاحبة الامتياز تحتاج نموذج واضح ومحدد.','التقليص بدون بيانات خطر؛ راجعوا كم عميلة تجي لخدمة معينة ثم تطلب غيرها قبل الحذف.',array['porter-strategy']::text[],'consensus',array['مقايضات','تركيز','قائمة الخدمات','هوية','توافق']::text[],null,12) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-14','growth','نواة الاستراتيجية: تشخيص وسياسة وأفعال','يقول Rumelt إن الاستراتيجية الجيدة لها نواة من ثلاثة أجزاء: تشخيص يحدد التحدي الحقيقي، وسياسة موجِّهة تحدد طريقة التعامل معه، وأفعال مترابطة تنفذها.','قبل أي خطة نمو، اكتبوا جملة تشخيص واحدة من بياناتكم (مثلًا: العميلات الجدد كثير لكن قليل منهن يرجعن)، ثم سياسة واحدة، ثم ثلاث إلى خمس خطوات مترابطة.','تشخيص: رجوع العميلات بعد أول زيارة ضعيف. سياسة: نخلي الزيارة الثانية أسهل قرار. أفعال: حجز الموعد القادم قبل الخروج، رسالة متابعة بعد أسبوع، أخصائية ثابتة لكل عميلة جديدة.','المؤشر المرتبط بالتشخيص نفسه (هنا: نسبة رجوع العميلات خلال ٦٠ يوم) قبل وبعد التنفيذ.','عند وضع خطة السنة، أو لما تتراكم مبادرات كثيرة بدون اتجاه واحد.',null,array['rumelt-gsbs']::text[],'consensus',array['تشخيص','خطة','أولويات','تنفيذ']::text[],null,13) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-15','growth','الأهداف والشعارات مو استراتيجية','يحذّر Rumelt من الاستراتيجية السيئة: كلام منمّق، وتجاهل التحدي الحقيقي، وخلط الأهداف المرغوبة بالاستراتيجية، وقوائم أهداف كثيرة غير مترابطة.','جملة مثل «نبغى نكون الصالون الأول في الأحساء» أو «نضاعف الإيراد» أمنيات. اسألوا: وش العقبة اللي تمنعنا اليوم؟ وإذا ما قدرتوا تسمونها، ارجعوا للبيانات قبل ما تحطون خطة.','بدل هدف «نفتح فرع في الدمام السنة الجاية»، يصير السؤال: هل عندنا طلب مثبت من الدمام، ومديرة قادرة تشغّل فرع بدوننا؟ هذا هو التحدي الحقيقي.','هل كل هدف في الخطة مربوط بعقبة مسمّاة وفعل محدد ومؤشر في صفحة المالية أو الحجوزات.','عند مراجعة الخطة السنوية، أو لما يكون فيه أكثر من خمس أولويات في نفس الوقت.',null,array['rumelt-gsbs']::text[],'consensus',array['أهداف','تخطيط','أولويات','وضوح']::text[],null,14) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-16','growth','احذفوا وقللوا وارفعوا وابتكروا','يقترح Kim وMauborgne شبكة من أربعة أسئلة لإعادة تصميم العرض: وش العوامل اللي تنافس عليها السوق ونحذفها، ونقللها، ونرفعها فوق المعتاد، ونبتكر شي ما تقدمه السوق أصلًا. ويرسمون العوامل في «لوحة استراتيجية» مقارنة بالمنافسين.','ارسموا لوحة لعوامل المنافسة في الأحساء (السعر، تنوع الخدمات، الفخامة، وقت الانتظار، الخصوصية، الخدمة المنزلية) وحددوا موقعكم وموقع المنافسين، ثم طبقوا الأسئلة الأربعة.','بيوتفريش قد تقلل الديكور المكلف، وترفع الخصوصية والالتزام بالمواعيد، وتبتكر متابعة شخصية بعد الخدمات الكيميائية مثل الصبغة والبروتين.','نتائج مقارنة اللوحة كل سنة، ونسبة العميلات الجدد اللي يذكرن العامل المبتكر في «كيف عرفتنا؟» أو التقييمات.','لما يتشابه الصالون مع منافسيه، أو قبل تصميم نموذج الامتياز.','أمثلة الكتاب حالات نجاح مدروسة بأثر رجعي، فما تثبت إن الأداة نفسها هي سبب النجاح. استخدموها لتنظيم التفكير مو كوصفة مضمونة.',array['kim-boss','rosenzweig-halo']::text[],'practice',array['محيط أزرق','تميز','ابتكار','لوحة استراتيجية','منافسة']::text[],null,15) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-17','growth','فكروا في اللي ما يجون لكم أصلًا','يدعو المحيط الأزرق للنظر إلى «غير العملاء»: من هم على حافة السوق، ومن يرفضونه، ومن لم يفكروا فيه أصلًا، لأن فهم أسباب غيابهم يفتح طلب جديد بدل التنافس على نفس العميلات.','اسألوا: مين في الأحساء ما تزور الصالونات؟ أمهات ما عندهن وقت، موظفات تنتهي دواماتهن متأخر، كبيرات سن يفضلن الخصوصية. الخدمات المنزلية وساعات العمل مداخل لهذي الفئات.','تصميم باقة منزلية للعرائس وأهلهن، أو ساعات مسائية مخصصة، يجيب عميلات ما كن يحجزن في الصالون أبدًا.','عدد العميلات الجدد من الخدمة الموجهة لغير العملاء، ونسبة اللي منهن صرن يجين للصالون بعدها.','لما يكون نمو العميلات الجدد بطيء والمنافسة على نفس الشريحة حادة.',null,array['kim-boss']::text[],'practice',array['عميلات جدد','خدمات منزلية','شرائح','طلب جديد']::text[],'campaigns',16) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-18','growth','مفهوم القنفذ: تقاطع ثلاث دوائر','يطرح Collins أن الشركات اللي درسها ركزت على تقاطع ثلاثة أسئلة: وش نتحمس له، ووش نقدر نكون الأفضل فيه، ووش يحرك محركنا الاقتصادي (مؤشر ربح واحد أساسي).','حددوا الخدمات اللي فيها تميز حقيقي (من التقييمات ورجوع العميلات)، واللي الفريق متحمس لها، واللي تحقق أعلى ربح للساعة. التقاطع هو مركز نموكم وما ينقل للامتياز.','إذا كان الشعر يجمع أعلى تقييم وحماس الفريق وربح الساعة، فهو قلب علامة بيوتفريش، والمؤشر الاقتصادي قد يكون «الربح لكل ساعة أخصائية».','مؤشر اقتصادي واحد تتفقون عليه وتتابعونه شهريًا في صفحة المالية.','عند تحديد هوية العلامة قبل الامتياز، أو لما تتشتت الخدمات.','الكتاب تعرّض لنقد منهجي: Rosenzweig يرى أنه اعتمد على مصادر متأثرة بهالة النجاح وخلط الارتباط بالسببية، وبعض الشركات «العظيمة» فيه مثل Circuit City وFannie Mae تعثرت لاحقًا. استخدموه كأداة تفكير مو قانون.',array['collins-g2g','rosenzweig-halo']::text[],'practice',array['تركيز','هوية','ربحية','تميز']::text[],null,17) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-19','growth','دولاب الزخم بدل القفزة الواحدة','يصف Collins النمو كدولاب ثقيل يدور بدفعات متراكمة في نفس الاتجاه، وكل دورة تسهّل اللي بعدها، بدل الاعتماد على مبادرة واحدة كبيرة.','ارسموا حلقتكم: خدمة ممتازة ← تقييمات عالية ← عميلات جدد ← دخل يسمح بتدريب وأخصائيات أفضل ← خدمة أفضل. وقيسوا كل حلقة بدل ما تقفزون بين حملات منفصلة.','كل تقييم إيجابي في بيوتفريش يُستثمر في الرد عليه ونشره، وكل زيادة دخل يخصص جزء منها لتدريب الأخصائيات، فتدور الحلقة.','مؤشر لكل حلقة: التقييم، العميلات الجدد من «كيف عرفتنا؟»، الدخل، ساعات التدريب، ونسبة الرجوع.','لما تكون الجهود متفرقة وكل شهر فيه مبادرة جديدة بدون تراكم.','نفس نقد Good to Great ينطبق هنا؛ الحلقة تصف منطق النمو لكنها ما تضمنه.',array['collins-g2g','rosenzweig-halo']::text[],'practice',array['زخم','نمو','تقييمات','تدريب','استمرارية']::text[],'reviews',18) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-20','growth','لا تنسخون قصص نجاح الآخرين','يبيّن Rosenzweig أن كثير من دراسات النجاح تنظر للشركات الناجحة وتنسب صفاتها للنجاح، بينما النجاح نفسه يجعل الناس يرون صفاتها إيجابية (تأثير الهالة)، فتختلط النتيجة بالسبب.','لما تشوفون صالون ناجح في الرياض أو سلسلة مشهورة، لا تفترضون إن ديكورها أو عروضها هي سبب نجاحها. جربوا الفكرة عندكم بشكل صغير وقيسوا.','سلسلة معروفة تقدم قهوة مختصة للعميلات؛ بدل تقليدها فورًا، بيوتفريش تجربها شهر وتقيس أثرها على التقييمات ومتوسط الفاتورة.','نتيجة التجربة على مؤشراتكم أنتم، مو على شهرة الفكرة.','لما يجي اقتراح «فلان سوّى كذا ونجح».',null,array['rosenzweig-halo']::text[],'consensus',array['تقليد','تفكير نقدي','تجربة','قرارات']::text[],null,19) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-21','growth','بطاقة أداء بأربعة منظورات','يقترح Kaplan وNorton ألا تكتفي الإدارة بالمؤشرات المالية، وأن تتابع أربعة منظورات مترابطة: المالي، والعميل، والعمليات الداخلية، والتعلم والنمو.','اختاروا مؤشرين أو ثلاثة لكل منظور: مالي (الهامش، أيام الاحتياطي)، عميلة (التقييم، الرجوع)، عمليات (الالتزام بالمواعيد، الإلغاء، الهدر في المخزون)، تعلم (ساعات تدريب، استقرار الأخصائيات).','صفحة واحدة شهرية لبيوتفريش تعرض المنظورات الأربعة، فإذا نزل الرجوع تقدرون تشوفون هل السبب في التدريب أو في الالتزام بالمواعيد.','اكتمال البطاقة شهريًا واتجاه كل مؤشر.','لما تكون المتابعة مالية بس، أو قبل الامتياز لأن كل فرع يحتاج بطاقة موحدة.','كثرة المؤشرات تضيع التركيز؛ قلة مختارة أفضل من لوحة مزدحمة.',array['kaplan-bsc']::text[],'consensus',array['مؤشرات أداء','لوحة متابعة','قياس','إدارة']::text[],'finance',20) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-22','growth','أهداف قليلة ونتائج تنقاس','يشرح Doerr منهج OKRs: هدف واضح ومُلهم، يتبعه عدد قليل من النتائج الرئيسية القابلة للقياس اللي تثبت تحققه، مع مراجعة دورية وشفافية للفريق.','لكل ربع سنة، حطوا هدف أو اثنين بالكثير للصالون، ولكل هدف ثلاث نتائج رقمية من بياناتكم. شاركوها مع الأخصائيات والاستقبال وراجعوها كل أسبوعين.','الهدف: كل عميلة جديدة ترجع. النتائج: رفع الرجوع خلال ٦٠ يوم من مستواه الحالي، حجز موعد ثاني قبل الخروج لأغلب العميلات الجدد، تقييم الزيارة الأولى لا ينزل.','نسبة تحقق كل نتيجة رئيسية في نهاية الربع.','بداية كل ربع، أو لما الفريق ما يعرف وش الأولوية هالشهر.','ربط النتائج بالمكافآت مباشرة قد يدفع للتلاعب بالرقم بدل تحسين الواقع (مثلًا: حجز مواعيد ثانية تُلغى بعدين). قيسوا الجودة مع الكمية.',array['doerr-mwm']::text[],'practice',array['أهداف','OKR','فريق','مراجعة ربعية']::text[],'team',21) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-23','growth','جرّبوا بأصغر نسخة قبل الفرع الثاني','يدعو Ries لاختبار الفرضيات بأصغر نسخة قابلة للتجربة (MVP) ضمن حلقة ابنِ-قِس-تعلّم، بدل الاستثمار الكامل قبل ما يثبت الطلب.','قبل فرع كامل في مدينة ثانية، اختبروا الطلب بخطوات صغيرة: خدمات منزلية في الحي المستهدف، أيام محددة في مكان مؤقت، أو حملة حجز مسبق. كل تجربة لها فرضية مكتوبة ورقم نجاح محدد مسبقًا.','فرضية: عميلات في الخبر والدمام مستعدات يحجزن خدمات بيوتفريش المنزلية بسعرها الحالي. التجربة: فتح الحجز المنزلي هناك أيام محددة وقياس الطلب.','عدد الحجوزات من المدينة المستهدفة، ونسبة اللي حجزن مرة ثانية، ومقارنتها برقم النجاح المحدد قبل التجربة.','قبل أي التزام بإيجار أو تجهيز فرع جديد.','التجربة الصغيرة ما تكشف كل تكاليف الفرع الكامل (إيجار، تراخيص، إدارة)؛ هي تثبت الطلب، مو ربحية الفرع.',array['ries-lean']::text[],'practice',array['تجربة','MVP','فرع جديد','توسع','اختبار السوق']::text[],null,22) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-24','growth','مقاييس حقيقية مو مقاييس غرور','يفرّق Ries بين مقاييس تعطي شعور بالنجاح بدون ما تساعد على القرار (مقاييس الغرور) والمقاييس اللي تثبت سببًا ونتيجة، ويربطها بقرار واضح: نستمر أو نغيّر الاتجاه.','المتابعات في الانستقرام وعدد المشاهدات مقاييس غرور إذا ما ارتبطت بحجوزات. ركزوا على: العميلات الجدد من القناة، الرجوع، والهامش. بعد كل تجربة قرروا صراحة: نكمل، نعدل، أو نوقف.','حملة مؤثرة جابت مشاهدات عالية لكن حجوزاتها قليلة، فقرار بيوتفريش يكون التوقف عن هذا النوع ونقل الميزانية لقناة تجيب حجوزات.','عدد الحجوزات والعميلات الراجعات لكل قناة من «كيف عرفتنا؟»، مو المشاهدات.','بعد كل حملة أو تجربة، وعند تقييم أي فكرة توسع.',null,array['ries-lean']::text[],'practice',array['قياس','حملات','قرارات','تحول','قنوات']::text[],'campaigns',23) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-25','growth','متى تعمّقون الفرع ومتى تفتحون ثاني','تجتمع عدة مدارس على أن التوسع قبل تثبيت النموذج وضبط ربحيته يضاعف المشاكل: Porter يحذر من تمدد يضعف التموضع، وCollins يربط النمو بالتركيز على ما تتميز فيه المنشأة، وRies يطلب إثبات الطلب قبل الاستثمار.','عمّقوا الفرع الحالي إذا كانت أوقات الذروة غير ممتلئة، أو الرجوع ضعيف، أو الربح يعتمد على وجود الشريكتين يوميًا. فكروا بفرع ثاني لما تمتلئ الذروة باستمرار مع قائمة انتظار، ويشتغل الصالون بأسبوع كامل بدون الشريكتين، وعندكم احتياطي نقدي كافٍ.','إذا كانت مواعيد نهاية الأسبوع في بيوتفريش تنحجز قبل أيام ويُعتذر لعميلات، والإشغال في الأيام العادية عالٍ أيضًا، فهذي إشارة طلب فائض تبرر دراسة فرع.','نسبة إشغال وقت الأخصائيات، عدد طلبات الحجز المرفوضة، نسبة العميلات من خارج الحي، وأيام الاحتياطي النقدي.','عند كل نقاش عن التوسع، وبشكل دوري كل ستة أشهر.','قد يكون رفع السعر أو تمديد الساعات أو إضافة كرسي حل أربح من فرع جديد؛ قارنوا الخيارات بالأرقام.',array['porter-strategy','collins-g2g','ries-lean']::text[],'consensus',array['توسع','فرع ثاني','إشغال','قائمة انتظار','قرار']::text[],'finance',24) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-26','growth','التوسع للدمام أو الرياض يبدأ بالقريب والمشابه','وجدت دراسة Kalnins وLafontaine أن السلاسل تميل لإعطاء الوحدات الجديدة لمن عنده وحدات قريبة جغرافيًا، وفي أسواق مجاورة ومشابهة سكانيًا لأسواقه الحالية، وتطبق نفس المعيار على وحداتها المملوكة لها. القرب والتشابه يسهلان الإشراف ونقل الخبرة.','الدمام والخبر أقرب للأحساء وأسهل في الإشراف ونقل الأخصائيات من الرياض. ابدأوا بالسوق الأقرب والأشبه بعميلاتكم الحاليات، وتحققوا من الطلب قبلها.','بيانات ركاز قد تكشف عميلات يجين من الدمام والخبر للأحساء؛ هذي نقطة بداية لاختبار الطلب هناك قبل الرياض.','عدد العميلات الحاليات من كل مدينة، ونتائج تجارب الطلب، ووقت ومسافة الإشراف المطلوب.','عند اختيار مدينة الفرع الثاني أو أول امتياز.','الدراسة على مطاعم وجبات سريعة في تكساس؛ المنطق قابل للنقل لكن الأرقام والسلوك يختلفان. والرياض سوق أكبر وأكثر منافسة، فالحجم وحده ما يبرر البدء فيها.',array['kalnins-lafontaine','ries-lean']::text[],'evidence',array['الدمام','الخبر','الرياض','توسع جغرافي','اختبار السوق']::text[],null,25) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-27','growth','ابنوا الصالون كأنه نموذج امتياز','يدعو Gerber صاحب المنشأة للعمل «على» المنشأة لا «فيها» فقط، وبنائها كنموذج أولي للامتياز: نظام موثق وقابل للتكرار يعطي نفس النتيجة بأشخاص عاديين، بدون الاعتماد على موهبة المالك.','وثقوا كل شي: استقبال العميلة، خطوات كل خدمة، معايير النظافة، الرد على الشكاوى، طلب المنتجات. الاختبار الحقيقي: هل يشتغل الصالون بنفس الجودة لو غابت شهد وأميرة أسبوعين؟','بطاقة إجراء لخدمة الصبغة في بيوتفريش: الاستشارة، اختبار الحساسية، المنتجات والكميات، الوقت، تعليمات العناية بعدها. أي أخصائية جديدة تطبقها بنفس المستوى.','عدد الإجراءات الموثقة من مجموع الخدمات، وثبات التقييمات بين الأخصائيات، والأداء في فترات غياب الشريكتين.','من الآن، لأنه شرط عملي للفرع الثاني والامتياز.','التوثيق الزائد يقتل المرونة في خدمات شخصية؛ ثبتوا المعايير والنتائج، واتركوا مساحة للأخصائية في التواصل مع العميلة.',array['gerber-emyth']::text[],'practice',array['أنظمة','إجراءات','توثيق','امتياز','استقلالية التشغيل']::text[],'kit',26) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-28','growth','دليل التشغيل والتدريب والتدقيق تحمي العلامة','تشرح نظرية الوكالة في أبحاث الامتياز أن صاحب الامتياز قد يقصّر في الجودة لأن ضرر العلامة يتوزع على الكل، فيحتاج المانح أدوات متابعة. ونظام الامتياز السعودي يلزم المانح بتدريب موظفي صاحب الامتياز وتقديم الخبرة الفنية والتسويقية.','جهزوا ثلاث أدوات قبل أي امتياز: دليل تشغيل مكتوب، برنامج تدريب للأخصائيات والاستقبال بشهادة داخلية، وزيارات تدقيق دورية بنموذج تقييم موحد ومعه تقييمات العميلات.','نموذج تدقيق بيوتفريش يشمل: النظافة، الالتزام بخطوات الخدمة، تواريخ صلاحية المنتجات، وقت الانتظار، وطريقة الرد على التقييمات. يتعبأ كل زيارة ويُقارن بين الفروع.','درجة التدقيق لكل فرع، والفرق في التقييم بين الفرع الأصلي والفروع الأخرى.','قبل منح أول امتياز، وطوال مدة العقد.',null,array['combs-franchising','gerber-emyth','ksa-franchise-law']::text[],'consensus',array['دليل تشغيل','تدريب','تدقيق','معايير','جودة العلامة']::text[],'team',27) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-29','growth','ليش الامتياز: موارد ناقصة أم رقابة صعبة','تربط مراجعة Combs وMichael وCastrogiovanni أبحاث الامتياز بنظريتين: ندرة الموارد (الامتياز يمول التوسع برأس مال وإدارة أصحاب الامتياز)، والوكالة (صاحبة الامتياز المالكة تتحمس أكثر من مديرة براتب، خصوصًا في الفروع البعيدة).','اسألوا أنفسكم بصراحة: هل نحتاج الامتياز لأن ما عندنا رأس مال للتوسع، أو لأن إدارة فروع بعيدة بمديرات صعبة؟ الجواب يحدد شكل التوسع: فروع مملوكة قريبة، وامتياز للمدن البعيدة مثلًا.','بيوتفريش قد تملك فرعها الثاني في الدمام وتديره بنفسها، وتمنح امتيازًا في الرياض لمستثمرة محلية تعرف السوق وتديره بنفسها.','تكلفة فتح الفرع المملوك مقابل العائد المتوقع من الامتياز، ومسافة وتكلفة الإشراف.','عند المقارنة بين فرع مملوك وامتياز.','المراجعة نفسها تدعو لتنويع النظريات؛ ما فيه نظرية وحدة تفسر قرار الامتياز بالكامل.',array['combs-franchising']::text[],'evidence',array['امتياز','فرع مملوك','رأس مال','رقابة','نظرية الوكالة']::text[],null,28) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-30','growth','شرط الخبرة: سنة تشغيل بفرعين قبل الامتياز','تنص المادة الخامسة من نظام الامتياز التجاري على عدم عرض أو منح الامتياز إلا بعد تشغيل النشاط مدة لا تقل عن سنة في نقطتي بيع مختلفتين أو بواسطة شخصين على الأقل (يجوز أن يكون أحدهما المانح). وفي يناير 2026 صدر قرار من مجلس الوزراء باستثناء فئات في قطاعات واعدة بشروط، منها تقديم نموذج عمل ودراسة جدوى وعدم أخذ رسوم قبل بدء التشغيل.','بيوتفريش بفرع واحد ما تقدر تعرض امتيازها اليوم. الطريق النظامي: فتح فرع ثاني (مملوك) وتشغيله سنة على الأقل، وخلال هالسنة تبنون دليل التشغيل وتقيسون قابلية التكرار.','خطة واقعية: فرع ثاني في الدمام، سنة تشغيل كاملة موثقة الأرقام، ثم إعداد وثيقة الإفصاح وعرض الامتياز.','تاريخ بدء تشغيل الفرع الثاني، واكتمال سنة التشغيل، ومقارنة أداء الفرعين.','قبل أي حديث مع مستثمرة مهتمة بالامتياز، وحتى قبل الإعلان عن «امتياز قريبًا».','الأخبار المنشورة عن الاستثناء ذكرت قطاعات مثل النقل والترفيه والسياحة والرياضة والصحة والتعدين والطاقة المتجددة، وما ذكرت صالونات التجميل صراحة. لا تعتمدون على الاستثناء بدون تأكيد مكتوب من وزارة التجارة.',array['ksa-franchise-law','ksa-franchise-exemption']::text[],'law',array['نظام الامتياز','شرط الخبرة','المادة الخامسة','فرع ثاني','وزارة التجارة']::text[],'rules',29) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-31','growth','وثيقة الإفصاح قبل التوقيع بـ١٤ يوم','يلزم النظام المانح بتسليم صاحب الامتياز وثيقة إفصاح قبل ١٤ يومًا على الأقل من توقيع الاتفاقية أو من أول دفعة مالية، أيهما أسبق، وتكون بالعربية واضحة ودقيقة. وما فيه في النظام فترة تراجع عامة بعد التوقيع، لكن لصاحب الامتياز حق إنهاء العقد بدون تعويض أو المطالبة بالتعويض إذا أخل المانح إخلالًا جوهريًا بالإفصاح أو التسجيل.','جهزوا وثيقة الإفصاح مع محامٍ مختص قبل أي تفاوض جدي: بيانات المانح، الوضع المالي، العلامة، الرسوم، الالتزامات، وأي قضايا. لا تأخذون أي عربون من مستثمرة قبل تسليمها الوثيقة ومرور المدة.','مستثمرة من الرياض تبغى تدفع مبلغ حجز للمنطقة؛ بيوتفريش تسلمها وثيقة الإفصاح أولًا وتنتظر المدة النظامية قبل أي دفعة أو توقيع.','سجل تاريخ تسليم الوثيقة وتاريخ التوقيع وأول دفعة لكل صاحبة امتياز.','مع أول مستثمرة جادة.','التأخر أو النقص في الإفصاح يعرض العقد للإنهاء والتعويض؛ هذا ملخص مو استشارة قانونية.',array['ksa-franchise-law']::text[],'law',array['وثيقة الإفصاح','نظام الامتياز','عقد','حماية قانونية']::text[],'rules',30) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-32','growth','تسجيل الاتفاقية والوثيقة إلزامي','يوجب النظام تسجيل اتفاقيات الامتياز ووثائق الإفصاح لدى وزارة التجارة، وتحدد اللائحة الإجراءات (وتذكر مكاتب قانونية أن المدة ٩٠ يومًا من التوقيع). وتصل الغرامة على المخالفات حتى ٥٠٠ ألف ريال. ويتناول النظام أيضًا التجديد (إشعار من صاحب الامتياز قبل ١٨٠ يومًا من الانتهاء ما لم ينص العقد على غير ذلك) ويمنع المانح خلال العقد من فتح نشاط مماثل في المنطقة المحددة.','اجعلوا التسجيل خطوة ضمن قائمة الإغلاق لكل عقد، وحددوا المنطقة الجغرافية بوضوح في العقد، وجهزوا تقويم لمواعيد التجديد.','بعد توقيع أول امتياز في الرياض، بيوتفريش تسجل العقد والوثيقة إلكترونيًا مباشرة وتحدد في العقد الأحياء المشمولة بالمنطقة.','حالة التسجيل لكل عقد، ومواعيد التجديد في تقويم الإدارة.','بعد كل توقيع، وقبل انتهاء أي عقد بستة أشهر على الأقل.','مسار التسجيل الإلكتروني ممكن يتغير (بعض المكاتب تذكر انتقاله لمنصة منشآت)؛ تأكدوا من الجهة الحالية وقت التسجيل.',array['ksa-franchise-law','monshaat-franchise']::text[],'law',array['تسجيل','وزارة التجارة','غرامات','تجديد','منطقة حصرية']::text[],'rules',31) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-33','growth','سجلوا العلامة قبل أي عقد امتياز','تسجيل العلامات في المملكة لدى الهيئة السعودية للملكية الفكرية وفق نظام العلامات الخليجي. وفي 2023 أبطلت المحكمة التجارية بالدمام (حكم ابتدائي) عقد امتياز لمقهى لأن المانح ما كان يملك العلامة وقت التعاقد، وسجلها بعد التوقيع، فاسترد صاحب الامتياز رسومه.','تأكدوا إن اسم «بيوتفريش» وشعاره مسجلين باسم الكيان المالك لدى الهيئة في الفئات المناسبة لخدمات التجميل والمنتجات إن وجدت. السجل التجاري وحده ما يكفي.','قبل التفاوض مع أي مستثمرة، بيوتفريش تراجع شهادة تسجيل العلامة وتتأكد إنها باسم الشركة اللي بتوقع العقد، مو باسم شريكة بصفتها الشخصية.','وجود شهادة تسجيل سارية لكل علامة وشعار مستخدم، وتطابق اسم المالك مع الطرف المانح في العقد.','الآن، لأن التسجيل ياخذ وقت، وقبل أي توسع أو امتياز.','الحكم ابتدائي وقابل للاستئناف حسب التحليل المنشور، لكنه يوضح كيف ممكن تفسر المحاكم شرط ملكية العلامة.',array['saip-trademark','dammam-court-2023','ksa-franchise-law']::text[],'law',array['علامة تجارية','الملكية الفكرية','تسجيل','حماية الاسم','امتياز']::text[],'rules',32) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-34','growth','صمموا الإتاوة بعناية لأنها نادرًا تتغير','وجدت دراسة Lafontaine وShaw على قرابة ألف مانح امتياز أن الإتاوات ورسوم الامتياز نادرًا ما تتعدل بعد تحديدها، ولما تتعدل ما تمشي باتجاه ثابت. فالقرار الأول للهيكل يدوم طويلًا.','الممارسة الشائعة: رسم دخول عند التوقيع، وإتاوة دورية مربوطة غالبًا بالإيراد، وأحيانًا مساهمة في صندوق تسويق. احسبوا الهيكل من أرقامكم: هل يبقى لصاحبة الامتياز ربح معقول بعد الإيجار والرواتب والإتاوة؟','بيوتفريش تبني نموذج مالي لفرع امتياز افتراضي من أرقام فرعيها الفعلية، وتجرب عدة هياكل للإتاوة قبل تثبيت واحد في وثيقة الإفصاح.','ربح صاحبة الامتياز المتوقع بعد الإتاوة، وفترة استرداد استثمارها، مقارنة بأرقام الفروع الفعلية.','عند إعداد وثيقة الإفصاح ونموذج الامتياز.','لا توجد نسبة إتاوة «قياسية» يُعتمد عليها؛ أي نسبة تسمعونها هي ممارسة سلسلة معينة. وفي حال الاستثناء من شرط الخبرة، يشترط القرار عدم أخذ رسوم قبل بدء التشغيل.',array['lafontaine-shaw','ksa-franchise-exemption']::text[],'evidence',array['إتاوة','رسوم الامتياز','نموذج مالي','صندوق تسويق']::text[],'finance',33) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_principles (id,domain,title,idea,salon,example,measure,"when",caution,sources,strength,tags,go,ord) values ('grw-35','growth','مطوّرة منطقة أو صاحبة فرع واحد','تبيّن أبحاث تملّك الوحدات المتعددة أن السلاسل تميل لإعطاء الوحدات الجديدة لأصحاب امتياز قائمين قريبين جغرافيًا ومثبتين، بدل توزيعها على ملاك جدد. ومنشآت تدعم القطاع بمنصة الامتياز وجولات في المناطق، منها جولة الأحساء في ديسمبر 2025 بورش واستشارات وجهات تمويل.','البداية الآمنة غالبًا بصاحبة فرع واحد تثبت النموذج، ثم إعطاء الفروع الإضافية في نفس المنطقة لمن نجحت فيها. مطوّرة منطقة تلتزم بعدة فروع تسرّع التوسع لكنها تحتاج نظام إشراف ونموذج قوي من البداية.','أول صاحبة امتياز في الرياض تفتح فرع واحد؛ إذا حققت معايير التدقيق والأرقام لسنة، تُعطى أولوية الفرع الثاني في نفس المدينة.','أداء كل صاحبة امتياز (التدقيق، التقييمات، الإيراد) قبل منح فرع إضافي.','عند تصميم هيكل الامتياز ووثيقة الإفصاح، وعند التواصل مع مركز الامتياز في منشآت.','الدراسة على الوجبات السريعة في أمريكا؛ وأي صلاحيات لمطوّرة منطقة أو امتياز رئيسي لها أحكام خاصة في النظام السعودي، فراجعوها مع محامٍ.',array['kalnins-lafontaine','monshaat-franchise','ksa-franchise-law']::text[],'evidence',array['مطور منطقة','امتياز رئيسي','فرع واحد','منشآت','الأحساء']::text[],'rules',34) on conflict (id) do update set domain=excluded.domain,title=excluded.title,idea=excluded.idea,salon=excluded.salon,example=excluded.example,measure=excluded.measure,"when"=excluded."when",caution=excluded.caution,sources=excluded.sources,strength=excluded.strength,tags=excluded.tags,go=excluded.go,ord=excluded.ord,updated_at=now();
insert into public.kb_cautions (domain,text) values ('marketing','«٧٠٪ (أو ٩٥٪) من قرارات الشراء عاطفية أو لا واعية»: أرقام شائعة بلا أصل بحثي واضح، لا تُستخدم.');
insert into public.kb_cautions (domain,text) values ('marketing','«العميلة تحتاج ٧ تعرضات قبل الشراء» (قاعدة السبعة): قاعدة متداولة بدون دراسة أصلية موثوقة.');
insert into public.kb_cautions (domain,text) values ('marketing','نسبة ٦٠:٤٠ بين بناء العلامة والتنشيط: متوسط من بيانات Binet وField لعلامات كبيرة، وليست قاعدة ثابتة لصالون مستقل.');
insert into public.kb_cautions (domain,text) values ('marketing','أرقام مركز Spiegel (مثل ارتفاع الشراء مع أول خمس مراجعات) من تجارة إلكترونية لمنتجات، وأرقام Luca من مطاعم في سياتل، وأرقام Schmitt من بنك ألماني: الاتجاه مفيد، لكن لا تُنقل كنسب متوقعة للصالون.');
insert into public.kb_cautions (domain,text) values ('marketing','شراء المتابعين أو التقييمات أو تقييمات الموظفات وأقاربهن: مخالف لسياسات قوقل ويضر الثقة، ويُعدّ في أنظمة عدة تضليلًا للمستهلك.');
insert into public.kb_cautions (domain,text) values ('marketing','«الولاء أهم من الجذب» و«الجذب أهم من الولاء»: الخلاف بين المدارس حقيقي؛ احكموا بأرقام رجوع العميلات ونسبة الجدد عندكم.');
insert into public.kb_cautions (domain,text) values ('marketing','غرامات «موثوق» والتخفيضات المنتشرة في الأخبار والحسابات: لا تعتمدون عليها؛ ارجعوا للهيئة العامة لتنظيم الإعلام ووزارة التجارة مباشرة.');
insert into public.kb_cautions (domain,text) values ('sales','Dan Ariely: بحث شارك فيه عن التوقيع في بداية النموذج والصدق (PNAS 2012) سُحب في 2021 بعد اكتشاف بيانات مفبركة في التجربة الميدانية. هذا لا يُسقط كل أعماله، لكن تعاملوا مع أمثلة Predictably Irrational كأفكار للاختبار لا حقائق مثبتة.');
insert into public.kb_cautions (domain,text) values ('sales','تأثير الخيار الطُعم (Decoy): مثال اشتراك المجلة المشهور مثير، لكن أبحاث لاحقة (Frederick وزملاؤه 2014) وجدت التأثير ضعيف أو غائب في مواقف كثيرة أقرب للواقع.');
insert into public.kb_cautions (domain,text) values ('sales','النفور من الخسارة: عبارة «الخسارة تؤلم ضعف المكسب» تُنقل كرقم ثابت، والواقع أن حجمه يختلف حسب الموقف، وفيه نقد علمي جاد (Gal وRucker 2018). استخدموا الفكرة بدون رقم.');
insert into public.kb_cautions (domain,text) values ('sales','«السعر المنتهي بـ 9 يرفع المبيعات دائمًا»: الأدلة تقول إن الأثر موجود في سياقات معينة وأقوى للمنتجات الجديدة، وقد يضر صورة الخدمات الفاخرة.');
insert into public.kb_cautions (domain,text) values ('sales','دراسة إزالة رمز العملة من القائمة: دراسة وحدة في مطعم واحد بعينة صغيرة؛ لا تُنقل كقاعدة مضمونة ولا بنسبة زيادة محددة.');
insert into public.kb_cautions (domain,text) values ('sales','Alex Hormozi وأطر «العروض التي لا تُرفض»: ممارسة مفيدة لتنظيم التفكير، لكنها ليست بحثًا محكّمًا، وبعض أساليبها (الضمانات المبالغ فيها، الإلحاح الزمني المصطنع) قد تخالف ضوابط الإعلان وحماية المستهلك.');
insert into public.kb_cautions (domain,text) values ('sales','أرقام شائعة مثل «جذب عميل جديد يكلف خمس أضعاف الاحتفاظ بعميل» أو «المنتجات لازم تكون نسبة كذا من إيراد الصالون»: تتداول بدون مصدر محدد قابل للتحقق في هذا السياق؛ لا تُستخدم، والقياس يكون من بيانات الصالون.');
insert into public.kb_cautions (domain,text) values ('sales','The Challenger Sale وSPIN Selling: مبنيان على أبحاث شركات استشارية (CEB وHuthwaite) في بيع الشركات، وليست دراسات محكّمة على خدمات التجميل؛ تُستخدم كممارسة مهنية مع التكييف.');
insert into public.kb_cautions (domain,text) values ('experience','«العميلة الزعلانة تخبر عشرة والراضية تخبر ثلاثة» وأمثالها: أرقام تنتشر بدون أصل واضح قابل للتحقق؛ لا تُستخدم.');
insert into public.kb_cautions (domain,text) values ('experience','«جذب عميلة جديدة يكلف خمس أضعاف الاحتفاظ بالحالية»: نسبة شائعة بدون مصدر موحد مؤكد؛ الفكرة العامة معقولة لكن احسبوا تكلفتكم من بياناتكم.');
insert into public.kb_cautions (domain,text) values ('experience','أرقام أثر رفع الاحتفاظ على الربح المنسوبة لـ Bain/رايكهيلد: جاية من قطاعات ودراسات محددة، ولا تنطبق تلقائيًا على صالون.');
insert into public.kb_cautions (domain,text) values ('experience','مفارقة التعافي: تنتشر كأن الخطأ مع حله أفضل من عدم الخطأ؛ التحليل التجميعي (de Matos 2007) أثبتها للرضا فقط، مو للرجوع أو التوصية.');
insert into public.kb_cautions (domain,text) values ('experience','NPS كـ«الرقم الوحيد»: النقد المحكّم ما لقى له تفوق في التنبؤ بالنمو؛ يُستخدم مع مؤشرات سلوكية.');
insert into public.kb_cautions (domain,text) values ('experience','الاعتذار وحده: تجربة ميدانية كبيرة على تطبيق نقل (Halperin وزملاؤه، NBER) لقت إن الاعتذار بدون تعويض ملموس ممكن ما ينفع أو يضر، وخاصة إذا تكرر.');
insert into public.kb_cautions (domain,text) values ('experience','شراء التقييمات أو ربطها بهدايا أو إرسال رابط التقييم للراضيات فقط: مخالف لسياسة قوقل ويعرّض التقييمات للحذف والملف للقيود.');
insert into public.kb_cautions (domain,text) values ('operations','أرقام فشل المشاريع الصغيرة المتداولة (مثل «٨٠٪ تفشل خلال خمس سنوات») ما لها مصدر إحصائي واحد موثوق، فلا تُستخدم لتبرير أي قرار.');
insert into public.kb_cautions (domain,text) values ('operations','نتائج دراسة قائمة التحقق الجراحية (Haynes 2009) جاءت من مقارنة قبل وبعد في مستشفيات، فلا تُنقل نسبها للصالون كوعود. الدرس هو المنهج، مو الرقم.');
insert into public.kb_cautions (domain,text) values ('operations','نسب الحضور في مراجعة Cochrane عن رسائل التذكير مأخوذة من مواعيد صحية ودرجة اليقين فيها منخفضة إلى متوسطة. قيسوا أثر التذكير على أرقام بيوتفريش نفسها.');
insert into public.kb_cautions (domain,text) values ('operations','عبارة «خالي من الفورمالديهايد» على منتجات البروتين ما تعني إن المنتج آمن بالضرورة، حسب OSHA. اقرؤوا صحيفة بيانات السلامة وتأكدوا من إدراج المنتج لدى الهيئة.');
insert into public.kb_cautions (domain,text) values ('operations','الاسم الرسمي للنظام السعودي هو «نظام منتجات التجميل»، وليس «نظام مستحضرات التجميل».');
insert into public.kb_cautions (domain,text) values ('operations','لائحة المشاغل النسائية لعام 2015 تحدّثت باشتراطات وزارة البلديات والإسكان في 2025. أي بند من اللائحة القديمة يُطابَق مع النص الحالي في منصة بلدي قبل الاعتماد عليه.');
insert into public.kb_cautions (domain,text) values ('operations','دليل الهيئة الملكية للعلا مفيد للتفاصيل، لكنه صادر لنطاق العلا. الأرقام فيه (حرارة الماء، عدد أجهزة التعقيم، مدة حفظ التسجيل) تُطابَق مع أمانة الأحساء.');
insert into public.kb_cautions (domain,text) values ('operations','لا تُذكر غرامات أو أرقام مواد نظامية في نصائح الموقع إلا من جدول المخالفات أو النص الرسمي نفسه.');
insert into public.kb_cautions (domain,text) values ('operations','فكرة إن كل موظفة لازم يكون جدولها ممتلئ ١٠٠٪ تخالف نظرية القيود؛ الامتلاء الكامل مطلوب عند القيد فقط.');
insert into public.kb_cautions (domain,text) values ('operations','نسبة «٢٠٪ من الأصناف = ٨٠٪ من القيمة» في المخزون تقريب شائع وليست قاعدة؛ احسبوا التوزيع من بيانات الصالون.');
insert into public.kb_cautions (domain,text) values ('people','عبارات ونسب شائعة عن الموظفين (مثل «الناس يتركون المدير مو الشركة» مع نسبة محددة) تنتشر بدون مصدر أصلي واضح؛ لا تُستخدم كرقم أو اقتباس إلا إذا رجعنا للدراسة نفسها.');
insert into public.kb_cautions (domain,text) values ('people','نسب العمولة والرواتب المتداولة (مثل ٥٠٪ أو ٦٠/٤٠ أو «رواتب الخدمة يجب ألا تتجاوز نسبة كذا من الإيراد») مصدرها ممارسة السوق الأمريكي ومكاتب تدريب تبيع خدماتها؛ ما تنطبق مباشرة على الأحساء. احسبوها من أرقامكم.');
insert into public.kb_cautions (domain,text) values ('people','فكرة «المال ما يحفز» مبالغ فيها في المحتوى الشعبي؛ الأبحاث تقول إن أثر المكافأة يعتمد على نوع المهمة وطريقة المكافأة، والأجر العادل نفسه أساس.');
insert into public.kb_cautions (domain,text) values ('people','نظرية Herzberg وهرم Lencioni ومخطط EOS أدوات مفيدة لكنها ليست نتائج تجريبية مثبتة بنفس قوة أبحاث تحديد الأهداف أو نظرية تقرير المصير.');
insert into public.kb_cautions (domain,text) values ('people','أي معلومة عن نظام العمل أو التوطين منقولة من مواقع غير رسمية أو مكاتب محاماة تحتاج تأكيد من موقع وزارة الموارد البشرية أو منصة قوى، لأن الأنظمة عُدّلت في السنوات الأخيرة.');
insert into public.kb_cautions (domain,text) values ('growth','تاريخ نظام الامتياز التجاري هو 1441هـ (2019م) بالمرسوم الملكي م/22، مو 1440هـ كما يتداول أحيانًا.');
insert into public.kb_cautions (domain,text) values ('growth','لا توجد في نظام الامتياز السعودي فترة تراجع (cooling-off) عامة بعد التوقيع؛ الحماية الأساسية هي مهلة الـ١٤ يوم للإفصاح وحق الإنهاء عند الإخلال الجوهري بالإفصاح أو التسجيل.');
insert into public.kb_cautions (domain,text) values ('growth','الشائع إن «فرع واحد ناجح يكفي للامتياز» غير صحيح نظاميًا في المملكة: الشرط سنة تشغيل في نقطتي بيع أو بشخصين على الأقل، والاستثناءات لقطاعات محددة بقرار وشروط.');
insert into public.kb_cautions (domain,text) values ('growth','أي «نسبة إتاوة قياسية» للصالونات تنتشر في المواقع ليس لها أصل موثوق؛ الهيكل يُبنى من أرقام الفروع الفعلية.');
insert into public.kb_cautions (domain,text) values ('growth','رقم ١١٫١٪ (أثر تحسين السعر ١٪) متوسط لشركات أمريكية متنوعة في دراسة 1992، وما ينطبق حرفيًا على صالون؛ احسبوا الأثر من هامشكم.');
insert into public.kb_cautions (domain,text) values ('growth','أيام الاحتياطي (٢٧ يومًا للمنشأة الوسيطة و٢١ للخدمات الشخصية) بيانات أمريكية من 2015 تصف الواقع ولا تحدد هدفًا مثاليًا.');
insert into public.kb_cautions (domain,text) values ('growth','بعض الشركات اللي وصفها Good to Great بالعظيمة تعثرت لاحقًا، والكتاب انتُقد منهجيًا؛ لا يُستخدم كدليل سببي.');
insert into public.kb_cautions (domain,text) values ('growth','أمثلة المحيط الأزرق ودراسات النجاح عمومًا مختارة بأثر رجعي (تأثير الهالة)؛ تقليد شركة ناجحة لا يضمن النجاح.');
insert into public.kb_cautions (domain,text) values ('growth','أرقام شائعة مثل «أغلب المشاريع الصغيرة تفشل في أول سنة» أو «الامتياز أقل خطرًا بنسبة كذا» تتداول بدون مصدر محدد؛ لا تُستخدم.');
